xt[]:=array[''public.user_profiles''];begin\n -- Exact approved full application delta; unknown unlinked application tables\n -- also fail closed. Managed namespace checks remain the original fixed helper.\n if not result_data_private.infrastructure_supported_v1() or profile_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object(''relation'',n.nspname||''.''||c.relname,''columns'',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),''constraints'',(select jsonb_agg(pg_get_constraintdef(k.oid) order by k.conname) from pg_constraint k where k.conrelid=c.oid)) order by n.nspname,c.relname),''[]''::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind=''r'' and n.nspname not in(''pg_catalog'',''information_schema'',''extensions'',''auth'',''result_data_private'',''storage'',''realtime'',''_realtime'',''vault'',''supabase_functions'',''supabase_migrations''))::text)<> ''01fd3fb6beadf36bf1d9091593c3adf89dfbbabd32256cc66cf2a0426c82249e'' then return false;end if;\n for r in select * from profile_data_private.sources_v1() loop names:=names||r.relation_name;end loop;\n expected:=''{\"public.turns\":{\"columns\":[[\"id\",\"uuid\",true],[\"owner_id\",\"uuid\",true],[\"trip_id\",\"uuid\",false],[\"status\",\"text\",true],[\"created_at\",\"timestamp with time zone\",true],[\"thread_id\",\"uuid\",false],[\"updated_at\",\"timestamp with time zone\",true]],\"constraints\":[\"UNIQUE (id, owner_id)\",\"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE\",\"PRIMARY KEY (id)\",\"CHECK ((status = ANY (ARRAY[''''accepted''''::text, ''''planning''''::text, ''''retrieving''''::text, ''''generating''''::text, ''''validating''''::text, ''''completed''''::text, ''''proposal_ready''''::text, ''''unavailable''''::text, ''''failed''''::text, ''''cancelled''''::text])))\",\"FOREIGN KEY (thread_id) REFERENCES public.chat_threads(id) ON DELETE CASCADE\",\"FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE SET NULL\"]},\"turn_private.work\":{\"columns\":[[\"turn_id\",\"uuid\",true],[\"owner_id\",\"uuid\",true],[\"session_id\",\"uuid\",true],[\"state\",\"text\",true],[\"attempt\",\"integer\",true],[\"max_attempts\",\"integer\",true],[\"lease_ms\",\"integer\",true],[\"lease_token\",\"uuid\",false],[\"expires_at\",\"timestamp with time zone\",false],[\"created_at\",\"timestamp with time zone\",true],[\"execution_mode\",\"text\",true]],\"constraints\":[\"CHECK (((attempt >= 0) AND (attempt <= 5)))\",\"CHECK (((state = ''''leased''''::text) = ((lease_token IS NOT NULL) AND (expires_at IS NOT NULL))))\",\"CHECK (((state = ''''leased''''::text) OR ((lease_token IS NULL) AND (expires_at IS NULL))))\",\"CHECK ((execution_mode = ANY (ARRAY[''''text''''::text, ''''planning_comparison_v1''''::text, ''''planning_intake_comparison_v2''''::text, ''''scoped_trip_edit_v1''''::text])))\",\"CHECK (((lease_ms >= 1000) AND (lease_ms <= 300000)))\",\"CHECK (((max_attempts >= 1) AND (max_attempts <= 5)))\",\"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE\",\"PRIMARY KEY (turn_id)\",\"CHECK ((state = ANY (ARRAY[''''queued''''::text, ''''leased''''::text, ''''completed''''::text, ''''failed''''::text, ''''cancelled''''::text, ''''quarantined''''::text])))\",\"FOREIGN KEY (turn_id) REFERENCES public.turns(id) ON DELETE CASCADE\"]},\"public.user_profiles\":{\"columns\":[[\"owner_id\",\"uuid\",true],[\"display_name\",\"text\",false],[\"travel_pace\",\"text\",true],[\"locale\",\"text\",true],[\"currency\",\"text\",true],[\"distance_unit\",\"text\",true],[\"temperature_unit\",\"text\",true],[\"default_departure_time\",\"time without time zone\",true],[\"created_at\",\"timestamp with time zone\",true],[\"updated_at\",\"timestamp with time zone\",true],[\"pace_revision\",\"bigint\",true],[\"pace_state\",\"text\",true],[\"pace_notice\",\"text\",false],[\"pace_oper