sonb_build_object(''kind'',''stale'');\n  end if;\n  if p_outcome=''provider_failure'' and w.attempt<w.max_attempts then\n    update turn_private.work set state=''queued'',lease_token=null,expires_at=null where turn_id=w.turn_id;\n    return jsonb_build_object(''kind'',''queued'');\n  end if;\n  perform turn_private.terminal(w.turn_id,case p_outcome when ''completed'' then ''completed'' when ''validation_failure'' then ''failed'' else ''quarantined'' end,w.attempt);\n  return jsonb_build_object(''kind'',''finished'');\nend ","result":"jsonb","strict":false,"identity":"p_turn_id uuid, p_lease_token uuid, p_outcome text","language":"plpgsql","parallel":"u","arguments":"p_turn_id uuid, p_lease_token uuid, p_outcome text","definition":"CREATE OR REPLACE FUNCTION public.finish_turn_work(p_turn_id uuid, p_lease_token uuid, p_outcome text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare w turn_private.work%rowtype; turn_state text;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode=''planning_intake_comparison_v2'') then return jsonb_build_object(''kind'',''stale''); end if;\n  if p_outcome is null or p_outcome not in (''completed'',''provider_failure'',''validation_failure'') then raise exception ''INVALID_INPUT''; end if;\n  select * into w from turn_private.work where turn_id=p_turn_id;\n  if not found or p_lease_token is null then return jsonb_build_object(''kind'',''stale''); end if;\n  if not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object(''kind'',''unavailable''); end if;\n  select * into w from turn_private.work where turn_id=p_turn_id for update;\n  if not found or w.state<>''leased'' or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp() then return jsonb_build_object(''kind'',''stale''); end if;\n  select status into turn_state from public.turns where id=w.turn_id;\n  if turn_state in (''completed'',''proposal_ready'',''unavailable'',''failed'',''cancelled'') then\n    perform turn_private.terminal(w.turn_id,''cancelled'',w.attempt);\n    return jsonb_build_object(''kind'',''stale'');\n  end if;\n  if p_outcome=''provider_failure'' and w.attempt<w.max_attempts then\n    update turn_private.work set state=''queued'',lease_token=null,expires_at=null where turn_id=w.turn_id;\n    return jsonb_build_object(''kind'',''queued'');\n  end if;\n  perform turn_private.terminal(w.turn_id,case p_outcome when ''completed'' then ''completed'' when ''validation_failure'' then ''failed'' else ''quarantined'' end,w.attempt);\n  return jsonb_build_object(''kind'',''finished'');\nend $function$\n","volatility":"v","securityDefiner":true},"turn_data_private.schema_supported_v1()":{"acl":"{postgres=X/postgres}","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare actual_n jsonb;s record;pk_n text[];\nbegin\n for s in select * from turn_data_private.sources_v1() loop\n  if to_regclass(s.relation_name) is null then return false;end if;\n  select jsonb_agg(jsonb_build_object(''name'',a.attname,''type'',format_type(a.atttypid,a.atttypmod),''notNull'',a.attnotnull) order by a.attnum) into actual_n from pg_attribute a where a.attrelid=s.relation_name::regclass and a.attnum>0 and not a.attisdropped;\n  if actual_n is distinct from (''{\"public.chat_turn_events\":[{\"name\":\"id\",\"type\":\"uuid\",\"notNull\":true},{\"name\":\"owner_id\",\"type\":\"uuid\",\"notNull\":true},{\"name\":\"thread_id\",\"type\":\"uuid\",\"notNull\":true},{\"name\":\"turn_id\",\"type\":\"uuid\",\"notNull\":true},{\"name\":\"event_id\",\"type\":\"text\",\"notNull\":true},{\"name\":\"sequence\",\"type\":\"integer\",\"notNull\":true},{\"name\":\"schema_version\",\"type\":\"text\",\"notNull\":true},{\"name\":\"event_type\",\"type\":\"text\",\"notNull\":true},{\"name\":\"state\",\"type\":\"text\",\"notNull\":true},{\"name\":\"created_at\",\"type\":\"timestamp with time zone\",\"notNull