end $$;

create function turn_private.directions_strings_v1(v jsonb,max_items integer,max_text integer)
returns boolean language plpgsql immutable set search_path='' as $$
declare s jsonb;
begin
 if jsonb_typeof(v) is distinct from 'array' or jsonb_array_length(v)>max_items then return false;end if;
 if (select count(*) from jsonb_array_elements(v))<>(select count(distinct value) from jsonb_array_elements(v)) then return false;end if;
 for s in select value from jsonb_array_elements(v) loop
  if not turn_private.directions_text_v1(s,max_text) then return false;end if;
 end loop;return true;
end $$;

create function turn_private.valid_directions_intake_v1(v jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare b jsonb;d jsonb;first_n date;last_n date;days_n integer;
begin
 if not turn_private.directions_exact_v1(v,array['schemaVersion','destinations','durationDays','interests','currentPace','budget','dates','intent'])
  or v->>'schemaVersion' is distinct from 'travel-directions-intake/1'
  or not turn_private.directions_strings_v1(v->'destinations',30,80)
  or not turn_private.directions_strings_v1(v->'interests',8,40)
  or (v->'durationDays'<>'null'::jsonb and (not turn_private.result_int_v2(v->'durationDays') or (v->>'durationDays')::numeric>30))
  or (v->'currentPace'<>'null'::jsonb and (jsonb_typeof(v->'currentPace')<>'string' or v->>'currentPace' not in('relaxed','balanced','packed')))
  or jsonb_typeof(v->'intent') is distinct from 'string' or v->>'intent' not in('explore','specific') then return false;end if;
 b:=v->'budget';
 if b<>'null'::jsonb then
  if not turn_private.directions_exact_v1(b,array['currency','totalMinorUnits'])
   or jsonb_typeof(b->'currency') is distinct from 'string' or b->>'currency' not in('CNY','USD','EUR','GBP')
   or not turn_private.result_int_v2(b->'totalMinorUnits') or (b->>'totalMinorUnits')::numeric>10000000 then return false;end if;
 end if;
 d:=v->'dates';
 if d<>'null'::jsonb then
  if not turn_private.directions_exact_v1(d,array['startDate','endDate'])
   or jsonb_typeof(d->'startDate') is distinct from 'string' or jsonb_typeof(d->'endDate') is distinct from 'string'
   or d->>'startDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or d->>'endDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return false;end if;
  first_n:=(d->>'startDate')::date;last_n:=(d->>'endDate')::date;days_n:=last_n-first_n+1;
  if first_n::text<>d->>'startDate' or last_n::text<>d->>'endDate' or days_n not between 1 and 30
   or v->'durationDays' is distinct from to_jsonb(days_n) then return false;end if;
 end if;
 return true;
exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then return false;
end $$;

create function turn_private.valid_directions_relative_v1(v jsonb,intake_n jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare expected_n integer;row_n jsonb;ordinal_n integer:=0;
begin
 if not turn_private.valid_directions_intake_v1(intake_n)
  or not turn_private.directions_exact_v1(v,array['directionId','requestedDays','days','coverage','limitations','pace','paceSource'])
  or jsonb_typeof(v->'directionId') is distinct from 'string' or v->>'directionId' not in('depth','breadth')
  or v->'requestedDays' is distinct from intake_n->'durationDays'
  or jsonb_typeof(v->'days') is distinct from 'array' or jsonb_array_length(v->'days')>30
  or jsonb_typeof(v->'coverage') is distinct from 'string' or v->>'coverage' not in('complete_relative','partial_relative')
  or not turn_private.directions_strings_v1(v->'limitations',10,3000) or jsonb_array_length(v->'limitations')=0
  or jsonb_typeof(v->'paceSource') is distinct from 'string' or v->>'paceSource' not in('current_input','profile','none')
  or (v->'pace'<>'null'::jsonb and (jsonb_typeof(v->'pace')<>'string' or v->>'pace' not in('relaxed','balanced','packed')))
  or (v->'pace'='null'::jsonb and v->>'paceSource'<>'none')
  or (v->'pace'<>'null'::jsonb and v->>'paceSource'='none') then return false;end if;
 if intake_n->'currentPace'<>'null'::jsonb then
  if v->'pace' is distinct from intake_n->'currentPace' or v->>'paceSource'<>'current_input' then return false;end if;
 elsif v->>'paceSource'='current_input' then return false;end if;
 expected_n:=case when intake_n->'durationDays'<>'null'::jsonb and jsonb_array_length(intake_n->'destinations')>0 then (intake_n->>'durationDays')::integer else 0 end;
 if jsonb_array_length(v->'days')<>expected_n
  or v->>'coverage'<>(case when expected_n>0 and jsonb_array_length(intake_n->'destinations')<=expected_n then 'complete_relative' else 'partial_relative' end) then return false;end if;
 for row_n in select value from jsonb_array_elements(v->'days') loop
  ordinal_n:=ordinal_n+1;
  if not turn_private.directions_exact_v1(row_n,array['ordinal','destination','activities'])
   or row_n->'ordinal' is distinct from to_jsonb(ordinal_n)
   or not turn_private.directions_text_v1(row_n->'destination',80)
   or not turn_private.directions_strings_v1(row_n->'activities',8,160) or jsonb_array_length(row_n->'activities')=0 then return false;end if;
 end loop;
 return true;
exception when invalid_text_representation or numeric_value_out_of_range then return false;
end $$;

create function turn_private.valid_travel_directions_v1(v jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare d jsonb;ids_n text[]:=array[]::text[];count_n integer;
begin
 if not turn_private.directions_exact_v1(v,array['schemaVersion','title','summary','intake','directions','selectedDirectionId','draft','actions'])
  or v->>'schemaVersion' is distinct from 'travel-directions/1' or v->'actions' is distinct from '[]'::jsonb
  or octet_length(v::text)>65536 or not turn_private.directions_text_v1(v->'title',120)
  or not turn_private.directions_text_v1(v->'summary',1000) or not turn_private.valid_directions_intake_v1(v->'intake')
  or jsonb_typeof(v->'directions') is distinct from 'array' or jsonb_array_length(v->'directions') not between 1 and 2 then return false;end if;
 count_n:=jsonb_array_length(v->'directions');
 if count_n<>(case when v->'intake'->>'intent'='specific' then 1 else 2 end) then return false;end if;
 for d in select value from jsonb_array_elements(v->'directions') loop
  if not turn_private.directions_exact_v1(d,array['id','title','tradeoff'])
   or jsonb_typeof(d->'id') is distinct from 'string' or d->>'id' not in('depth','breadth') or d->>'id'=any(ids_n)
   or not turn_private.directions_text_v1(d->'title',120) or not turn_private.directions_text_v1(d->'tradeoff',500) then return false;end if;
  ids_n:=ids_n||array[d->>'id'];
 end loop;
 if v->'selectedDirectionId'<>'null'::jsonb and (jsonb_typeof(v->'selectedDirectionId')<>'string' or not(v->>'selectedDirectionId'=any(ids_n))) then return false;end if;
 if v->'draft'<>'null'::jsonb and (v->'selectedDirectionId'='null'::jsonb or not turn_private.valid_directions_relative_v1(v->'draft',v->'intake')
  or v->'draft'->'directionId' is distinct from v->'selectedDirectionId') then return false;end if;
 return true;
end $$;

