 request_bytes_digest text not null check(request_bytes_digest ~ '^[a-f0-9]{64}$'),
 intake jsonb not null check(turn_private.valid_directions_intake_v1(intake)),
 memory_basis jsonb not null check(jsonb_typeof(memory_basis)='array' and jsonb_array_length(memory_basis)<=3),
