 unique(owner_id,idempotency_key),unique(goal_id,intake_revision)
);
create index directions_intake_goal_current_v1 on turn_private.assistant_directions_intakes_v1(goal_id,intake_revision desc);
create index directions_intake_owner_export_v1 on turn_private.assistant_directions_intakes_v1(owner_id,message_id);

-- The original result is published in the same transaction after real Task
-- terminal output. Deferred artifact FK permits validation before first insert.
create table turn_private.directions_result_sources_v1 (
 artifact_id uuid primary key references turn_private.result_artifacts(id) on delete cascade deferrable initially deferred,
 owner_id uuid not null references auth.users(id) on delete cascade,
 message_id uuid not null unique references turn_private.assistant_directions_intakes_v1(message_id) on delete cascade,
 task_turn_id uuid not null unique references turn_private.text_content(turn_id) on delete cascade,
 source_digest text not null check(source_digest ~ '^[a-f0-9]{64}$'),
 initial_content_digest text not null check(initial_content_digest ~ '^[a-f0-9]{64}$'),
 initial_output_digest text not null check(initial_output_digest ~ '^[a-f0-9]{64}$'),
 previous_artifact_id uuid references turn_private.result_artifacts(id) on delete cascade,
 previous_revision integer check(previous_revision between 1 and 1000),
 publication_key uuid not null unique,
 created_at timestamptz not null default clock_timestamp(),
 check((previous_artifact_id is null)=(previous_revision is null)),
 check(previous_artifact_id is distinct from artifact_id)
);

-- Purpose-specific action receipt, not a new general Result/Task/planner store.
-- Source identities and display-bearing receipt are scrubbed only by original
-- proof-bound privacy handlers; owner/session/action/exact-byte replay fence stay.
-- No artifact/proposal FK cascade can delete the permanent replay fence.
create table turn_private.directions_operations_v1 (
 operation_id uuid not null,
 owner_id uuid not null references auth.users(id) on delete cascade,
 session_id uuid not null,
 action text not null check(action in('choose','save','edit','bind')),
 request_bytes_digest text not null check(request_bytes_digest ~ '^[a-f0-9]{64}$'),
 erased boolean not null default false,
 artifact_id uuid,
 source_message_id uuid,
 task_turn_id uuid,
 expected_revision integer,
 result_revision integer,
 source_digest text,
 output_content_digest text,
 trip_id uuid,
 proposal_id uuid,
 proposal_artifact_id uuid,
 receipt jsonb,
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,operation_id),
 check(coalesce((erased and artifact_id is null and source_message_id is null and task_turn_id is null and expected_revision is null and result_revision is null and source_digest is null and output_content_digest is null and trip_id is null and proposal_id is null and proposal_artifact_id is null and receipt is null)
  or (not erased and artifact_id is not null and source_message_id is not null and task_turn_id is not null
   and expected_revision between 1 and 1000 and result_revision between 1 and 1000
   and source_digest ~ '^[a-f0-9]{64}$' and jsonb_typeof(receipt)='object'
   and (action='bind' and result_revision=expected_revision and output_content_digest is null and trip_id is not null and proposal_id is not null and proposal_artifact_id is not null
    or action<>'bind' and expected_revision<1000 and result_revision=expected_revision+1 and output_content_digest ~ '^[a-f0-9]{64}$' and trip_id is null and proposal_id is null and proposal_artifact_id is null)),false))
);
create index directions_operation_artifact_v1 on turn_private.directions_operations_v1(owner_id,artifact_id) where not erased;

alter table turn_private.assistant_directions_intakes_v1 enable row level security;
alter table turn_private.directions_result_sources_v1 enable row level security;
alter table turn_private.directions_operations_v1 enable row level security;
revoke all on turn_private.assistant_directions_intakes_v1,turn_private.directions_result_sources_v1,
 turn_private.directions_operations_v1 from public,anon,authenticated,service_role;

create function turn_private.immutable_directions_source_v1() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 -- DELETE follows original qualified parent/account/private erasure contracts;
 -- existing source fences on all three relations are required, not optional.
 if TG_OP='UPDATE' then raise exception 'IMMUTABLE_DIRECTIONS_SOURCE';end if;
 return OLD;
end $$;
create trigger immutable_directions_intake_v1 before update on turn_private.assistant_directions_intakes_v1
 for each row execute function turn_private.immutable_directions_source_v1();
create trigger immutable_directions_result_source_v1 before update on turn_private.directions_result_sources_v1
 for each row execute function turn_private.immutable_directions_source_v1();
revoke all on function turn_private.immutable_directions_source_v1() from public,anon,authenticated,service_role;

-- Required still-unwritten exact constituents:
-- operation immutable/proof-bound scrub/accountGone guard; all original Result,
-- Conversation, Turn and linked-parent fences; qualified export revision hook;
