-- Constituent: history-source.candidate.sql
-- ARTIFACT ONLY. Private original-owner historical qualification, not a public
-- read API or current-source exception. Iterative bounded provenance avoids
-- recursive public RPC calls from service-owned export/publication contexts.
create function turn_private.directions_history_readable_v1(u uuid,artifact_n uuid,revision_n integer,goal_n uuid)
returns boolean language plpgsql security definer set search_path='' as $$
declare a turn_private.result_artifacts%rowtype;r turn_private.result_revisions%rowtype;
 s turn_private.directions_result_sources_v1%rowtype;i turn_private.assistant_directions_intakes_v1%rowtype;
 seen_n uuid[]:=array[]::uuid[];bytes_n bigint:=0;content_n text;state_n jsonb;
 next_artifact_n uuid:=artifact_n;next_revision_n integer:=revision_n;
begin
 if u is null or goal_n is null or next_artifact_n is null or next_revision_n not between 1 and 1000 then return false;end if;
 while next_artifact_n is not null loop
  if next_artifact_n=any(seen_n) or cardinality(seen_n)>=4100 then return false;end if;
  seen_n:=seen_n||array[next_artifact_n];
  select * into a from turn_private.result_artifacts where id=next_artifact_n and owner_id=u and goal_id=goal_n and lifecycle='active';
  if not found then return false;end if;
  select * into r from turn_private.result_revisions where artifact_id=a.id and revision=next_revision_n and owner_id=u;
  if not found or r.evidence_basis is distinct from '[]'::jsonb or not turn_private.valid_travel_directions_v1(r.content)
   or (r.content->'draft'<>'null'::jsonb and r.content->'draft'->>'paceSource'='profile') then return false;end if;
  -- Existing archive variant policy is not extended by this new provenance read.
  if a.trip_id is not null and (exists(select 1 from public.trip_archives where trip_id=a.trip_id and owner_id=u)
   or exists(select 1 from privacy_private.trip_deletions where trip_id=a.trip_id)) then return false;end if;
  state_n:=turn_private.comparison_common_basis_state(a,r);
  if state_n->>'readable' is distinct from 'true' then return false;end if;
  select * into s from turn_private.directions_result_sources_v1 where artifact_id=a.id and owner_id=u and task_turn_id=r.task_turn_id;
  if not found or a.source_result_id is distinct from s.previous_artifact_id then return false;end if;
  select * into i from turn_private.assistant_directions_intakes_v1 where message_id=s.message_id and owner_id=u and goal_id=goal_n and task_turn_id=r.task_turn_id;
  if not found or r.content->'intake' is distinct from i.intake or r.memory_basis is distinct from i.memory_basis
   or not turn_private.planning_policy_current(i.planning_policy_id)
   or not exists(select 1 from turn_private.planning_consents c where c.owner_id=u and c.policy_id=i.planning_policy_id and c.consent_id=i.planning_consent_id and c.revoked_at is null) then return false;end if;
  content_n:=encode(sha256(convert_to(r.content::text,'UTF8')),'hex');
  if content_n<>s.initial_content_digest and not exists(select 1 from turn_private.directions_operations_v1 o
   where o.owner_id=u and o.artifact_id=a.id and o.source_message_id=i.message_id and o.task_turn_id=r.task_turn_id
    and not o.erased and o.action in('choose','save','edit') and o.result_revision=r.revision
    and o.output_content_digest=content_n and o.source_digest=s.source_digest) then return false;end if;
  bytes_n:=bytes_n+octet_length(jsonb_build_array(to_jsonb(a),to_jsonb(r),to_jsonb(s),to_jsonb(i))::text);
  if bytes_n>1000000 then return false;end if;
  next_artifact_n:=s.previous_artifact_id;next_revision_n:=s.previous_revision;
 end loop;
 return true;
end $$;
revoke all on function turn_private.directions_history_readable_v1(uuid,uuid,integer,uuid) from public,anon,authenticated,service_role;

-- Constituent: current-source.candidate.sql
-- ARTIFACT ONLY. Requires reviewed minimal metadata, dedicated genuine Task
-- completion, original source fences and complete privacy/catalog constituents.
-- No caller qualified flag, saved-Profile purpose or model dispatch authority.
create function turn_private.directions_current_basis_v1(u uuid,source_n uuid)
returns text language plpgsql security definer set search_path='' as $$
declare i turn_private.assistant_directions_intakes_v1%rowtype;
 m turn_private.assistant_messages%rowtype;g turn_private.assistant_goals%rowtype;
 a turn_private.assistant_conversations%rowtype;t turn_private.service_tasks%rowtype;
 w turn_private.work%rowtype;memories_n jsonb;
begin
 select * into i from turn_private.assistant_directions_intakes_v1 where message_id=source_n and owner_id=u;
 if not found then return null;end if;
 select * into m from turn_private.assistant_messages where id=i.message_id and owner_id=u;
 select * into g from turn_private.assistant_goals where id=i.goal_id and owner_id=u;
 select * into a from turn_private.assistant_conversations where id=i.conversation_id and owner_id=u;
 select * into t from turn_private.service_tasks where id=i.task_id and owner_id=u;
 select * into w from turn_private.work where turn_id=i.task_turn_id and owner_id=u;
 if m.id is null or g.id is null or a.id is null or t.id is null or w.turn_id is null
  or m.conversation_id<>a.id or m.goal_id<>g.id or g.conversation_id<>a.id
  or m.task_id is distinct from t.id or t.last_turn_id<>i.task_turn_id
  or m.sequence<>i.message_sequence or m.scope_version<>i.goal_version
  or g.scope_version<>i.goal_version or g.trip_terminal
  or m.policy_id<>i.policy_id or a.policy_id<>i.policy_id or t.policy_id<>i.policy_id
  or m.consent_id<>i.consent_id or a.consent_id<>i.consent_id or t.consent_id<>i.consent_id
  or w.execution_mode<>'travel_directions_v1' or w.state in('cancelled','quarantined')
  or not exists(select 1 from turn_private.text_content c where c.turn_id=i.task_turn_id and c.owner_id=u and c.hidden_at is null and c.policy_id=i.policy_id and c.consent_id=i.consent_id)
  or not exists(select 1 from turn_private.service_task_turns l where l.turn_id=i.task_turn_id and l.task_id=i.task_id and l.owner_id=u)
  or not turn_private.text_policy_current(i.policy_id)
  or not exists(select 1 from turn_private.text_consents c where c.owner_id=u and c.policy_id=i.policy_id and c.consent_id=i.consent_id and c.revoked_at is null)
  or not turn_private.planning_policy_current(i.planning_policy_id)
  or not exists(select 1 from turn_private.planning_policies p where p.id=i.planning_policy_id and p.text_policy_id=i.policy_id)
  or not exists(select 1 from turn_private.planning_consents c where c.owner_id=u and c.policy_id=i.planning_policy_id and c.consent_id=i.planning_consent_id and c.revoked_at is null)
  or i.intake_revision is distinct from (select max(x.intake_revision) from turn_private.assistant_directions_intakes_v1 x where x.goal_id=g.id and x.owner_id=u)
  or m.sequence is distinct from (select max(x.sequence) from turn_private.assistant_messages x where x.goal_id=g.id and x.owner_id=u)
  or not exists(select 1 from auth.sessions s where s.id=w.session_id and s.user_id=u) then return null;end if;
 -- Match original Native worker source-session qualification. A replaced login
 -- is not accountGone and does not authorize removal of retained source rows.
 if (exists(select 1 from identity_private.mobile_login_proofs p where p.session_id=w.session_id)
  or exists(select 1 from identity_private.mobile_attempts p where p.session_id=w.session_id))
  and not exists(select 1 from identity_private.mobile_accounts account_row where account_row.owner_id=u and account_row.session_id=w.session_id) then return null;end if;
 memories_n:=turn_private.explicit_intake_memory_binding_v1(u,i.memory_basis);
 if memories_n is null then return null;end if;
 return encode(sha256(convert_to(jsonb_build_object('schemaVersion','travel-directions-current-basis/1',
  'ownerId',u,'conversationId',a.id,'goalId',g.id,'goalVersion',i.goal_version,
  'inputMessageId',m.id,'inputSequence',i.message_sequence,'intakeRevision',i.intake_revision,
  'taskId',t.id,'taskTurnId',i.task_turn_id,'sourceSessionId',w.session_id,
  'policyId',i.policy_id,'consentId',i.consent_id,'planningPolicyId',i.planning_policy_id,
  'planningConsentId',i.planning_consent_id,'intake',i.intake,'memoryBindings',memories_n)::text,'UTF8')),'hex');
end $$;
revoke all on function turn_private.directions_current_basis_v1(uuid,uuid) from public,anon,authenticated,service_role;

create function turn_private.directions_domain_state_v1(u uuid,task_turn_n uuid,v jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare s turn_private.directions_result_sources_v1%rowtype;
 i turn_private.assistant_directions_intakes_v1%rowtype;actual_n text;content_n text;prior_r turn_private.result_revisions%rowtype;
begin
 if not turn_private.valid_travel_directions_v1(v) then return jsonb_build_object('readable',false,'current',false);end if;
 select * into s from turn_private.directions_result_sources_v1 where task_turn_id=task_turn_n and owner_id=u;
 if not found then return jsonb_build_object('readable',false,'current',false);end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where message_id=s.message_id and owner_id=u and task_turn_id=task_turn_n;
 if not found or v->'intake' is distinct from i.intake
  or (v->'draft'<>'null'::jsonb and v->'draft'->>'paceSource'='profile')
  or not turn_private.planning_policy_current(i.planning_policy_id)
  or not exists(select 1 from turn_private.planning_consents c where c.owner_id=u and c.policy_id=i.planning_policy_id and c.consent_id=i.planning_consent_id and c.revoked_at is null) then return jsonb_build_object('readable',false,'current',false);end if;
 content_n:=encode(sha256(convert_to(v::text,'UTF8')),'hex');
 -- Immutable original revisions hold content. Source/action metadata contains
 -- only digest/provenance; a generic service publisher cannot invent a choice.
 if content_n<>s.initial_content_digest and not exists(select 1 from turn_private.directions_operations_v1 o
  where o.owner_id=u and o.artifact_id=s.artifact_id and o.source_message_id=i.message_id and o.task_turn_id=task_turn_n
   and not o.erased and o.action in('choose','save','edit') and o.output_content_digest=content_n and o.source_digest=s.source_digest) then
  return jsonb_build_object('readable',false,'current',false);
 end if;
 if s.previous_artifact_id is not null then
  select * into prior_r from turn_private.result_revisions where artifact_id=s.previous_artifact_id and revision=s.previous_revision and owner_id=u;
  if not found or prior_r.content->'intake' is distinct from i.intake or prior_r.memory_basis is distinct from i.memory_basis
   or not turn_private.directions_history_readable_v1(u,s.previous_artifact_id,s.previous_revision,i.goal_id) then
   return jsonb_build_object('readable',false,'current',false);
  end if;
 end if;
 actual_n:=turn_private.directions_current_basis_v1(u,i.message_id);
 -- Original common Result state separately qualifies historical readability,
 -- original Memory/Task/Trip and evidence. New source staleness grants no action.
 return jsonb_build_object('readable',true,'current',actual_n is not null and actual_n=s.source_digest);
end $$;
revoke all on function turn_private.directions_domain_state_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;

-- These functions are only candidate constituents. The original closed union
-- and result_domain_state_v2 exact after patch is still required. Exact operation
