-- Constituent: read-basis.candidate.sql
-- ARTIFACT ONLY. Original current goal/message and immutable prior intake CAS;
-- reading a write basis never rewrites a goal, creates a Task or grants consent.
create function turn_private.directions_write_basis_v1(u uuid,policy_n uuid,conversation_n uuid,goal_n uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a turn_private.assistant_conversations%rowtype;g turn_private.assistant_goals%rowtype;
 m turn_private.assistant_messages%rowtype;i turn_private.assistant_directions_intakes_v1%rowtype;
 digest_n text;revision_n integer:=0;
begin
 if u is null or policy_n is null or conversation_n is null or goal_n is null then raise exception 'INVALID_INPUT';end if;
 select * into a from turn_private.assistant_conversations where id=conversation_n and owner_id=u and policy_id=policy_n;
 select * into g from turn_private.assistant_goals where id=goal_n and owner_id=u and conversation_id=conversation_n;
 if a.id is null or g.id is null or g.trip_terminal or not turn_private.text_policy_current(policy_n)
  or not exists(select 1 from turn_private.text_consents c where c.owner_id=u and c.policy_id=policy_n and c.consent_id=a.consent_id and c.revoked_at is null) then return jsonb_build_object('kind','unavailable','reason','blocked');end if;
 select * into m from turn_private.assistant_messages where goal_id=g.id and owner_id=u and conversation_id=a.id order by sequence desc limit 1;
 if not found or m.policy_id<>policy_n or m.consent_id<>a.consent_id or m.sequence not between 1 and 999999
  or g.scope_version not between 1 and 9999 or a.next_sequence>1000000 then return jsonb_build_object('kind','unavailable','reason','stale_basis');end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where goal_id=g.id and owner_id=u order by intake_revision desc limit 1;
 if found then
  revision_n:=i.intake_revision;if revision_n>999 then return jsonb_build_object('kind','unavailable','reason','stale_basis');end if;
  digest_n:=turn_private.directions_current_basis_v1(u,i.message_id);
  if digest_n is null then
   -- Explicit fresh linked-scope/correction may append a new source while the
   -- old result stays stale. This token binds the actual current parent/scope
   -- and exact immutable prior intake; it never makes old content current.
   digest_n:=encode(sha256(convert_to(jsonb_build_object('schemaVersion','travel-directions-write-cas/1','ownerId',u,
    'conversationId',a.id,'goalId',g.id,'goalVersion',g.scope_version,'parentMessageId',m.id,'messageSequence',m.sequence,
    'policyId',policy_n,'consentId',a.consent_id,'priorMessageId',i.message_id,'intakeRevision',i.intake_revision,
    'priorRequestBytesDigest',i.request_bytes_digest)::text,'UTF8')),'hex');
  end if;
 end if;
 return jsonb_build_object('kind','directions_write_basis','conversationId',a.id,'goalId',g.id,'goalVersion',g.scope_version,
  'parentMessageId',m.id,'messageSequence',m.sequence,'intakeRevision',revision_n,'intakeDigest',digest_n,'policyId',policy_n);
end $$;

create function turn_private.directions_read_intake_v1(u uuid,policy_n uuid,conversation_n uuid,goal_n uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare b jsonb;i turn_private.assistant_directions_intakes_v1%rowtype;d text;
 link_n turn_private.assistant_goal_trip_links%rowtype;trip_n public.trips%rowtype;pace_n jsonb;
begin
 b:=turn_private.directions_write_basis_v1(u,policy_n,conversation_n,goal_n);
 if b->>'kind'='unavailable' then return b;end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where goal_id=goal_n and owner_id=u and conversation_id=conversation_n order by intake_revision desc limit 1;
 if not found then return jsonb_build_object('kind','unavailable','reason','intake_unrecorded');end if;
 d:=turn_private.directions_current_basis_v1(u,i.message_id);
 if d is null then return jsonb_build_object('kind','unavailable','reason','stale_basis');end if;
 select * into link_n from turn_private.assistant_goal_trip_links where goal_id=goal_n and owner_id=u and conversation_id=conversation_n and not terminal_unlinked and trip_id is not null;
 if found then
  select * into trip_n from public.trips where id=link_n.trip_id and owner_id=u;
  if not found or exists(select 1 from privacy_private.trip_deletions where trip_id=link_n.trip_id)
   or exists(select 1 from public.trip_archives where trip_id=link_n.trip_id and owner_id=u) then return jsonb_build_object('kind','unavailable','reason','stale_basis');end if;
  -- Existing local-only projection may be displayed by its original consumer.
  -- This read is not server planning permission; submit.useSavedPace still denies.
  if exists(select 1 from identity_private.mobile_login_proofs p where p.session_id=(auth.jwt()->>'session_id')::uuid)
   or exists(select 1 from identity_private.mobile_attempts p where p.session_id=(auth.jwt()->>'session_id')::uuid) then
   pace_n:=public.native_task_travel_pace_v1(jsonb_build_object('tripId',trip_n.id,'currentPace',null,'useSaved',true));
   if pace_n->>'source' is distinct from 'profile' then pace_n:=null;end if;
  end if;
 end if;
 return jsonb_build_object('kind','directions_intake','schemaVersion','travel-directions-current-basis/1','conversationId',i.conversation_id,'goalId',i.goal_id,
  'goalVersion',i.goal_version,'inputMessageId',i.message_id,'inputSequence',i.message_sequence,'intakeRevision',i.intake_revision,'intakeDigest',d,
  'intake',i.intake,'memoryBasis',i.memory_basis,'tripId',trip_n.id,'tripVersion',trip_n.head_version,'profilePace',pace_n);
end $$;
revoke all on function turn_private.directions_write_basis_v1(uuid,uuid,uuid,uuid),turn_private.directions_read_intake_v1(uuid,uuid,uuid,uuid) from public,anon,authenticated,service_role;

-- Constituent: inline-claim.candidate.sql
-- ARTIFACT ONLY. Actual original newly admitted Turn/work, inline deterministic
-- lease; no external worker claim, fake dispatch, budget grant or started event.
create function turn_private.claim_directions_inline_v1(p_turn uuid,p_owner uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare w turn_private.work%rowtype;token_n uuid;
begin
 if p_turn is null or p_owner is null or p_owner is distinct from turn_private.text_owner() then raise exception 'UNAUTHENTICATED';end if;
 select * into w from turn_private.work where turn_id=p_turn and owner_id=p_owner;
 if not found or w.session_id is distinct from (auth.jwt()->>'session_id')::uuid
  or not turn_private.lock_turn(p_turn,p_owner,w.session_id) then raise exception 'SERVICE_TASK_CONFLICT';end if;
 select * into w from turn_private.work where turn_id=p_turn and owner_id=p_owner for update;
 if not found or w.state<>'queued' or w.execution_mode<>'travel_directions_v1' or w.attempt>=w.max_attempts
  or not exists(select 1 from public.turns t where t.id=p_turn and t.owner_id=p_owner and t.status='accepted')
  or not exists(select 1 from turn_private.assistant_directions_intakes_v1 i where i.task_turn_id=p_turn and i.owner_id=p_owner and turn_private.directions_current_basis_v1(p_owner,i.message_id) is not null) then raise exception 'SERVICE_TASK_CONFLICT';end if;
 token_n:=gen_random_uuid();
 update turn_private.work set state='leased',attempt=attempt+1,lease_token=token_n,
  expires_at=clock_timestamp()+w.lease_ms*interval '1 millisecond' where turn_id=p_turn and owner_id=p_owner;
 return token_n;
end $$;
create function turn_private.directions_task_output_v1(locale_n text,preserved_n boolean)
returns text language plpgsql immutable set search_path='' as $$
begin
 if locale_n is null or locale_n not in('zh','en') or preserved_n is null then raise exception 'INVALID_INPUT';end if;
 if preserved_n then return case when locale_n='zh' then '已保留你选择、保存和修改的相对日草稿。请查看旅行方向，再决定是否生成行程提案。' else 'Your selected, saved and edited relative-day draft is preserved. Review the travel directions before deciding whether to create a Trip proposal.' end;end if;
 return case when locale_n='zh' then '旅行方向已准备好。选方向、保存相对日草稿和确认行程分别操作；交通、营业时间与价格仍未核实。' else 'Your travel directions are ready. Choosing a direction, saving a relative-day draft and confirming a Trip are separate actions; transport, opening hours and prices remain unverified.' end;
end $$;
revoke all on function turn_private.claim_directions_inline_v1(uuid,uuid),turn_private.directions_task_output_v1(text,boolean) from public,anon,authenticated,service_role;

-- Constituent: trip-reference.candidate.sql
-- ARTIFACT ONLY. Exact current Trip-reference reader uses64+1, not128+1.
-- Candidate new narrow identity reader; actual Main lease/ACL review required.
-- No second content/store, Trip write, source-current exception or archive grant.
create function public.read_trip_directions_reference_v1(p_trip_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=turn_private.text_owner();candidate record;authorised jsonb;examined integer:=0;
begin
 if p_trip_id is null then raise exception 'INVALID_INPUT';end if;
 if not exists(select 1 from public.trips where id=p_trip_id and owner_id=u)
  or exists(select 1 from privacy_private.trip_deletions where trip_id=p_trip_id) then return jsonb_build_object('kind','empty');end if;
 -- Archived variants need their own precise original reader-domain lease.
 -- No historical archive allowlist is silently broadened by this helper.
 if exists(select 1 from public.trip_archives where trip_id=p_trip_id and owner_id=u) then return jsonb_build_object('kind','unavailable');end if;
 -- Bound original raw candidates BEFORE filtering, matching existing Trip RPC.
 for candidate in select id,current_revision from turn_private.result_artifacts
  where owner_id=u and trip_id=p_trip_id and lifecycle='active'
  order by created_at desc,id desc limit 65 loop
  examined:=examined+1;if examined>64 then return jsonb_build_object('kind','unavailable');end if;
  authorised:=public.read_result_artifact_v2(candidate.id,candidate.current_revision);
  if authorised->>'kind'='result_artifact' and authorised->>'artifactId'=candidate.id::text
   and authorised->'revision'=to_jsonb(candidate.current_revision)
   and authorised->'source'->>'tripId'=p_trip_id::text
   and authorised->'content'->>'schemaVersion'='travel-directions/1'
   and (authorised->'current'='true'::jsonb or authorised->'historicalReadable'='true'::jsonb) then
   -- Exact GET remains required; current=false never enables an action.
   return jsonb_build_object('kind','result_reference','artifactId',candidate.id,'revision',candidate.current_revision,'tripId',p_trip_id);
  end if;
 end loop;
 return jsonb_build_object('kind','empty');
end $$;
revoke all on function public.read_trip_directions_reference_v1(uuid) from public,anon,authenticated,service_role;
-- Repository candidate ACL ONLY. No target GRANT is authorized.
grant execute on function public.read_trip_directions_reference_v1(uuid) to authenticated;

-- Constituent: completion.candidate.sql
-- ARTIFACT ONLY. Dedicated deterministic completion; no fake provider dispatch.
-- Called by a precise new-mode branch in the original private unmetered function,
-- under the UNCHANGED original public capacity-settlement wrapper.
create function turn_private.complete_directions_work_v1(p_turn_id uuid,p_lease_token uuid,p_kind text,p_text text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare w turn_private.work%rowtype;s turn_private.directions_result_sources_v1%rowtype;
 i turn_private.assistant_directions_intakes_v1%rowtype;actual_n text;
begin
 if p_kind is distinct from 'answered' or not turn_private.valid_text(p_text,8000) then raise exception 'INVALID_INPUT';end if;
 if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked');end if;
 select * into w from turn_private.work where turn_id=p_turn_id for update;
 if not found or w.execution_mode<>'travel_directions_v1' or w.state<>'leased'
  or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp() then return jsonb_build_object('kind','blocked');end if;
 select * into s from turn_private.directions_result_sources_v1 where task_turn_id=p_turn_id and owner_id=w.owner_id;
 if not found then return jsonb_build_object('kind','blocked');end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where message_id=s.message_id and owner_id=w.owner_id and task_turn_id=p_turn_id;
 if not found then return jsonb_build_object('kind','blocked');end if;
 -- Original Text cap stays8000 even when a preserved edited Result is64KB.
 -- Canonical admission separately binds actual Result content digest; the Turn
 -- stores its real human-readable deterministic completion, not a content copy.
 if encode(sha256(convert_to(p_text,'UTF8')),'hex')<>s.initial_output_digest then return jsonb_build_object('kind','blocked');end if;
 actual_n:=turn_private.directions_current_basis_v1(w.owner_id,i.message_id);
 if actual_n is null or actual_n<>s.source_digest then return jsonb_build_object('kind','blocked');end if;
 -- Dedicated mode records genuine deterministic output and original terminal
 -- event. The enclosing original wrapper verifies readability and settles the
 -- logical Task reservation. No provider/model attempt or usage is synthesized.
 update turn_private.text_content set output_kind='answered',output_text=p_text where turn_id=p_turn_id and owner_id=w.owner_id and hidden_at is null;
 if not found then return jsonb_build_object('kind','blocked');end if;
 perform turn_private.terminal(p_turn_id,'completed',w.attempt);
 return jsonb_build_object('kind','finished');
exception when invalid_text_representation then raise exception 'INVALID_INPUT';
end $$;
revoke all on function turn_private.complete_directions_work_v1(uuid,uuid,text,text) from public,anon,authenticated,service_role;

-- Constituent: completion-shared.after.sql
-- ARTIFACT ONLY: precise shared seam; current-owner release/Main lease required.
CREATE OR REPLACE FUNCTION turn_private.complete_text_work_unmetered(p_turn_id uuid, p_lease_token uuid, p_kind text, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w turn_private.work%rowtype;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode='travel_directions_v1') then return turn_private.complete_directions_work_v1(p_turn_id,p_lease_token,p_kind,p_text);end if;
  if exists(select 1 from turn_private.text_content guarded_content join turn_private.text_policies guarded_policy on guarded_policy.id=guarded_content.policy_id where guarded_content.turn_id=p_turn_id and guarded_policy.context_mode='knowledge_intent_v1') then return jsonb_build_object('kind','unavailable'); end if;
  if p_kind is null or p_kind not in ('answered','partial','clarification','blocked','technical_failure') or not turn_private.valid_text(p_text,8000) then raise exception 'INVALID_INPUT'; end if;
  if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
  if p_kind in ('answered','partial','clarification') and not exists(select 1 from turn_private.text_dispatches where lease_token=p_lease_token and turn_id=p_turn_id) then return jsonb_build_object('kind','blocked'); end if;
  select * into w from turn_private.work where turn_id=p_turn_id;
  update turn_private.text_content set output_kind=p_kind,output_text=p_text where turn_id=p_turn_id;
  perform turn_private.terminal(p_turn_id,case when p_kind='blocked' then 'unavailable' when p_kind='technical_failure' then 'failed' else 'completed' end,w.attempt);
  return jsonb_build_object('kind','finished');
end $function$;

-- Constituent: turn_private-valid_result_content_v2.after.sql
-- ARTIFACT ONLY: exact current-owner/Main product lease required.
CREATE OR REPLACE FUNCTION turn_private.valid_result_content_v2(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s jsonb;
begin
 if v is null or jsonb_typeof(v) is distinct from 'object' or v->'actions' is distinct from '[]'::jsonb or octet_length(v::text)>65536 then return false;end if;
 if v->>'schemaVersion'='travel-directions/1' then return coalesce(turn_private.valid_travel_directions_v1(v),false);end if;
 if v->>'schemaVersion'='comparison/1' then return coalesce(turn_private.valid_comparison_v1(v),false);end if;
 if v->>'schemaVersion'='change-proposal-reference/1' then return coalesce(turn_private.valid_proposal_reference_v1(v),false);end if;
 if v->>'schemaVersion'='journey-draft/1' then
  s:=v->'source';return coalesce(knowledge_review_private.closed_object(v,array['schemaVersion','title','summary','draft','source','actions']) and knowledge_review_private.bounded_text(v->'title',120) and knowledge_review_private.bounded_text(v->'summary',1000) and turn_private.valid_result_draft_v2(v->'draft') and
   (knowledge_review_private.closed_object(s,array['kind','taskTurnId']) and s->>'kind'='task_output' and turn_private.result_uuid_v2(s->'taskTurnId')
    or knowledge_review_private.closed_object(s,array['kind','tripId','tripVersion']) and s->>'kind'='trip_snapshot' and turn_private.result_uuid_v2(s->'tripId') and turn_private.result_int_v2(s->'tripVersion',0)
    or knowledge_review_private.closed_object(s,array['kind','proposalId','proposalRevision']) and s->>'kind'='proposal_preview' and turn_private.result_uuid_v2(s->'proposalId') and turn_private.result_int_v2(s->'proposalRevision')),false);
 end if;
 if v->>'schemaVersion'='decision/1' then return coalesce(knowledge_review_private.closed_object(v,array['schemaVersion','title','summary','comparisonRef','state','chosenOptionId','actions']) and knowledge_review_private.bounded_text(v->'title',120) and knowledge_review_private.bounded_text(v->'summary',1000) and knowledge_review_private.closed_object(v->'comparisonRef',array['artifactId','revision']) and turn_private.result_uuid_v2(v->'comparisonRef'->'artifactId') and turn_private.result_int_v2(v->'comparisonRef'->'revision') and
  (v->>'state'='pending' and v->'chosenOptionId'='null'::jsonb or v->>'state'='chosen' and jsonb_typeof(v->'chosenOptionId')='string' and v->>'chosenOptionId' ~ '^[a-z0-9_-]{1,40}$'),false);end if;
 if v->>'schemaVersion'='practical/1' then return coalesce(knowledge_review_private.closed_object(v,array['schemaVersion','kind','sourceTurnId','sourceLocale','targetLocale','translation','backTranslation','actions']) and v->>'kind'='translation' and turn_private.result_uuid_v2(v->'sourceTurnId') and v->>'sourceLocale' in ('zh','en') and v->>'targetLocale' in ('zh','en') and v->>'sourceLocale'<>v->>'targetLocale' and knowledge_review_private.bounded_text(v->'translation',2400) and knowledge_review_private.bounded_text(v->'backTranslation',2400),false);end if;
 return false;
end $function$;

-- Constituent: turn_private-result_domain_state_v2.after.sql
-- ARTIFACT ONLY: exact current-owner/Main product lease required.
CREATE OR REPLACE FUNCTION turn_private.result_domain_state_v2(p_owner uuid, p_task_turn uuid, p_trip uuid, p_base integer, v jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb:=v->'source';proposal public.trip_proposals%rowtype;snap public.trip_version_snapshots%rowtype;preview jsonb;ra turn_private.result_artifacts%rowtype;rr turn_private.result_revisions%rowtype;state jsonb;projection jsonb;
begin
 if not turn_private.valid_result_content_v2(v) then return jsonb_build_object('readable',false,'current',false);end if;
 if v->>'schemaVersion'='travel-directions/1' then return turn_private.directions_domain_state_v1(p_owner,p_task_turn,v);end if;
 if v->>'schemaVersion'='change-proposal-reference/1' then
  if not turn_private.proposal_reference_current_v1(p_owner,p_trip,p_base,v) then return jsonb_build_object('readable',false,'current',false);end if;
 elsif v->>'schemaVersion'='journey-draft/1' then
  if s->>'kind'='task_output' then
   if (s->>'taskTurnId')::uuid<>p_task_turn then return jsonb_build_object('readable',false,'current',false);end if;
   if p_trip is null and v->'draft'->>'version'<>'0' then return jsonb_build_object('readable',false,'current',false);end if;
   perform 1 from turn_private.text_content c join public.turns t on t.id=c.turn_id where c.turn_id=p_task_turn and c.owner_id=p_owner and c.hidden_at is null and t.status='completed' and c.output_kind='answered' and c.output_text::jsonb=v->'draft';
   if not found then return jsonb_build_object('readable',false,'current',false);end if;
  elsif s->>'kind'='trip_snapshot' then
   if (s->>'tripId')::uuid is distinct from p_trip or (s->>'tripVersion')::integer is distinct from p_base then return jsonb_build_object('readable',false,'current',false);end if;
   select * into snap from public.trip_version_snapshots where trip_id=p_trip and owner_id=p_owner and version=p_base for share;
   if not found or snap.content||jsonb_build_object('version',p_base)<>v->'draft' then return jsonb_build_object('readable',false,'current',false);end if;
  else
   select * into proposal from public.trip_proposals where id=(s->>'proposalId')::uuid and owner_id=p_owner for share nowait;
   if not found or proposal.trip_id is distinct from p_trip then return jsonb_build_object('readable',false,'current',false);end if;
   if proposal.revision<>(s->>'proposalRevision')::integer or proposal.base_trip_version<>p_base or proposal.status<>'pending' or proposal.expires_at<=clock_timestamp() then return jsonb_build_object('readable',true,'current',false);end if;
   select * into snap from public.trip_version_snapshots where trip_id=p_trip and owner_id=p_owner and version=p_base for share;
   if not found then return jsonb_build_object('readable',false,'current',false);end if;
   if proposal.rollback_snapshot_version is not null then select content into preview from public.trip_version_snapshots where trip_id=p_trip and owner_id=p_owner and version=proposal.rollback_snapshot_version;
   else preview:=public.apply_trip_content_patch(snap.content,proposal.patch);end if;
   if preview is null or preview||jsonb_build_object('version',p_base+1)<>v->'draft' then return jsonb_build_object('readable',false,'current',false);end if;
  end if;
 elsif v->>'schemaVersion'='practical/1' then
  projection:=turn_private.result_translation_projection_v2(p_owner,(v->>'sourceTurnId')::uuid);
  if projection is null or projection<>v then return jsonb_build_object('readable',false,'current',false);end if;
 elsif v->>'schemaVersion'='decision/1' then
  select * into ra from turn_private.result_artifacts where id=(v->'comparisonRef'->>'artifactId')::uuid and owner_id=p_owner and lifecycle='active' for share nowait;
  if not found then return jsonb_build_object('readable',false,'current',false);end if;
  select * into rr from turn_private.result_revisions where artifact_id=ra.id and owner_id=p_owner and revision=(v->'comparisonRef'->>'revision')::integer;
  if not found or not coalesce(turn_private.valid_comparison_v1(rr.content),false) then return jsonb_build_object('readable',false,'current',false);end if;
  state:=turn_private.comparison_common_basis_state(ra,rr);
  if state->>'readable'<>'true' or not turn_private.result_evidence_current_v2(rr.evidence_basis) then return jsonb_build_object('readable',false,'current',false);end if;
  if v->>'state'='chosen' and not exists(select 1 from jsonb_array_elements(rr.content->'options') x where x->>'id'=v->>'chosenOptionId') then return jsonb_build_object('readable',false,'current',false);end if;
  if state->>'current'<>'true' or ra.current_revision<>rr.revision then return jsonb_build_object('readable',true,'current',false);end if;
 end if;
 return jsonb_build_object('readable',true,'current',true);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or lock_not_available then return jsonb_build_object('readable',false,'current',false);
end $function$;

-- Constituent: turn_private-publish_result_v2.after.sql
-- ARTIFACT ONLY: exact current-owner/Main product lease required.
CREATE OR REPLACE FUNCTION turn_private.publish_result_v2(p_owner_id uuid, p_artifact_id uuid, p_expected_revision integer, p_idempotency_key uuid, p_task_id uuid, p_goal_id uuid, p_input_message_id uuid, p_trip_id uuid, p_trip_version integer, p_goal_version integer, p_memory_basis jsonb, p_content jsonb, p_evidence_basis jsonb, p_owner_choice boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a turn_private.result_artifacts%rowtype; r turn_private.result_revisions%rowtype;
  source turn_private.assistant_messages%rowtype; task turn_private.service_tasks%rowtype;
  trip public.trips%rowtype; linked turn_private.assistant_goal_trip_links%rowtype;
  goal turn_private.assistant_goals%rowtype; receipt turn_private.assistant_goal_trip_receipts%rowtype;
  digest text; new_revision integer; m jsonb; reference_id uuid; content_locale text; source_result_n uuid;
begin
  if ((select auth.role())<>'service_role' and not (p_owner_choice and (select auth.role())='authenticated' and p_owner_id=turn_private.text_owner())) or p_owner_id is null or p_artifact_id is null or p_idempotency_key is null
    or p_task_id is null or p_goal_id is null or p_input_message_id is null or p_expected_revision is null
    or p_expected_revision not between 0 and 999 or p_goal_version is null or p_goal_version<1
    or (p_trip_id is null)<>(p_trip_version is null)
    or p_memory_basis is null or jsonb_typeof(p_memory_basis)<>'array' or jsonb_array_length(p_memory_basis)>20
    or not turn_private.valid_result_content_v2(p_content) or not turn_private.result_evidence_current_v2(p_evidence_basis) then raise exception 'INVALID_INPUT'; end if;
  if p_content->>'schemaVersion'='decision/1' and p_content->>'state'='chosen' and not (p_owner_choice and (select auth.role())='authenticated' and p_owner_id=turn_private.text_owner()) then raise exception 'OWNER_CHOICE_REQUIRED';end if;
  if turn_private.valid_proposal_reference_v1(p_content) then
    if p_trip_id is null then raise exception 'STALE_BASIS'; end if;
    reference_id:=(p_content->>'proposalId')::uuid;
  end if;
  if p_content->>'schemaVersion'='journey-draft/1' and p_content->'source'->>'kind'='proposal_preview' then reference_id:=(p_content->'source'->>'proposalId')::uuid;if p_trip_id is null then raise exception 'STALE_BASIS';end if;end if;
  for m in select value from jsonb_array_elements(p_memory_basis) loop
    if jsonb_typeof(m)<>'object' or m-'id'-'revision'<>'{}'::jsonb
      or (m->>'id') is null or (m->>'revision') !~ '^[1-9][0-9]{0,14}$'
      then raise exception 'INVALID_INPUT'; end if;
    if not exists(select 1 from public.memory_profiles p join public.memory_consents c on c.id=p.consent_id and c.owner_id=p.owner_id and c.status='granted'
      where p.id=(m->>'id')::uuid and p.owner_id=p_owner_id and p.revision=(m->>'revision')::bigint and p.state in ('explicit','confirmed') and p.summary is not null)
      then raise exception 'STALE_BASIS'; end if;
  end loop;
  select locale into content_locale from turn_private.assistant_messages where id=p_input_message_id and owner_id=p_owner_id;
  p_content:=turn_private.project_result_display_v2(p_content,content_locale);
  if p_content->>'schemaVersion'='decision/1' then source_result_n:=(p_content->'comparisonRef'->>'artifactId')::uuid;
  elsif p_content->>'schemaVersion'='travel-directions/1' then
    select previous_artifact_id into source_result_n from turn_private.directions_result_sources_v1 where artifact_id=p_artifact_id and owner_id=p_owner_id;
    if not found then raise exception 'STALE_BASIS';end if;
    if p_expected_revision=0 then
      if not exists(select 1 from turn_private.directions_result_sources_v1 s where s.artifact_id=p_artifact_id and s.owner_id=p_owner_id and s.publication_key=p_idempotency_key and s.initial_content_digest=encode(sha256(convert_to(p_content::text,'UTF8')),'hex')) then raise exception 'STALE_BASIS';end if;
    elsif not exists(select 1 from turn_private.directions_operations_v1 o where o.owner_id=p_owner_id and o.artifact_id=p_artifact_id and o.operation_id=p_idempotency_key and not o.erased and o.action in('choose','save','edit') and o.expected_revision=p_expected_revision and o.result_revision=p_expected_revision+1 and o.output_content_digest=encode(sha256(convert_to(p_content::text,'UTF8')),'hex')) then raise exception 'OWNER_CHOICE_REQUIRED';end if;
  end if;
  digest:=encode(pg_catalog.sha256(convert_to(jsonb_build_array(p_owner_id,p_artifact_id,p_expected_revision,p_task_id,p_goal_id,p_input_message_id,p_trip_id,p_trip_version,p_goal_version,p_memory_basis,p_content,p_evidence_basis)::text,'UTF8')),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('result-idempotency:'||p_owner_id||':'||p_idempotency_key,0));
  select * into r from turn_private.result_revisions where owner_id=p_owner_id and idempotency_key=p_idempotency_key;
  if found then
    if r.request_digest<>digest or r.artifact_id<>p_artifact_id then raise exception 'IDEMPOTENCY_KEY_REUSE'; end if;
    select * into a from turn_private.result_artifacts where id=r.artifact_id and owner_id=p_owner_id;
    if not found or a.lifecycle<>'active' or a.current_revision<>r.revision or turn_private.result_state_v2(a,r)->>'current'<>'true' then raise exception 'STALE_BASIS';end if;
    return jsonb_build_object('kind','published','artifactId',r.artifact_id,'revision',r.revision,'reused',true);
  end if;
  if p_trip_id is not null then
    -- Match #572's Trip -> link -> goal lock order. Neither retarget nor
    -- deletion can invalidate this basis before the revision/event commit.
    select * into trip from public.trips where id=p_trip_id and owner_id=p_owner_id for share;
    if not found or trip.head_version<>p_trip_version
      or exists(select 1 from public.trip_archives archive where archive.trip_id=p_trip_id and archive.owner_id=p_owner_id)
      or exists(select 1 from privacy_private.trip_deletions d where d.trip_id=p_trip_id)
      then raise exception 'STALE_BASIS'; end if;
    if reference_id is not null then
      -- Existing confirm/revise locks Proposal then Trip. Never wait for a
      -- Proposal lock while holding Trip: NOWAIT aborts rather than deadlocks.
      begin
        perform 1 from public.trip_proposals where id=reference_id and owner_id=p_owner_id for share nowait;
      exception when lock_not_available then raise exception 'STALE_BASIS'; end;
      if not turn_private.proposal_reference_current_v1(p_owner_id,p_trip_id,p_trip_version,case when p_content->>'schemaVersion'='journey-draft/1' then jsonb_build_object('schemaVersion','change-proposal-reference/1','proposalId',p_content->'source'->'proposalId','proposalRevision',p_content->'source'->'proposalRevision','actions','[]'::jsonb) else p_content end)
        then raise exception 'STALE_BASIS'; end if;
    end if;
    select * into linked from turn_private.assistant_goal_trip_links
      where goal_id=p_goal_id and owner_id=p_owner_id for share;
    if not found or linked.trip_id<>p_trip_id or linked.trip_head_version<>p_trip_version
      or linked.goal_scope_version<>p_goal_version or linked.source_kind<>'native_user_confirmed'
      or linked.terminal_unlinked then raise exception 'STALE_BASIS'; end if;
    select * into goal from turn_private.assistant_goals
      where id=p_goal_id and owner_id=p_owner_id and conversation_id=linked.conversation_id for share;
    if not found or goal.scope_version<>p_goal_version or goal.trip_terminal then raise exception 'STALE_BASIS'; end if;
    select * into receipt from turn_private.assistant_goal_trip_receipts
      where operation_id=linked.operation_id and owner_id=p_owner_id for share;
    if not found or receipt.action<>'link' or receipt.source_kind<>'native_user_confirmed'
      or receipt.goal_id<>p_goal_id or receipt.conversation_id<>linked.conversation_id
      or receipt.trip_id<>p_trip_id or receipt.trip_head_version<>p_trip_version
      or receipt.after_link_version<>linked.link_version or receipt.after_goal_scope_version<>p_goal_version
      or receipt.source_message_id is distinct from linked.source_message_id
      then raise exception 'STALE_BASIS'; end if;
  end if;
  select * into source from turn_private.assistant_messages where id=p_input_message_id and owner_id=p_owner_id and goal_id=p_goal_id and task_id=p_task_id;
  if not found or source.scope_version<>p_goal_version then raise exception 'STALE_BASIS'; end if;
  select * into task from turn_private.service_tasks where id=p_task_id and owner_id=p_owner_id for share;
  if not found or not turn_private.text_policy_current(task.policy_id)
    or not exists(select 1 from turn_private.text_consents c where c.owner_id=p_owner_id and c.policy_id=task.policy_id and c.consent_id=task.consent_id and c.revoked_at is null)
    or not exists(select 1 from turn_private.text_content root where root.turn_id=task.goal_turn_id and root.owner_id=p_owner_id and root.hidden_at is null)
    or not exists(select 1 from public.turns t join turn_private.text_content c on c.turn_id=t.id and c.owner_id=p_owner_id and c.hidden_at is null
      where t.id=task.last_turn_id and t.owner_id=p_owner_id and t.status='completed' and c.output_kind='answered' for share)
    then raise exception 'STALE_BASIS'; end if;
  if p_trip_id is not null and (source.conversation_id<>linked.conversation_id
    or source.created_at<=receipt.created_at or task.created_at<=receipt.created_at)
    then raise exception 'STALE_BASIS'; end if;
  if not exists(select 1 from turn_private.assistant_goals g where g.id=p_goal_id and g.owner_id=p_owner_id and g.conversation_id=source.conversation_id and g.scope_version=p_goal_version)
    or not turn_private.text_policy_current(source.policy_id)
    or not exists(select 1 from turn_private.text_consents c where c.owner_id=p_owner_id and c.policy_id=source.policy_id and c.consent_id=source.consent_id and c.revoked_at is null)
    then raise exception 'STALE_BASIS'; end if;
  if turn_private.result_domain_state_v2(p_owner_id,task.last_turn_id,p_trip_id,p_trip_version,p_content)->>'current'<>'true' then raise exception 'STALE_BASIS';end if;
  select * into a from turn_private.result_artifacts where id=p_artifact_id for update;
  if p_expected_revision=0 then
    if found then raise exception 'REVISION_CONFLICT'; end if;
    insert into turn_private.result_artifacts(id,owner_id,task_id,goal_id,input_message_id,trip_id,proposal_id,source_result_id,source_turn_id,current_revision)
      values(p_artifact_id,p_owner_id,p_task_id,p_goal_id,p_input_message_id,p_trip_id,reference_id,source_result_n,case when p_content->>'schemaVersion'='practical/1' then (p_content->>'sourceTurnId')::uuid when p_content->>'schemaVersion'='journey-draft/1' and p_content->'source'->>'kind'='task_output' then (p_content->'source'->>'taskTurnId')::uuid end,1);
    new_revision:=1;
  else
    if not found or a.owner_id<>p_owner_id or a.lifecycle<>'active' or a.current_revision<>p_expected_revision
      or (select content->>'schemaVersion' from turn_private.result_revisions where artifact_id=a.id and revision=a.current_revision) is distinct from p_content->>'schemaVersion'
      or a.proposal_id is distinct from reference_id
      or a.source_result_id is distinct from (source_result_n)
      or a.source_turn_id is distinct from (case when p_content->>'schemaVersion'='practical/1' then (p_content->>'sourceTurnId')::uuid when p_content->>'schemaVersion'='journey-draft/1' and p_content->'source'->>'kind'='task_output' then (p_content->'source'->>'taskTurnId')::uuid end)
      or a.task_id<>p_task_id or a.goal_id<>p_goal_id or a.input_message_id<>p_input_message_id or a.trip_id is distinct from p_trip_id
      then raise exception 'REVISION_CONFLICT'; end if;
    new_revision:=a.current_revision+1;
    update turn_private.result_artifacts set current_revision=new_revision where id=p_artifact_id;
  end if;
  insert into turn_private.result_revisions(artifact_id,revision,owner_id,idempotency_key,request_digest,input_sequence,task_turn_id,goal_version,trip_version,trip_link_operation_id,trip_link_version,memory_basis,content,evidence_basis)
    values(p_artifact_id,new_revision,p_owner_id,p_idempotency_key,digest,source.sequence,task.last_turn_id,p_goal_version,p_trip_version,
      case when p_trip_id is null then null else linked.operation_id end,
      case when p_trip_id is null then null else linked.link_version end,p_memory_basis,p_content,p_evidence_basis);
  insert into turn_private.result_events(owner_id,artifact_id,revision,event_type)
    values(p_owner_id,p_artifact_id,new_revision,case when new_revision=1 then 'ready' else 'revised' end);
  return jsonb_build_object('kind','published','artifactId',p_artifact_id,'revision',new_revision,'reused',false);
end $function$;

