-- public.complete_grounded_work_with_needs(uuid,uuid,text,text,text) beforeSHA256 934ed8c5d6e8e7ee3c133c0ae37f6c8a4cad423cc4e7c739374fdc45f1707fc0
CREATE OR REPLACE FUNCTION public.complete_grounded_work_with_needs(p_turn_id uuid, p_lease_token uuid, p_intent text, p_request_scope text, p_unanswered_needs text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare needs jsonb; source_text text; item jsonb; result jsonb;
begin
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
 if p_unanswered_needs is null or octet_length(p_unanswered_needs)>12000 then raise exception 'INVALID_INPUT'; end if;
 needs:=p_unanswered_needs::jsonb;
 if jsonb_typeof(needs)<>'array' then raise exception 'INVALID_INPUT'; end if;
 if jsonb_array_length(needs)>6 or p_request_scope is null
  or ((p_request_scope='additional_needs') <> (jsonb_array_length(needs)>0)) then raise exception 'INVALID_INPUT'; end if;
 if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 select input_text into source_text from turn_private.text_content where turn_id=p_turn_id;
 if source_text is null then return jsonb_build_object('kind','blocked'); end if;
 for item in select value from jsonb_array_elements(needs) loop
  if jsonb_typeof(item)<>'string' then raise exception 'INVALID_INPUT'; end if;
  if (item#>>'{}') !~ '[^[:space:]]' or length(item#>>'{}')>240
   or strpos(source_text,item#>>'{}')=0 then raise exception 'INVALID_INPUT'; end if;
 end loop;
 if (select count(distinct value) from jsonb_array_elements(needs))<>jsonb_array_length(needs) then raise exception 'INVALID_INPUT'; end if;
 -- The existing completion owns dispatch, current evidence, deadline recheck,
 -- immutable result and terminal event. Both writes commit or roll back together.
 result:=public.complete_grounded_work(p_turn_id,p_lease_token,p_intent,p_request_scope);
 if result->>'kind'='finished' then
  update turn_private.grounded_turns set unanswered_needs=case when request_scope='additional_needs' then needs else '[]'::jsonb end
   where turn_id=p_turn_id;
 end if;
 return result;
end $function$;

-- public.complete_grounded_place_work(uuid,uuid,text,text,text,text) beforeSHA256 2afa5a746d8ccdda8a0a842f8ebc06af4f3afcb7b9b0953f05e8e9df2ddb4a10
CREATE OR REPLACE FUNCTION public.complete_grounded_place_work(p_turn_id uuid, p_lease_token uuid, p_intent text, p_request_scope text, p_unanswered_needs text, p_place_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_text text; city text; needs jsonb; item jsonb; selected jsonb; result jsonb; final_intent text; final_scope text;
begin
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) then return guide_private.place_complete_v1(p_turn_id,p_lease_token,p_intent,p_request_scope,p_unanswered_needs,p_place_name);end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
 if p_intent is null or p_intent not in ('place_address','place_opening_hours','place_address_and_hours')
  or p_request_scope is null or p_request_scope not in ('single','additional_needs')
  or p_place_name is null or length(p_place_name) not between 1 and 160 or p_place_name~'[[:cntrl:]]'
  or p_unanswered_needs is null or octet_length(p_unanswered_needs)>12000 then raise exception 'INVALID_INPUT'; end if;
 needs:=p_unanswered_needs::jsonb;
 if jsonb_typeof(needs) is distinct from 'array' then raise exception 'INVALID_INPUT'; end if;
 if jsonb_array_length(needs)>6 or ((p_request_scope='additional_needs')<>(jsonb_array_length(needs)>0)) then raise exception 'INVALID_INPUT'; end if;
 if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 select c.input_text,g.city into source_text,city from turn_private.text_content c
 join turn_private.grounded_turns g on g.turn_id=c.turn_id and g.owner_id=c.owner_id where c.turn_id=p_turn_id and g.completed_at is null;
 if not found then return jsonb_build_object('kind','blocked'); end if;
 if strpos(source_text,p_place_name)=0 then raise exception 'INVALID_INPUT'; end if;
 for item in select value from jsonb_array_elements(needs) loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}')!~'[^[:space:]]' or length(item#>>'{}')>240
   or strpos(source_text,item#>>'{}')=0 then raise exception 'INVALID_INPUT'; end if;
 end loop;
 if (select count(distinct value) from jsonb_array_elements(needs))<>jsonb_array_length(needs) then raise exception 'INVALID_INPUT'; end if;
 -- Same lock order as Ops: name barrier before publication row locks.
 perform pg_catalog.pg_advisory_xact_lock_shared(160047,1);
 begin
  selected:=knowledge_review_private.place_subject(p_place_name,city);
 exception when raise_exception then
  if SQLERRM<>'KNOWLEDGE_DISABLED' then raise; end if;
  return public.complete_grounded_work(p_turn_id,p_lease_token,'technical_failure','unknown');
 end;
 final_intent:=case selected->>'kind' when 'matched' then p_intent when 'ambiguous' then 'clarification' else 'unsupported' end;
 final_scope:=case when selected->>'kind'='matched' then p_request_scope else 'unknown' end;
 result:=turn_private.complete_selected_grounded_work(p_turn_id,p_lease_token,final_intent,final_scope,selected->>'subjectId');
 if result->>'kind'='finished' then
  update turn_private.grounded_turns set place_name=case when intent<>'technical_failure' then p_place_name end,
   place_resolution=case when intent<>'technical_failure' then selected->>'kind' end,
   unanswered_needs=case when request_scope='additional_needs' then needs else '[]'::jsonb end where turn_id=p_turn_id;
 end if;
 return result;
end $function$;

-- public.finish_turn_work(uuid,uuid,text) beforeSHA256 888a7b6ef2bbd627c503ae0fd058654c807563d32fd3e9aa0365dafa87da4ab6
CREATE OR REPLACE FUNCTION public.finish_turn_work(p_turn_id uuid, p_lease_token uuid, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w turn_private.work%rowtype; turn_state text;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
  if p_outcome is null or p_outcome not in ('completed','provider_failure','validation_failure') then raise exception 'INVALID_INPUT'; end if;
  select * into w from turn_private.work where turn_id=p_turn_id;
  if not found or p_lease_token is null then return jsonb_build_object('kind','stale'); end if;
  if not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object('kind','unavailable'); end if;
  select * into w from turn_private.work where turn_id=p_turn_id for update;
  if not found or w.state<>'leased' or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp() then return jsonb_build_object('kind','stale'); end if;
  select status into turn_state from public.turns where id=w.turn_id;
  if turn_state in ('completed','proposal_ready','unavailable','failed','cancelled') then
    perform turn_private.terminal(w.turn_id,'cancelled',w.attempt);
    return jsonb_build_object('kind','stale');
  end if;
  if p_outcome='provider_failure' and w.attempt<w.max_attempts then
    update turn_private.work set state='queued',lease_token=null,expires_at=null where turn_id=w.turn_id;
    return jsonb_build_object('kind','queued');
  end if;
  perform turn_private.terminal(w.turn_id,case p_outcome when 'completed' then 'completed' when 'validation_failure' then 'failed' else 'quarantined' end,w.attempt);
  return jsonb_build_object('kind','finished');
end $function$;

-- public.claim_planning_action_v1(uuid,uuid,uuid,uuid,text,text,text,jsonb) beforeSHA256 3a6cc943c716aeb2999912954aa6e22be61e5f980f0348baa11e38db7d4be87c
CREATE OR REPLACE FUNCTION public.claim_planning_action_v1(p_turn_id uuid, p_owner_id uuid, p_lease_token uuid, p_message_id uuid, p_action_key text, p_tool_id text, p_input_digest text, p_memory_basis jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w turn_private.work%rowtype; prior turn_private.planning_action_receipts%rowtype;
  basis text; v_task_id uuid;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
  if (select auth.role())<>'service_role' or p_action_key !~ '^[a-f0-9]{64}$'
    or p_input_digest !~ '^[a-f0-9]{64}$'
    or p_tool_id not in ('evidence.lookup','place.read','constraints.evaluate','result.prepare')
    or p_turn_id is null or p_owner_id is null or p_lease_token is null or p_message_id is null
    then raise exception 'INVALID_INPUT'; end if;
  select * into w from turn_private.work where turn_id=p_turn_id and owner_id=p_owner_id;
  if not found or not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object('kind','stale'); end if;
  select * into w from turn_private.work where turn_id=p_turn_id for update;
  if w.state<>'leased' or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp()
    or not exists(select 1 from public.turns t where t.id=p_turn_id and t.owner_id=p_owner_id and t.status='accepted')
    then return jsonb_build_object('kind','stale'); end if;
  basis:=turn_private.planning_action_basis(p_turn_id,p_owner_id,p_message_id,p_memory_basis);
  if basis is null then return jsonb_build_object('kind','stale_basis'); end if;
  select m.task_id into v_task_id from turn_private.assistant_messages m where m.id=p_message_id;
  select * into prior from turn_private.planning_action_receipts where turn_id=p_turn_id and action_key=p_action_key;
  if found then
    if prior.owner_id<>p_owner_id or prior.task_id<>v_task_id or prior.message_id<>p_message_id
      or prior.tool_id<>p_tool_id or prior.input_digest<>p_input_digest or prior.basis_digest<>basis
      then return jsonb_build_object('kind','conflict'); end if;
    return jsonb_build_object('kind',case when prior.state='completed' then 'duplicate' else 'unknown' end,
      'receiptDigest',prior.receipt_digest);
  end if;
  -- A dispatched/pending model charge, or a prior action without a durable
  -- completion receipt, requires reconciliation before any new effect.
  if exists(select 1 from public.model_budget_attempts a where a.task_id in (v_task_id,p_turn_id)
    and a.status in ('dispatched','pending'))
    or exists(select 1 from turn_private.planning_action_receipts a where a.turn_id=p_turn_id and a.state in ('started','unknown'))
    then return jsonb_build_object('kind','unknown'); end if;
  if (select count(*) from turn_private.planning_action_receipts where task_id=v_task_id)>=4
    then return jsonb_build_object('kind','step_limit'); end if;
  insert into turn_private.planning_action_receipts(turn_id,action_key,owner_id,task_id,message_id,lease_token,tool_id,input_digest,basis_digest,memory_basis,state)
    values(p_turn_id,p_action_key,p_owner_id,v_task_id,p_message_id,p_lease_token,p_tool_id,p_input_digest,basis,p_memory_basis,'started');
  return jsonb_build_object('kind','claimed');
end $function$;

-- public.finish_planning_action_v1(uuid,uuid,uuid,text,text) beforeSHA256 a9e60b6c46e21a78f017bb635afbb8f1468497ae9639e171969abf7c642834dc
CREATE OR REPLACE FUNCTION public.finish_planning_action_v1(p_turn_id uuid, p_owner_id uuid, p_lease_token uuid, p_action_key text, p_receipt_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w turn_private.work%rowtype; action turn_private.planning_action_receipts%rowtype;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
  if (select auth.role())<>'service_role' or p_turn_id is null or p_owner_id is null or p_lease_token is null
    or p_action_key !~ '^[a-f0-9]{64}$' or (p_receipt_digest is not null and p_receipt_digest !~ '^[a-f0-9]{64}$')
    then raise exception 'INVALID_INPUT'; end if;
  select * into w from turn_private.work where turn_id=p_turn_id and owner_id=p_owner_id;
  if not found or not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object('kind','stale'); end if;
  select * into w from turn_private.work where turn_id=p_turn_id for update;
  if w.state<>'leased' or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp()
    or not exists(select 1 from public.turns t where t.id=p_turn_id and t.owner_id=p_owner_id and t.status='accepted')
    then return jsonb_build_object('kind','stale'); end if;
  select * into action from turn_private.planning_action_receipts where turn_id=p_turn_id and action_key=p_action_key for update;
  if not found or action.owner_id<>p_owner_id or action.lease_token<>p_lease_token then return jsonb_build_object('kind','stale'); end if;
  if action.state='completed' then return jsonb_build_object('kind',case when action.receipt_digest=p_receipt_digest then 'duplicate' else 'conflict' end); end if;
  if action.state='unknown' and p_receipt_digest is not null then return jsonb_build_object('kind','unknown'); end if;
  if p_receipt_digest is not null and turn_private.planning_action_basis(p_turn_id,p_owner_id,action.message_id,action.memory_basis) is distinct from action.basis_digest
    then return jsonb_build_object('kind','stale_basis'); end if;
  update turn_private.planning_action_receipts set state=case when p_receipt_digest is null then 'unknown' else 'completed' end,
    receipt_digest=p_receipt_digest,updated_at=clock_timestamp() where turn_id=p_turn_id and action_key=p_action_key;
  return jsonb_build_object('kind',case when p_receipt_digest is null then 'unknown' else 'completed' end);
end $function$;

-- public.read_planning_comparison_work_v1(uuid,uuid) beforeSHA256 d5b184b23bb6b398e327b57a50bd01deeab04a4464b44b1b77d5d14bf7fed600
CREATE OR REPLACE FUNCTION public.read_planning_comparison_work_v1(p_turn_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w turn_private.work%rowtype; j turn_private.planning_comparisons%rowtype;
  s turn_private.service_tasks%rowtype; g turn_private.assistant_goals%rowtype;
  m turn_private.assistant_messages%rowtype; p turn_private.planning_policies%rowtype;
  t turn_private.text_policies%rowtype; basis text; item jsonb; profile public.memory_profiles%rowtype;
  memories jsonb:='[]'::jsonb; payload jsonb;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
  if (select auth.role())<>'service_role' or p_turn_id is null or p_lease_token is null then raise exception 'INVALID_INPUT'; end if;
  select * into w from turn_private.work where turn_id=p_turn_id;
  if not found or not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object('kind','blocked'); end if;
  select * into w from turn_private.work where turn_id=p_turn_id for update;
  if w.execution_mode<>'planning_comparison_v1' or w.state<>'leased' or w.lease_token is distinct from p_lease_token
    or w.expires_at<=clock_timestamp() or not exists(select 1 from public.turns where id=p_turn_id and owner_id=w.owner_id and status='accepted')
    then return jsonb_build_object('kind','blocked'); end if;
  select * into j from turn_private.planning_comparisons where turn_id=p_turn_id and owner_id=w.owner_id and state='queued';
  if not found then return jsonb_build_object('kind','blocked'); end if;
  basis:=turn_private.planning_action_basis(p_turn_id,w.owner_id,j.message_id,j.memory_basis);
  if basis is null then return jsonb_build_object('kind','stale_basis'); end if;
  select * into s from turn_private.service_tasks where id=j.task_id and owner_id=w.owner_id;
  select * into g from turn_private.assistant_goals where id=j.goal_id and owner_id=w.owner_id;
  select * into m from turn_private.assistant_messages where id=j.message_id and owner_id=w.owner_id;
  select * into p from turn_private.planning_policies where id=j.planning_policy_id;
  select * into t from turn_private.text_policies where id=p.text_policy_id;
  if s.id is null or g.id is null or m.id is null or p.id is null or t.id is null or t.id<>s.policy_id
    then return jsonb_build_object('kind','blocked'); end if;
  for item in select value from jsonb_array_elements(j.memory_basis) loop
    select * into profile from public.memory_profiles where id=(item->>'id')::uuid and owner_id=w.owner_id
      and revision=(item->>'revision')::bigint and state in ('explicit','confirmed') and summary is not null;
    if not found then return jsonb_build_object('kind','stale_basis'); end if;
    memories:=memories||jsonb_build_array(jsonb_build_object('id',profile.id,'revision',profile.revision,
      'constraintKind',profile.constraint_kind,'summary',profile.summary,'state',profile.state,
      'sourceReceiptId',profile.source_receipt_id,'consentId',profile.consent_id,
      'consentStatus','granted','updatedAt',profile.updated_at));
  end loop;
  payload:=jsonb_build_object('kind','planning_input','turnId',w.turn_id,'ownerId',w.owner_id,
    'taskId',j.task_id,'conversationId',m.conversation_id,'goalId',j.goal_id,'goalVersion',j.goal_version,'messageId',j.message_id,
    'messageSequence',m.sequence,'policyId',p.id,'provider',t.provider,'endpoint',t.endpoint,
    'locale',m.locale,'goalText',g.current_text,'messageText',m.input_text,'memories',memories,
    'memoryBasis',j.memory_basis,'artifactId',j.artifact_id);
  return payload||jsonb_build_object('contextDigest',encode(pg_catalog.sha256(convert_to(payload::text,'UTF8')),'hex'));
end $function$;

-- public.authorize_planning_read_v1(uuid,uuid,text) beforeSHA256 ecfebf3e4d4c98745415cc9f98b590226d5bfe43d2db8ae6a21d79670686161d
CREATE OR REPLACE FUNCTION public.authorize_planning_read_v1(p_turn_id uuid, p_lease_token uuid, p_context_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload jsonb;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
  if (select auth.role())<>'service_role' or p_context_digest !~ '^[a-f0-9]{64}$' then raise exception 'INVALID_INPUT'; end if;
  payload:=public.read_planning_comparison_work_v1(p_turn_id,p_lease_token);
  if payload->>'kind'<>'planning_input' or payload->>'contextDigest' is distinct from p_context_digest then return jsonb_build_object('kind','blocked'); end if;
  return jsonb_build_object('kind','authorized');
end $function$;

-- public.authorize_planning_dispatch_v1(uuid,uuid,text,uuid,uuid) beforeSHA256 ed657be120b1d89c6ae39472b1bf5361fd13eb6820edaff0a46e03b7c9de852b
CREATE OR REPLACE FUNCTION public.authorize_planning_dispatch_v1(p_turn_id uuid, p_lease_token uuid, p_context_digest text, p_scope_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload jsonb; w turn_private.work%rowtype; c turn_private.text_content%rowtype; j turn_private.planning_comparisons%rowtype;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
  if (select auth.role())<>'service_role' or p_context_digest !~ '^[a-f0-9]{64}$'
    or p_scope_id is null or p_attempt_id is null then raise exception 'INVALID_INPUT'; end if;
  payload:=public.read_planning_comparison_work_v1(p_turn_id,p_lease_token);
  if payload->>'kind'<>'planning_input' or payload->>'contextDigest' is distinct from p_context_digest then return jsonb_build_object('kind','blocked'); end if;
  select * into w from turn_private.work where turn_id=p_turn_id;
  select * into j from turn_private.planning_comparisons where turn_id=p_turn_id;
  select * into c from turn_private.text_content where turn_id=p_turn_id;
  if not exists(select 1 from public.model_budget_attempts a join public.model_budget_scopes s on s.id=a.scope_id
    where a.scope_id=p_scope_id and a.attempt_id=p_attempt_id and a.task_id=j.task_id and a.status='dispatched'
      and s.owner_id=w.owner_id and a.provider=payload->>'provider' and s.enabled and not s.frozen and s.expires_at>clock_timestamp())
    then return jsonb_build_object('kind','blocked'); end if;
  insert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id)
    values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;
  if not found then return jsonb_build_object('kind','blocked'); end if;
  insert into turn_private.planning_model_dispatches(lease_token,turn_id,owner_id,task_id,scope_id,attempt_id)
    values(p_lease_token,p_turn_id,w.owner_id,j.task_id,p_scope_id,p_attempt_id) on conflict do nothing;
  if not found then raise exception 'DISPATCH_CONFLICT'; end if;
  return jsonb_build_object('kind','authorized');
end $function$;

-- public.pause_planning_comparison_v1(uuid,uuid) beforeSHA256 766dabfc1129d1825c13eaa04fdd21bdbb1d57fff37c106bbdefe16f652106ca
CREATE OR REPLACE FUNCTION public.pause_planning_comparison_v1(p_turn_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w turn_private.work%rowtype;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
  if (select auth.role())<>'service_role' or p_turn_id is null or p_lease_token is null then raise exception 'INVALID_INPUT'; end if;
  select * into w from turn_private.work where turn_id=p_turn_id;
  if not found or not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object('kind','stale'); end if;
  select * into w from turn_private.work where turn_id=p_turn_id for update;
  if w.state<>'leased' or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp()
    or w.execution_mode<>'planning_comparison_v1' then return jsonb_build_object('kind','stale'); end if;
  update turn_private.planning_comparisons set state='paused_unknown' where turn_id=p_turn_id and state='queued';
