  return jsonb_build_object('kind','paused_unknown');
end $function$;

-- public.complete_planning_observation_v1(uuid,uuid,uuid,text,jsonb) beforeSHA256 161e237e8bedfc254d711cfe879a74833df18dea1d4d060b6d37072622707f35
CREATE OR REPLACE FUNCTION public.complete_planning_observation_v1(p_turn_id uuid, p_owner_id uuid, p_lease_token uuid, p_action_key text, p_observation jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w turn_private.work%rowtype; a turn_private.planning_action_receipts%rowtype; existing turn_private.planning_observations%rowtype;
  policy_environment text; digest text;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
  if (select auth.role())<>'service_role' or p_turn_id is null or p_owner_id is null or p_lease_token is null
    or p_action_key !~ '^[a-f0-9]{64}$' or p_observation is null or octet_length(p_observation::text)>8192
    then raise exception 'INVALID_INPUT'; end if;
  select * into w from turn_private.work where turn_id=p_turn_id and owner_id=p_owner_id;
  if not found or not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object('kind','stale'); end if;
  select * into w from turn_private.work where turn_id=p_turn_id for update;
  if w.execution_mode<>'planning_comparison_v1' or w.state<>'leased' or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp()
    then return jsonb_build_object('kind','stale'); end if;
  select * into a from turn_private.planning_action_receipts where turn_id=p_turn_id and action_key=p_action_key for update;
  if not found or a.owner_id<>p_owner_id or a.lease_token<>p_lease_token or not turn_private.valid_planning_observation_v1(a.tool_id,p_observation)
    then return jsonb_build_object('kind','blocked'); end if;
  if a.tool_id='place.read' then
    select p.environment into policy_environment from turn_private.planning_comparisons j
      join turn_private.planning_policies p on p.id=j.planning_policy_id where j.turn_id=p_turn_id;
    if policy_environment is null or (p_observation->>'source'='synthetic_fixture') is distinct from (policy_environment='local_synthetic')
      then return jsonb_build_object('kind','blocked'); end if;
  end if;
  if turn_private.planning_action_basis(p_turn_id,p_owner_id,a.message_id,a.memory_basis) is distinct from a.basis_digest
    then return jsonb_build_object('kind','stale_basis'); end if;
  digest:=encode(pg_catalog.sha256(convert_to(p_observation::text,'UTF8')),'hex');
  if a.state='completed' then
    select * into existing from turn_private.planning_observations where turn_id=p_turn_id and action_key=p_action_key;
    return jsonb_build_object('kind',case when a.receipt_digest=digest and existing.observation=p_observation then 'duplicate' else 'conflict' end);
  end if;
  if a.state<>'started' then return jsonb_build_object('kind','unknown'); end if;
  insert into turn_private.planning_observations(turn_id,action_key,owner_id,observation)
    values(p_turn_id,p_action_key,p_owner_id,p_observation);
  update turn_private.planning_action_receipts set state='completed',receipt_digest=digest,updated_at=clock_timestamp()
    where turn_id=p_turn_id and action_key=p_action_key;
  return jsonb_build_object('kind','completed','receiptDigest',digest);
end $function$;

-- public.read_planning_observations_v1(uuid,uuid) beforeSHA256 b08559d3386db3fdf68e894dedf9d2ad51fec33ecb4dd4f5d2a81d739a05ee75
CREATE OR REPLACE FUNCTION public.read_planning_observations_v1(p_turn_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare input jsonb; observations jsonb;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
  if (select auth.role())<>'service_role' then raise exception 'FORBIDDEN'; end if;
  input:=public.read_planning_comparison_work_v1(p_turn_id,p_lease_token);
  if input->>'kind'<>'planning_input' then return jsonb_build_object('kind','blocked'); end if;
  select coalesce(jsonb_agg(jsonb_build_object('toolId',a.tool_id,'actionKey',a.action_key,
      'receiptDigest',a.receipt_digest,'observation',o.observation) order by a.created_at,a.action_key),'[]'::jsonb)
    into observations from turn_private.planning_action_receipts a
    join turn_private.planning_observations o on o.turn_id=a.turn_id and o.action_key=a.action_key
    where a.turn_id=p_turn_id and a.state='completed';
  return jsonb_build_object('kind','observations','items',observations,'contextDigest',input->>'contextDigest');
end $function$;

-- public.complete_planning_comparison_v1(uuid,uuid,uuid,text,uuid,text,jsonb) beforeSHA256 5d8aa658cdde5b6e3d59b85017a793c02d9b04b9bcdd7fdc0e74eaaf14675094
CREATE OR REPLACE FUNCTION public.complete_planning_comparison_v1(p_turn_id uuid, p_owner_id uuid, p_lease_token uuid, p_result_action_key text, p_model_attempt_id uuid, p_text text, p_content jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; published jsonb; j turn_private.planning_comparisons%rowtype;
  a turn_private.planning_action_receipts%rowtype; basis text; digest text; tools text[]; place jsonb; content_locale text;
begin
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
  if (select auth.role())<>'service_role' or p_turn_id is null or p_owner_id is null or p_lease_token is null
    or p_result_action_key !~ '^[a-f0-9]{64}$' or p_model_attempt_id is null
    or not turn_private.valid_text(p_text,8000) or not turn_private.valid_comparison_v1(p_content)
    or (select count(*) from jsonb_array_elements(p_content->'options') o where o->>'id' in ('jingan','peoples_square'))<>2
    or (select count(distinct o->>'id') from jsonb_array_elements(p_content->'options') o)<>2
    then raise exception 'INVALID_INPUT'; end if;
  select o.observation into place from turn_private.planning_action_receipts x
    join turn_private.planning_observations o on o.turn_id=x.turn_id and o.action_key=x.action_key
    where x.turn_id=p_turn_id and x.tool_id='place.read' and x.state='completed';
  select m.locale into content_locale from turn_private.planning_comparisons job_row
    join turn_private.assistant_messages m on m.id=job_row.message_id where job_row.turn_id=p_turn_id and job_row.owner_id=p_owner_id;
  if place is null or not turn_private.valid_planning_comparison_v1(p_content,place,content_locale)
    or (place->>'observedAt')::timestamptz>clock_timestamp()+interval '5 seconds'
    or (place->>'observedAt')::timestamptz<clock_timestamp()-interval '5 minutes'
    then raise exception 'INVALID_INPUT'; end if;
  -- The existing wrapper owns the task-capacity lock order and only returns
  -- finished for a current authorized lease with a dispatch receipt.
  result:=public.complete_text_work(p_turn_id,p_lease_token,'answered',p_text);
  if result->>'kind'<>'finished' then return jsonb_build_object('kind','stale'); end if;
  select * into j from turn_private.planning_comparisons where turn_id=p_turn_id and owner_id=p_owner_id for update;
  if not found or j.state<>'queued' or not turn_private.planning_policy_current(j.planning_policy_id)
    or not exists(select 1 from turn_private.planning_consents c where c.owner_id=p_owner_id and c.policy_id=j.planning_policy_id
      and c.consent_id=j.planning_consent_id and c.revoked_at is null)
    then raise exception 'STALE_BASIS'; end if;
  basis:=turn_private.planning_action_basis(p_turn_id,p_owner_id,j.message_id,j.memory_basis);
  select * into a from turn_private.planning_action_receipts where turn_id=p_turn_id and action_key=p_result_action_key for update;
  if basis is null or not found or a.owner_id<>p_owner_id or a.task_id<>j.task_id or a.message_id<>j.message_id
    or a.lease_token<>p_lease_token or a.tool_id<>'result.prepare' or a.state<>'started' or a.basis_digest<>basis
    then raise exception 'STALE_BASIS'; end if;
  select array_agg(distinct x.tool_id order by x.tool_id) into tools from turn_private.planning_action_receipts x
    join turn_private.planning_observations o on o.turn_id=x.turn_id and o.action_key=x.action_key
    where x.turn_id=p_turn_id and x.state='completed';
  if tools is distinct from array['constraints.evaluate','evidence.lookup','place.read']::text[]
    or not exists(select 1 from turn_private.planning_model_dispatches d where d.lease_token=p_lease_token
      and d.turn_id=p_turn_id and d.owner_id=p_owner_id and d.task_id=j.task_id and d.attempt_id=p_model_attempt_id)
    or not exists(select 1 from public.model_budget_attempts b join public.model_budget_scopes s on s.id=b.scope_id
      where b.attempt_id=p_model_attempt_id and b.task_id=j.task_id and b.status='settled'
        and b.actual_micros is not null and s.owner_id=p_owner_id and b.created_at>=j.created_at)
    then raise exception 'PLANNING_INCOMPLETE'; end if;
  published:=public.publish_comparison_result_v1(p_owner_id,j.artifact_id,0,j.publication_key,
    j.task_id,j.goal_id,j.message_id,null,null,j.goal_version,j.memory_basis,p_content);
  if published->>'kind'<>'published' or published->>'reused'<>'false' then raise exception 'PLANNING_INCOMPLETE'; end if;
  digest:=encode(pg_catalog.sha256(convert_to(p_content::text,'UTF8')),'hex');
  update turn_private.planning_action_receipts set state='completed',receipt_digest=digest,updated_at=clock_timestamp()
    where turn_id=p_turn_id and action_key=p_result_action_key;
  update turn_private.planning_comparisons set state='completed' where turn_id=p_turn_id;
  return jsonb_build_object('kind','published','artifactId',j.artifact_id,'revision',1);
end $function$;

-- public.complete_grounded_work(uuid,uuid,text,text) beforeSHA256 6a15db936986543ead0f8c021d09af27008e0607e23030e05cc73a516c3f6191
CREATE OR REPLACE FUNCTION public.complete_grounded_work(p_turn_id uuid, p_lease_token uuid, p_intent text, p_request_scope text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select case when exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1'))
  then jsonb_build_object('kind','stale')
  else turn_private.complete_selected_grounded_work(p_turn_id,p_lease_token,p_intent,p_request_scope,null) end
$function$;

-- Constituent: submit.candidate.sql
-- ARTIFACT ONLY. Full atomic original Task admission → real completion → original
-- immutable result publication. Exact request bytes are supplied by the gateway.
create function turn_private.submit_directions_v1(u uuid,policy_n uuid,v jsonb,bytes_digest_n text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare prior_i turn_private.assistant_directions_intakes_v1%rowtype;i turn_private.assistant_directions_intakes_v1%rowtype;
 s turn_private.directions_result_sources_v1%rowtype;old_s turn_private.directions_result_sources_v1%rowtype;
 old_a turn_private.result_artifacts%rowtype;old_r turn_private.result_revisions%rowtype;
 link_n turn_private.assistant_goal_trip_links%rowtype;trip_n public.trips%rowtype;
 basis_n jsonb;admitted_n jsonb;message_n jsonb;published_n jsonb;content_n jsonb;memories_n jsonb;
 source_digest_n text;output_n text;token_n uuid;artifact_n uuid:=gen_random_uuid();publication_n uuid:=gen_random_uuid();
 previous_n uuid;previous_revision_n integer;source_current_n boolean;g turn_private.assistant_goals%rowtype;
begin
 if u is distinct from turn_private.text_owner() or policy_n is null or not turn_private.directions_input_v1('submit',v)
  or bytes_digest_n is null or bytes_digest_n !~ '^[a-f0-9]{64}$' then raise exception 'INVALID_INPUT';end if;
 if v->'useSavedPace'='true'::jsonb then raise exception 'DATA_POLICY_BLOCKED';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,34));
 perform pg_advisory_xact_lock(hashtextextended('directions-submit:'||u::text||':'||(v->>'messageKey'),0));
 if not turn_private.text_policy_current(policy_n) or not turn_private.planning_policy_current((v->>'planningPolicyId')::uuid)
  or not exists(select 1 from turn_private.planning_policies p where p.id=(v->>'planningPolicyId')::uuid and p.text_policy_id=policy_n)
  or not exists(select 1 from turn_private.planning_consents c where c.owner_id=u and c.policy_id=(v->>'planningPolicyId')::uuid and c.revoked_at is null for share) then raise exception 'DATA_POLICY_BLOCKED';end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where owner_id=u and idempotency_key=(v->>'messageKey')::uuid;
 if found then
  if i.request_bytes_digest<>bytes_digest_n or i.policy_id<>policy_n or i.task_id<>(v->>'taskId')::uuid or i.task_turn_id<>(v->>'turnId')::uuid or i.message_id<>(v->>'messageId')::uuid then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;
  select * into s from turn_private.directions_result_sources_v1 where message_id=i.message_id and owner_id=u;
  if not found then raise exception 'SERVICE_TASK_CONFLICT';end if;
  if public.read_result_artifact_v2(s.artifact_id,1)->>'kind' is distinct from 'result_artifact' then raise exception 'DATA_POLICY_BLOCKED';end if;
  source_current_n:=turn_private.directions_current_basis_v1(u,i.message_id)=s.source_digest
   and exists(select 1 from turn_private.result_artifacts a where a.id=s.artifact_id and a.owner_id=u and a.lifecycle='active' and a.current_revision=1);
  return jsonb_build_object('kind','published','artifactId',s.artifact_id,'revision',1,'reused',true,'taskId',i.task_id,'turnId',i.task_turn_id,
   'conversationId',i.conversation_id,'goalId',i.goal_id,'goalVersion',i.goal_version,'inputMessageId',i.message_id,'inputSequence',i.message_sequence,
   'intakeRevision',i.intake_revision,'intakeDigest',s.source_digest,'current',coalesce(source_current_n,false));
 end if;
 -- Source actor locks precede original Trip→link→goal order. Ordinary Web
 -- actors use original text_owner, without native-proof creation or coercion.
 perform 1 from identity_private.mobile_accounts where owner_id=u for update nowait;
 select * into link_n from turn_private.assistant_goal_trip_links where goal_id=(v->>'goalId')::uuid and owner_id=u;
 if link_n.trip_id is not null then
  select * into trip_n from public.trips where id=link_n.trip_id and owner_id=u for share nowait;
  if not found or trip_n.head_version<>link_n.trip_head_version or exists(select 1 from privacy_private.trip_deletions where trip_id=trip_n.id)
   or exists(select 1 from public.trip_archives where trip_id=trip_n.id and owner_id=u) then raise exception 'SERVICE_TASK_CONFLICT';end if;
  perform 1 from turn_private.assistant_goal_trip_links where goal_id=link_n.goal_id and owner_id=u and operation_id=link_n.operation_id for share nowait;
  if not found then raise exception 'SERVICE_TASK_CONFLICT';end if;
 end if;
 perform 1 from turn_private.assistant_conversations where id=(v->>'conversationId')::uuid and owner_id=u and policy_id=policy_n for update nowait;
 if not found then raise exception 'DATA_POLICY_BLOCKED';end if;
 select * into g from turn_private.assistant_goals where id=(v->>'goalId')::uuid and owner_id=u and conversation_id=(v->>'conversationId')::uuid for update nowait;
 if not found then raise exception 'SERVICE_TASK_CONFLICT';end if;
 basis_n:=turn_private.directions_write_basis_v1(u,policy_n,g.conversation_id,g.id);
 if basis_n->>'kind'<>'directions_write_basis' or basis_n->'goalVersion' is distinct from v->'expectedGoalVersion'
  or (basis_n->>'parentMessageId')::uuid<>(v->>'parentMessageId')::uuid or basis_n->'messageSequence' is distinct from v->'expectedSourceSequence'
  or basis_n->'intakeRevision' is distinct from v->'expectedIntakeRevision' or basis_n->'intakeDigest' is distinct from v->'expectedIntakeDigest' then raise exception 'SERVICE_TASK_CONFLICT';end if;
 if turn_private.explicit_intake_memory_binding_v1(u,v->'memoryBasis') is null then raise exception 'SERVICE_TASK_CONFLICT';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',(m->>'id')::uuid,'revision',(m->>'revision')::bigint) order by (m->>'id')::uuid),'[]') into memories_n from jsonb_array_elements(v->'memoryBasis') m;
 content_n:=turn_private.directions_initial_projection_v1(v->'intake',v->>'locale');
 select * into prior_i from turn_private.assistant_directions_intakes_v1 where owner_id=u and goal_id=g.id order by intake_revision desc limit 1;
 -- Only the explicit original link transition may preserve the previous
 -- selected/saved/edited relative state. No arbitrary historical account scan.
 if prior_i.message_id is not null and link_n.trip_id is not null and g.scope_version=prior_i.goal_version+1
  and link_n.goal_scope_version=g.scope_version and link_n.source_kind='native_user_confirmed'
  and prior_i.message_id=(v->>'parentMessageId')::uuid and prior_i.intake=v->'intake' and prior_i.memory_basis=memories_n then
  select * into old_s from turn_private.directions_result_sources_v1 where message_id=prior_i.message_id and owner_id=u;
  select * into old_a from turn_private.result_artifacts where id=old_s.artifact_id and owner_id=u and goal_id=g.id and lifecycle='active' for share nowait;
  if old_a.id is not null then
   select * into old_r from turn_private.result_revisions where artifact_id=old_a.id and owner_id=u and revision=old_a.current_revision;
   if old_r.artifact_id is not null and turn_private.directions_history_readable_v1(u,old_a.id,old_r.revision,g.id)
    and old_r.content->'intake'=v->'intake' and old_r.memory_basis=memories_n then
    content_n:=content_n||jsonb_build_object('selectedDirectionId',old_r.content->'selectedDirectionId','draft',old_r.content->'draft');
    if not turn_private.valid_travel_directions_v1(content_n) then raise exception 'SERVICE_TASK_CONFLICT';end if;
    previous_n:=old_a.id;previous_revision_n:=old_r.revision;
   end if;
  end if;
 end if;
 admitted_n:=public.submit_service_task_turn((v->>'threadId')::uuid,(v->>'turnId')::uuid,(v->>'taskKey')::uuid,policy_n,v->>'locale',v->>'text',(v->>'taskId')::uuid,1,'new_goal',null);
 if admitted_n->>'kind' is distinct from 'accepted' or admitted_n->>'reused'='true' then raise exception 'SERVICE_TASK_CONFLICT';end if;
 message_n:=public.submit_assistant_message_v1(g.conversation_id,(v->>'messageId')::uuid,(v->>'messageKey')::uuid,policy_n,v->>'locale',v->>'text','follow_up',g.id,g.scope_version,(v->>'taskId')::uuid,(v->>'parentMessageId')::uuid,null);
 if message_n->>'kind' is distinct from 'accepted' or message_n->>'reused'='true' then raise exception 'SERVICE_TASK_CONFLICT';end if;
 update turn_private.work set execution_mode='travel_directions_v1' where turn_id=(v->>'turnId')::uuid and owner_id=u and state='queued' and execution_mode='text';
 if not found then raise exception 'SERVICE_TASK_CONFLICT';end if;
 insert into turn_private.assistant_directions_intakes_v1(message_id,owner_id,conversation_id,goal_id,task_id,task_turn_id,policy_id,consent_id,planning_policy_id,planning_consent_id,message_sequence,goal_version,intake_revision,idempotency_key,request_bytes_digest,intake,memory_basis)
 select (v->>'messageId')::uuid,u,g.conversation_id,g.id,(v->>'taskId')::uuid,(v->>'turnId')::uuid,policy_n,a.consent_id,(v->>'planningPolicyId')::uuid,c.consent_id,(message_n->>'sequence')::bigint,g.scope_version,(v->>'expectedIntakeRevision')::integer+1,(v->>'messageKey')::uuid,bytes_digest_n,v->'intake',memories_n
 from turn_private.assistant_conversations a join turn_private.planning_consents c on c.owner_id=u and c.policy_id=(v->>'planningPolicyId')::uuid and c.revoked_at is null where a.id=g.conversation_id and a.owner_id=u returning * into i;
 if i.message_id is null then raise exception 'DATA_POLICY_BLOCKED';end if;
 source_digest_n:=turn_private.directions_current_basis_v1(u,i.message_id);if source_digest_n is null then raise exception 'SERVICE_TASK_CONFLICT';end if;
 output_n:=turn_private.directions_task_output_v1(v->>'locale',previous_n is not null);
 insert into turn_private.directions_result_sources_v1(artifact_id,owner_id,message_id,task_turn_id,source_digest,initial_content_digest,initial_output_digest,previous_artifact_id,previous_revision,publication_key)
 values(artifact_n,u,i.message_id,i.task_turn_id,source_digest_n,encode(sha256(convert_to(content_n::text,'UTF8')),'hex'),encode(sha256(convert_to(output_n,'UTF8')),'hex'),previous_n,previous_revision_n,publication_n);
 token_n:=turn_private.claim_directions_inline_v1(i.task_turn_id,u);
 if public.complete_text_work(i.task_turn_id,token_n,'answered',output_n)->>'kind' is distinct from 'finished' then raise exception 'SERVICE_TASK_CONFLICT';end if;
 published_n:=turn_private.publish_result_v2(u,artifact_n,0,publication_n,i.task_id,i.goal_id,i.message_id,trip_n.id,trip_n.head_version,i.goal_version,i.memory_basis,content_n,'[]',true);
 if published_n->>'kind' is distinct from 'published' or public.read_result_artifact_v2(artifact_n,1)->>'current' is distinct from 'true' then raise exception 'SERVICE_TASK_CONFLICT';end if;
 return jsonb_build_object('kind','published','artifactId',artifact_n,'revision',1,'reused',false,'taskId',i.task_id,'turnId',i.task_turn_id,
  'conversationId',i.conversation_id,'goalId',i.goal_id,'goalVersion',i.goal_version,'inputMessageId',i.message_id,'inputSequence',i.message_sequence,
  'intakeRevision',i.intake_revision,'intakeDigest',source_digest_n,'current',true);
exception when lock_not_available then raise exception 'SERVICE_TASK_CONFLICT';
end $$;
revoke all on function turn_private.submit_directions_v1(uuid,uuid,jsonb,text) from public,anon,authenticated,service_role;

-- Constituent: actions.candidate.sql
-- ARTIFACT ONLY. Four independent explicit actions, same original result chain.
-- Actor is current original JWT identity; it need not equal producer session.
create function turn_private.directions_append_patch_v1(draft_n jsonb,snapshot_n jsonb,start_n date,prefix_n text,version_n integer)
returns jsonb language plpgsql immutable set search_path='' as $$
declare d jsonb;item_n jsonb;ops_n jsonb:='[]';day_id_n text;item_id_n text;date_n text;n integer;patch_n jsonb;
begin
 if jsonb_typeof(draft_n->'days') is distinct from 'array' or jsonb_array_length(draft_n->'days') not between 1 and 30
  or prefix_n !~ '^[A-Za-z0-9_-]{1,40}$' or start_n is null then raise exception 'INVALID_INPUT';end if;
 for d in select value from jsonb_array_elements(draft_n->'days') loop
  date_n:=to_char(start_n+(d->>'ordinal')::integer-1,'YYYY-MM-DD');day_id_n:=prefix_n||'_d'||(d->>'ordinal');
  if exists(select 1 from jsonb_array_elements(snapshot_n->'days') old where old->>'date'=date_n or old->>'id'=day_id_n)
   or exists(select 1 from jsonb_array_elements(snapshot_n->'days') old cross join lateral jsonb_array_elements(coalesce(old->'items','[]')) item where item->>'id'=day_id_n) then raise exception 'SERVICE_TASK_CONFLICT';end if;
  ops_n:=ops_n||jsonb_build_array(jsonb_build_object('kind','upsert_day','dayId',day_id_n,'date',date_n,'timeZone','Asia/Shanghai'));
  n:=0;for item_n in select value from jsonb_array_elements(d->'activities') loop
   n:=n+1;item_id_n:=day_id_n||'_i'||n;
   if exists(select 1 from jsonb_array_elements(snapshot_n->'days') old where old->>'id'=item_id_n)
    or exists(select 1 from jsonb_array_elements(snapshot_n->'days') old cross join lateral jsonb_array_elements(coalesce(old->'items','[]')) item where item->>'id'=item_id_n) then raise exception 'SERVICE_TASK_CONFLICT';end if;
   ops_n:=ops_n||jsonb_build_array(jsonb_build_object('kind','upsert_item','dayId',day_id_n,'itemId',item_id_n,'title',item_n));
  end loop;
 end loop;
 patch_n:=jsonb_build_object('expectedVersion',version_n,'operations',ops_n);
 perform public.apply_trip_content_patch(snapshot_n,patch_n); -- original caps/closed Patch validation
 return patch_n;
end $$;

create function turn_private.act_directions_v1(u uuid,policy_n uuid,action_n text,v jsonb,bytes_digest_n text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare op turn_private.directions_operations_v1%rowtype;a turn_private.result_artifacts%rowtype;r turn_private.result_revisions%rowtype;
 i turn_private.assistant_directions_intakes_v1%rowtype;s turn_private.directions_result_sources_v1%rowtype;
 link_n turn_private.assistant_goal_trip_links%rowtype;trip_n public.trips%rowtype;proposal_n record;
 content_n jsonb;draft_n jsonb;days_n jsonb;replacement_n jsonb;published_n jsonb;receipt_n jsonb;qualified_n jsonb;
 source_digest_n text;next_revision_n integer;proposal_artifact_n uuid;proposal_key_n uuid;patch_n jsonb;snapshot_n jsonb;start_n date;
begin
 if u is distinct from turn_private.text_owner() or action_n not in('choose','save','edit','bind') or not turn_private.directions_input_v1(action_n,v)
  or bytes_digest_n is null or bytes_digest_n !~ '^[a-f0-9]{64}$' then raise exception 'INVALID_INPUT';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,34));
 perform pg_advisory_xact_lock(hashtextextended('directions-op:'||u::text||':'||(v->>'operationId'),0));
 select * into op from turn_private.directions_operations_v1 where owner_id=u and operation_id=(v->>'operationId')::uuid;
 if found then
  if op.request_bytes_digest<>bytes_digest_n or op.action<>action_n then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;
  if op.erased or op.artifact_id is distinct from (v->>'artifactId')::uuid or op.expected_revision is distinct from (v->>'expectedRevision')::integer then raise exception 'SERVICE_TASK_CONFLICT';end if;
  qualified_n:=public.read_result_artifact_v2(op.artifact_id,op.result_revision);
  if qualified_n->>'kind' is distinct from 'result_artifact' then raise exception 'DATA_POLICY_BLOCKED';end if;
  perform 1 from turn_private.assistant_directions_intakes_v1 x where x.message_id=op.source_message_id and x.owner_id=u and x.policy_id=policy_n;
  if not found then raise exception 'DATA_POLICY_BLOCKED';end if;
  if action_n='bind' then
   perform 1 from public.trip_proposals p where p.id=op.proposal_id and p.owner_id=u and p.trip_id=op.trip_id;
   if not found then raise exception 'SERVICE_TASK_CONFLICT';end if;
  end if;
  return op.receipt||jsonb_build_object('reused',true);
 end if;
 -- Trip locks precede original source/link/goal checks and result mutation.
 select * into a from turn_private.result_artifacts where id=(v->>'artifactId')::uuid and owner_id=u and lifecycle='active';
 if not found then raise exception 'DATA_POLICY_BLOCKED';end if;
 if a.trip_id is not null then
  select * into trip_n from public.trips where id=a.trip_id and owner_id=u for share nowait;
  if not found then raise exception 'SERVICE_TASK_CONFLICT';end if;
 end if;
 select * into a from turn_private.result_artifacts where id=a.id and owner_id=u and lifecycle='active' for update nowait;
 if not found or a.current_revision<>(v->>'expectedRevision')::integer then raise exception 'REVISION_CONFLICT';end if;
 select * into r from turn_private.result_revisions where artifact_id=a.id and owner_id=u and revision=a.current_revision;
 if not found or r.content->>'schemaVersion'<>'travel-directions/1' then raise exception 'DATA_POLICY_BLOCKED';end if;
 select * into s from turn_private.directions_result_sources_v1 where artifact_id=a.id and owner_id=u;
 select * into i from turn_private.assistant_directions_intakes_v1 where message_id=s.message_id and owner_id=u;
 if s.artifact_id is null or i.message_id is null or i.policy_id<>policy_n or i.task_id<>a.task_id or i.goal_id<>a.goal_id
  or i.task_turn_id<>r.task_turn_id or turn_private.result_state_v2(a,r)->>'current' is distinct from 'true' then raise exception 'SERVICE_TASK_CONFLICT';end if;
 source_digest_n:=turn_private.directions_current_basis_v1(u,i.message_id);
 if source_digest_n is null or source_digest_n<>s.source_digest then raise exception 'SERVICE_TASK_CONFLICT';end if;
 content_n:=r.content;next_revision_n:=r.revision+1;
 if action_n='choose' then
  if not exists(select 1 from jsonb_array_elements(content_n->'directions') d where d->>'id'=v->>'directionId') then raise exception 'INVALID_INPUT';end if;
  content_n:=content_n||jsonb_build_object('selectedDirectionId',v->'directionId','draft',null);
 elsif action_n='save' then
  if content_n->'selectedDirectionId'='null'::jsonb then raise exception 'SERVICE_TASK_CONFLICT';end if;
  -- An existing saved/edited draft is preserved by another explicit save.
  draft_n:=content_n->'draft';
  if draft_n='null'::jsonb then draft_n:=turn_private.directions_relative_projection_v1(i.intake,(select locale from turn_private.assistant_messages where id=i.message_id and owner_id=u),content_n->>'selectedDirectionId');end if;
  content_n:=content_n||jsonb_build_object('draft',draft_n);
 elsif action_n='edit' then
  draft_n:=content_n->'draft';if draft_n='null'::jsonb then raise exception 'SERVICE_TASK_CONFLICT';end if;
  for replacement_n in select value from jsonb_array_elements(v->'replacements') loop
   if not exists(select 1 from jsonb_array_elements(draft_n->'days') d where d->'ordinal'=replacement_n->'ordinal') then raise exception 'INVALID_INPUT';end if;
  end loop;
  select coalesce(jsonb_agg(coalesce((select e from jsonb_array_elements(v->'replacements') e where e->'ordinal'=d->'ordinal'),d) order by (d->>'ordinal')::integer),'[]') into days_n from jsonb_array_elements(draft_n->'days') d;
  content_n:=content_n||jsonb_build_object('draft',draft_n||jsonb_build_object('days',days_n));
 else
  if a.trip_id is distinct from (v->>'tripId')::uuid or trip_n.head_version is distinct from (v->>'expectedTripVersion')::integer then raise exception 'SERVICE_TASK_CONFLICT';end if;
  draft_n:=content_n->'draft';if draft_n='null'::jsonb or content_n->'selectedDirectionId'='null'::jsonb or jsonb_array_length(draft_n->'days')=0 then raise exception 'SERVICE_TASK_CONFLICT';end if;
  start_n:=(v->>'startDate')::date;
  if i.intake->'dates'<>'null'::jsonb and (i.intake->'dates'->>'startDate'<>v->>'startDate'
   or (i.intake->'dates'->>'endDate')::date<>start_n+jsonb_array_length(draft_n->'days')-1) then raise exception 'SERVICE_TASK_CONFLICT';end if;
  select * into link_n from turn_private.assistant_goal_trip_links where goal_id=i.goal_id and owner_id=u and conversation_id=i.conversation_id and trip_id=trip_n.id for share nowait;
  if not found or link_n.terminal_unlinked or link_n.source_kind<>'native_user_confirmed' or link_n.goal_scope_version<>i.goal_version or link_n.trip_head_version<>trip_n.head_version then raise exception 'SERVICE_TASK_CONFLICT';end if;
  snapshot_n:=public.trip_content_snapshot(trip_n.id,trip_n.title);
  patch_n:=turn_private.directions_append_patch_v1(draft_n,snapshot_n,start_n,'dir_'||replace(v->>'operationId','-',''),trip_n.head_version);
  select * into proposal_n from public.create_trip_proposal_patch(trip_n.id,patch_n);
