-- Constituent: gateway.candidate.sql
-- ARTIFACT ONLY: one closed authenticated gateway shared by original Native/Web.
-- No canonical RPC is enabled until full privacy/static after batch is reviewed.
create function public.native_travel_directions_v1(p_action text,p_policy_id uuid,p_input_bytes text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;v jsonb;digest_n text;
begin
 if (select auth.role()) is distinct from 'authenticated' then raise exception 'UNAUTHENTICATED';end if;
 u:=turn_private.text_owner();
 if p_action is null or p_action not in('basis','intake','submit','choose','save','edit','bind') or p_policy_id is null
  or p_input_bytes is null or octet_length(convert_to(p_input_bytes,'UTF8'))>16384 or left(p_input_bytes,1)=U&'\FEFF' then raise exception 'INVALID_INPUT';end if;
 begin v:=p_input_bytes::jsonb;exception when invalid_text_representation or numeric_value_out_of_range or untranslatable_character or character_not_in_repertoire then raise exception 'INVALID_INPUT';end;
 if not turn_private.directions_input_v1(p_action,v) then raise exception 'INVALID_INPUT';end if;
 -- UUID values are cast to original identity types only after closed parsing.
 -- Digest hashes the untouched original UTF8 bytes, not normalized JSONB.
 digest_n:=encode(sha256(convert_to(p_input_bytes,'UTF8')),'hex');
 if p_action='basis' then return turn_private.directions_write_basis_v1(u,p_policy_id,(v->>'conversationId')::uuid,(v->>'goalId')::uuid);end if;
 if p_action='intake' then return turn_private.directions_read_intake_v1(u,p_policy_id,(v->>'conversationId')::uuid,(v->>'goalId')::uuid);end if;
 if p_action='submit' then return turn_private.submit_directions_v1(u,p_policy_id,v,digest_n);end if;
 return turn_private.act_directions_v1(u,p_policy_id,p_action,v,digest_n);
end $$;
