create function turn_private.directions_parents_v1(relation_n text,v jsonb)
returns table(kind text,entity_id uuid) language plpgsql volatile security definer set search_path='' as $$
declare spec record;raw_n text;i turn_private.assistant_directions_intakes_v1%rowtype;m jsonb;
begin
 if relation_n not in('turn_private.assistant_directions_intakes_v1','turn_private.directions_result_sources_v1','turn_private.directions_operations_v1') then return;end if;
 for spec in select * from(values('artifact_id','artifactIds'),('previous_artifact_id','artifactIds'),('proposal_artifact_id','artifactIds'),('message_id','messageIds'),('source_message_id','messageIds'),('task_turn_id','turnIds'),('task_id','taskIds'),('goal_id','goalIds'),('conversation_id','conversationIds')) refs(column_n,kind_n) loop
  raw_n:=v->>spec.column_n;
  if raw_n is not null then
   if not turn_private.directions_uuid_v1(to_jsonb(raw_n)) then raise exception 'INVALID_DIRECTIONS_REFERENCE';end if;
   return query select spec.kind_n::text,raw_n::uuid;
  end if;
 end loop;
 -- Purpose metadata has no duplicate parent fields: resolve the original intake
 -- by exact existing source identity and owner, never arbitrary UUID guessing.
 if relation_n<>'turn_private.assistant_directions_intakes_v1' then
  select * into i from turn_private.assistant_directions_intakes_v1 where message_id=coalesce(nullif(v->>'message_id',''),nullif(v->>'source_message_id',''))::uuid and owner_id=(v->>'owner_id')::uuid;
  if found then
   return query select 'conversationIds'::text,i.conversation_id union select 'goalIds',i.goal_id union select 'taskIds',i.task_id;
  end if;
 end if;
end $$;

create function turn_private.directions_erase_authorized_v1(owner_n uuid,v jsonb)
returns boolean language plpgsql volatile security definer set search_path='' as $$
declare artifact_n uuid:=nullif(v->>'artifact_id','')::uuid;turn_n uuid:=nullif(v->>'task_turn_id','')::uuid;
 message_n uuid:=coalesce(nullif(v->>'message_id',''),nullif(v->>'source_message_id',''))::uuid;
 i turn_private.assistant_directions_intakes_v1%rowtype;f privacy_private.linked_delete_fences_v1%rowtype;
begin
 if owner_n is null then return false;end if;
 if not exists(select 1 from auth.users where id=owner_n) then return true;end if;
 if pg_trigger_depth()>0 and (
  (turn_n is not null and not exists(select 1 from turn_private.text_content c where c.turn_id=turn_n and c.owner_id=owner_n))
  or (message_n is not null and not exists(select 1 from turn_private.assistant_messages m where m.id=message_n and m.owner_id=owner_n))
  or (artifact_n is not null and not exists(select 1 from turn_private.result_artifacts a where a.id=artifact_n and a.owner_id=owner_n))
 ) then return true;end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where message_id=message_n and owner_id=owner_n;
 if (artifact_n is not null and result_data_private.proof_v1('artifactIds',artifact_n))
  or (artifact_n is not null and conversation_data_private.proof_v1(owner_n,'artifactIds',artifact_n))
  or (turn_n is not null and conversation_data_private.proof_v1(owner_n,'turnIds',turn_n))
  or (message_n is not null and conversation_data_private.proof_v1(owner_n,'messageIds',message_n))
  or (i.message_id is not null and (conversation_data_private.proof_v1(owner_n,'conversationIds',i.conversation_id) or conversation_data_private.proof_v1(owner_n,'goalIds',i.goal_id) or conversation_data_private.proof_v1(owner_n,'taskIds',i.task_id))) then return true;end if;
 if exists(select 1 from turn_data_private.transaction_proofs_v1 p join turn_data_private.operations_v1 o on o.request_id=p.request_id and o.owner_id=p.owner_id
  where p.transaction_id=pg_current_xact_id() and p.owner_id=owner_n and p.source_digest=o.source_digest and p.graph=o.graph and p.expires_at=o.expires_at
   and p.expires_at>floor(extract(epoch from clock_timestamp())*1000)::bigint
   and ((turn_n is not null and p.graph->'turnIds' ? turn_n::text) or (artifact_n is not null and p.graph->'artifactIds' ? artifact_n::text))) then return true;end if;
 for f in select * from privacy_private.linked_delete_fences_v1 where owner_id=owner_n
  and ((entity_kind='turn' and entity_id=turn_n) or (entity_kind='artifact' and entity_id=artifact_n) or (i.message_id is not null and entity_kind='task' and entity_id=i.task_id)) loop
  if privacy_private.linked_delete_erase_authority_v1(f.request_id,f.entity_kind,f.entity_id) then return true;end if;
 end loop;return false;
end $$;

create function turn_private.guard_directions_operation_v1() returns trigger
language plpgsql volatile security definer set search_path='' as $$
begin
 if tg_op='DELETE' then
  if exists(select 1 from auth.users where id=old.owner_id) then raise exception 'IMMUTABLE_DIRECTIONS_OPERATION';end if;
  return old;
 end if;
 if old.erased or not new.erased
  or to_jsonb(new)-array['erased','artifact_id','source_message_id','task_turn_id','expected_revision','result_revision','source_digest','output_content_digest','trip_id','proposal_id','proposal_artifact_id','receipt']
   is distinct from to_jsonb(old)-array['erased','artifact_id','source_message_id','task_turn_id','expected_revision','result_revision','source_digest','output_content_digest','trip_id','proposal_id','proposal_artifact_id','receipt']
  or not turn_private.directions_erase_authorized_v1(old.owner_id,to_jsonb(old)) then raise exception 'IMMUTABLE_DIRECTIONS_OPERATION';end if;
 return new;
end $$;
create trigger immutable_directions_operation_v1 before update or delete on turn_private.directions_operations_v1 for each row execute function turn_private.guard_directions_operation_v1();

create function turn_private.guard_directions_source_delete_v1() returns trigger
language plpgsql volatile security definer set search_path='' as $$
begin
 if not turn_private.directions_erase_authorized_v1(old.owner_id,to_jsonb(old)) then raise exception 'DIRECTIONS_SOURCE_ERASE_DENIED';end if;
 return old;
end $$;
create trigger directions_intake_delete_v1 before delete on turn_private.assistant_directions_intakes_v1 for each row execute function turn_private.guard_directions_source_delete_v1();
create trigger directions_result_source_delete_v1 before delete on turn_private.directions_result_sources_v1 for each row execute function turn_private.guard_directions_source_delete_v1();
