-- Constituent: witness.candidate.sql
-- ARTIFACT ONLY. Selected owned source witness joins the existing graph digest.
-- Original public counts stay unchanged; all rows/bytes enter original caps.
create function turn_private.directions_source_witness_v1(u uuid,scope_n text,g jsonb)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare inputs_n uuid[];artifacts_n uuid[];rows_n jsonb:='[]';r record;document_n jsonb;effect_n text;total_n integer:=0;bytes_n bigint:=0;
begin
 if u is null or scope_n not in('result','conversation','turn','d3') or jsonb_typeof(g) is distinct from 'object' then raise exception 'INVALID_DIRECTIONS_SCOPE';end if;
 if scope_n='result' then inputs_n:=array[]::uuid[];
 elsif scope_n='turn' then
  select coalesce(array_agg(i.message_id order by i.message_id),array[]::uuid[]) into inputs_n from turn_private.assistant_directions_intakes_v1 i where i.owner_id=u
   and (i.task_turn_id=any(privacy_private.linked_delete_array_v1(coalesce(g->'turnIds','[]'))) or i.message_id=any(privacy_private.linked_delete_array_v1(coalesce(g->'messageIds','[]'))));
 else
  select coalesce(array_agg(i.message_id order by i.message_id),array[]::uuid[]) into inputs_n from turn_private.assistant_directions_intakes_v1 i where i.owner_id=u
   and (i.conversation_id=any(privacy_private.linked_delete_array_v1(coalesce(g->'conversationIds','[]'))) or i.goal_id=any(privacy_private.linked_delete_array_v1(coalesce(g->'goalIds','[]')))
    or i.task_id=any(privacy_private.linked_delete_array_v1(coalesce(g->'taskIds','[]'))) or i.task_turn_id=any(privacy_private.linked_delete_array_v1(coalesce(g->'turnIds','[]'))) or i.message_id=any(privacy_private.linked_delete_array_v1(coalesce(g->'messageIds','[]'))));
 end if;
 select coalesce(array_agg(distinct id order by id),array[]::uuid[]) into artifacts_n from(
  select unnest(privacy_private.linked_delete_array_v1(coalesce(g->'artifactIds','[]'))) id
  union select s.artifact_id from turn_private.directions_result_sources_v1 s where s.owner_id=u and s.message_id=any(inputs_n)) refs;
 for r in select * from(
  select 'turn_private.assistant_directions_intakes_v1'::text relation_n,'message_id'::text key_n,i.message_id entity_n,to_jsonb(i) document_n,
   case when i.message_id=any(inputs_n) then 'erase' else 'retain' end effect_n
   from turn_private.assistant_directions_intakes_v1 i where i.owner_id=u and (i.message_id=any(inputs_n) or exists(select 1 from turn_private.directions_result_sources_v1 s where s.owner_id=u and s.message_id=i.message_id and s.artifact_id=any(artifacts_n)))
  union all select 'turn_private.directions_result_sources_v1','artifact_id',s.artifact_id,to_jsonb(s),'erase' from turn_private.directions_result_sources_v1 s where s.owner_id=u and s.artifact_id=any(artifacts_n)
  union all select 'turn_private.directions_operations_v1','operation_id',o.operation_id,to_jsonb(o),'scrub' from turn_private.directions_operations_v1 o where o.owner_id=u and not o.erased and (o.artifact_id=any(artifacts_n) or o.proposal_artifact_id=any(artifacts_n) or o.source_message_id=any(inputs_n))
 ) selected_rows order by relation_n collate "C",entity_n loop
  total_n:=total_n+1;if total_n>4100 then raise exception 'DIRECTIONS_SCOPE_TOO_LARGE';end if;
  document_n:=jsonb_build_object('table',r.relation_n,'key',jsonb_build_object(r.key_n,r.entity_n),'effect',r.effect_n,'row',r.document_n);
  bytes_n:=bytes_n+octet_length(document_n::text);if bytes_n>1000000 then raise exception 'DIRECTIONS_SCOPE_TOO_LARGE';end if;
  rows_n:=rows_n||jsonb_build_array(document_n);
 end loop;
 return jsonb_build_object('rows',rows_n,'rowCount',total_n,'bytes',bytes_n,'digest',encode(sha256(convert_to(rows_n::text,'UTF8')),'hex'));
end $$;

create function turn_private.lock_directions_witness_v1(u uuid,scope_n text,g jsonb,witness_n jsonb)
returns void language plpgsql volatile security definer set search_path='' as $$
declare r jsonb;
begin
 for r in select value from jsonb_array_elements(witness_n->'rows') order by value->>'table' collate "C",(value->'key')::text loop
  case r->>'table'
   when 'turn_private.assistant_directions_intakes_v1' then perform 1 from turn_private.assistant_directions_intakes_v1 where owner_id=u and message_id=(r->'key'->>'message_id')::uuid for update nowait;
   when 'turn_private.directions_result_sources_v1' then perform 1 from turn_private.directions_result_sources_v1 where owner_id=u and artifact_id=(r->'key'->>'artifact_id')::uuid for update nowait;
   when 'turn_private.directions_operations_v1' then perform 1 from turn_private.directions_operations_v1 where owner_id=u and operation_id=(r->'key'->>'operation_id')::uuid for update nowait;
   else raise exception 'UNKNOWN_DIRECTIONS_RELATION';
  end case;
  if not found then raise exception 'DIRECTIONS_SOURCE_CHANGED';end if;
 end loop;
 if turn_private.directions_source_witness_v1(u,scope_n,g) is distinct from witness_n then raise exception 'DIRECTIONS_SOURCE_CHANGED';end if;
end $$;

create function turn_private.erase_directions_witness_v1(u uuid,witness_n jsonb)
returns void language plpgsql volatile security definer set search_path='' as $$
declare r jsonb;
begin
 -- Existing original proof/xid and selected entity guards are mandatory.
 -- Operation receipts become irreversible minimal replay fences before parents.
 for r in select value from jsonb_array_elements(witness_n->'rows') where value->>'effect'='scrub' loop
  if r->>'table'<>'turn_private.directions_operations_v1' then raise exception 'UNKNOWN_DIRECTIONS_RELATION';end if;
  update turn_private.directions_operations_v1 set erased=true,artifact_id=null,source_message_id=null,task_turn_id=null,expected_revision=null,result_revision=null,source_digest=null,output_content_digest=null,trip_id=null,proposal_id=null,proposal_artifact_id=null,receipt=null
   where owner_id=u and operation_id=(r->'key'->>'operation_id')::uuid and not erased;
  if not found then raise exception 'DIRECTIONS_SOURCE_CHANGED';end if;
 end loop;
 for r in select value from jsonb_array_elements(witness_n->'rows') where value->>'effect'='erase' order by case value->>'table' when 'turn_private.directions_result_sources_v1' then 0 else 1 end loop
  case r->>'table'
   when 'turn_private.directions_result_sources_v1' then delete from turn_private.directions_result_sources_v1 where owner_id=u and artifact_id=(r->'key'->>'artifact_id')::uuid;
   when 'turn_private.assistant_directions_intakes_v1' then delete from turn_private.assistant_directions_intakes_v1 where owner_id=u and message_id=(r->'key'->>'message_id')::uuid;
   else raise exception 'UNKNOWN_DIRECTIONS_RELATION';
  end case;
  if not found then raise exception 'DIRECTIONS_SOURCE_CHANGED';end if;
 end loop;
end $$;
revoke all on function turn_private.directions_source_witness_v1(uuid,text,jsonb),turn_private.lock_directions_witness_v1(uuid,text,jsonb,jsonb),
 turn_private.erase_directions_witness_v1(uuid,jsonb) from public,anon,authenticated,service_role;

-- Constituent: privacy-handlers.after.sql
-- ARTIFACT ONLY: unchanged original public count keys, complete extra sourceDigest/4100/1MB budget.
CREATE OR REPLACE FUNCTION result_data_private.parents_v1(relation_n text, v jsonb)
 RETURNS TABLE(kind text, entity_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare doc_n jsonb;sets_n uuid[];seed_n uuid[];n integer:=0;
begin
 return query select * from turn_private.directions_parents_v1(relation_n,v);
 return query select * from result_data_private.json_references_v1(result_data_private.documents_v1(relation_n,v));
 -- Only these three actual relations can have a notification parent in the
 -- existing helper. Other rows still undergo the complete typed JSON walk.
 if relation_n in('notification_private.outbox','notification_private.attempts','notification_private.operations') then
  for doc_n in select * from result_data_private.notification_parents_v1(relation_n,v) loop
   return query select * from result_data_private.json_references_v1(doc_n);
  end loop;
 end if;
 if relation_n='turn_private.result_artifacts' and notification_private.uuid(v->'id') then return query select 'artifactIds'::text,(v->>'id')::uuid;end if;
 if relation_n='turn_private.planning_v2_collector_origins' and notification_private.uuid(v->'request_id') then return query select 'journalIds'::text,(v->>'request_id')::uuid;end if;
 if relation_n='turn_private.result_revisions' and notification_private.uuid(v->'idempotency_key') then return query select 'publicationKeys'::text,(v->>'idempotency_key')::uuid;end if;
 if relation_n='turn_private.planning_v2_execution_runs' and notification_private.uuid(v->'id') then return query select 'executionIds'::text,(v->>'id')::uuid;end if;
 if relation_n='turn_private.planning_v2_model_local_journal' and notification_private.uuid(v->'request_id') then return query select 'journalIds'::text,(v->>'request_id')::uuid;end if;
 if relation_n like 'turn_private.planning_%' then
  -- For execution-less callbacks, the retained original job still identifies
  -- the erased parent. Financial tables are not enrolled into this join.
  return query select 'artifactIds'::text,j.artifact_id from turn_private.planning_comparisons j
   where j.turn_id::text=v->>'turn_id' or j.turn_id::text=v->'binding'->>'turn'
    or j.turn_id in(select r.turn_id from turn_private.planning_v2_execution_runs r where r.id::text=v->>'execution_id')
    or j.turn_id in(select b.turn_id from turn_private.planning_v2_model_attempt_bindings b
      where b.scope_id::text=v->>'scope_id' and b.attempt_id::text=v->>'attempt_id');
 end if;
 if relation_n like 'knowledge_review_private.source_impact_%' then
  select coalesce(array_agg(id),array[]::uuid[]) into seed_n from(
   select nullif(v->>'set_id','')::uuid id union select (v->>'id')::uuid where relation_n='knowledge_review_private.source_impact_sets'
   union select set_id from knowledge_review_private.source_impact_items where id=nullif(v->>'item_id','')::uuid
   union select set_id from knowledge_review_private.source_impact_outbox where id=nullif(v->>'delivery_id','')::uuid
   union select set_id from knowledge_review_private.source_impact_projections where id in(nullif(v->>'projection_id','')::uuid,nullif(v->>'receipt_id','')::uuid)) seeds;
  sets_n:=result_data_private.impact_sets_v1(result_data_private.empty_graph_v1(),seed_n);
  if cardinality(sets_n)>4100 then raise exception 'RESULT_CAPACITY';end if;
  for doc_n in select to_jsonb(s) from knowledge_review_private.source_impact_sets s where id=any(sets_n)
   union all select to_jsonb(s) from knowledge_review_private.source_impact_items s where set_id=any(sets_n)
   union all select to_jsonb(s) from knowledge_review_private.source_impact_pages s where set_id=any(sets_n)
   union all select to_jsonb(s) from knowledge_review_private.source_impact_outbox s where set_id=any(sets_n)
   union all select to_jsonb(s) from knowledge_review_private.source_impact_projections s where set_id=any(sets_n)
   union all select to_jsonb(s) from knowledge_review_private.source_impact_review_requests s where delivery_id in(select id from knowledge_review_private.source_impact_outbox where set_id=any(sets_n)) or projection_id in(select id from knowledge_review_private.source_impact_projections where set_id=any(sets_n)) loop
   n:=n+1;if n>4100 then raise exception 'RESULT_CAPACITY';end if;
   return query select * from result_data_private.json_references_v1(doc_n);
  end loop;
 end if;
end$function$;

CREATE OR REPLACE FUNCTION conversation_data_private.parents_v1(relation_n text, v jsonb)
 RETURNS TABLE(kind text, entity_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare identity_n text:=conversation_data_private.entity_kind_v1(relation_n);parent_n jsonb;set_n uuid;item_n uuid;delivery_n uuid;projection_n uuid;sets_n uuid[];n integer:=0;
begin
 return query select * from turn_private.directions_parents_v1(relation_n,v);
 if identity_n is not null and notification_private.uuid(v->'id') then return query select identity_n,(v->>'id')::uuid;end if;
 return query select r.kind,r.entity_id from conversation_data_private.json_references_v1(conversation_data_private.documents_v1(relation_n,v)) r;
 if notification_private.uuid(v->'source_id') then
  return query select k,(v->>'source_id')::uuid from unnest(array['taskIds','artifactIds']) k;
 end if;
 if notification_private.uuid(v->'execution_id') then
  select to_jsonb(actual) into parent_n from turn_private.planning_v2_execution_runs actual where id=(v->>'execution_id')::uuid;
  if found then return query select r.kind,r.entity_id from conversation_data_private.json_references_v1(parent_n) r;end if;
 end if;
 if relation_n like 'knowledge_review_private.source_impact_%' then
  set_n:=nullif(v->>'set_id','')::uuid;item_n:=nullif(v->>'item_id','')::uuid;
  delivery_n:=nullif(v->>'delivery_id','')::uuid;projection_n:=nullif(v->>'projection_id','')::uuid;
  -- Seed every actual parent, including receipt_id and both sides of moves.
  select coalesce(array_agg(id),array[]::uuid[]) into sets_n from (
   select set_n id union select (v->>'id')::uuid where relation_n='knowledge_review_private.source_impact_sets'
   union select set_id from knowledge_review_private.source_impact_items where id=item_n
   union select set_id from knowledge_review_private.source_impact_outbox where id=delivery_n
   union select set_id from knowledge_review_private.source_impact_projections where id in(projection_n,nullif(v->>'receipt_id','')::uuid)
  ) parents;
  sets_n:=conversation_data_private.impact_sets_v1(conversation_data_private.empty_graph_v1(),sets_n);
  if cardinality(sets_n)>4100 then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
  for parent_n in select document_n from (
   select to_jsonb(s) document_n from knowledge_review_private.source_impact_sets s where id=any(sets_n)
   union all select to_jsonb(i) from knowledge_review_private.source_impact_items i where set_id=any(sets_n)
   union all select to_jsonb(p) from knowledge_review_private.source_impact_pages p where set_id=any(sets_n)
   union all select to_jsonb(p) from knowledge_review_private.source_impact_projections p where set_id=any(sets_n)
  ) documents limit 4101 loop
   n:=n+1;if n>4100 then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
   return query select r.kind,r.entity_id from conversation_data_private.json_references_v1(parent_n) r;
  end loop;
 end if;
end$function$;

CREATE OR REPLACE FUNCTION result_data_private.related_v1(relation_n text, v jsonb, g jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;parent_n jsonb;
begin
 if relation_n in('turn_private.assistant_directions_intakes_v1','turn_private.directions_result_sources_v1','turn_private.directions_operations_v1') then return false;end if; -- exact owned witness classification, not namespace exclusion
 -- Exact managed delivery copies are qualified/retired by assistantDelivery witness.
 if relation_n in ('turn_private.assistant_event_heads_v1','turn_private.assistant_events_v1') then return false;end if;
 if relation_n like 'privacy_private.%' then return false;end if;
 for r in select * from result_data_private.json_references_v1(result_data_private.documents_v1(relation_n,v)) loop
  if g->r.kind ? r.entity_id::text then return true;end if;
 end loop;
 for parent_n in select * from result_data_private.notification_parents_v1(relation_n,v) loop
  for r in select * from result_data_private.json_references_v1(parent_n) loop
   if g->r.kind ? r.entity_id::text then return true;end if;
  end loop;
 end loop;
 return relation_n='turn_private.planning_v2_collector_origins' and g->'journalIds' ? (v->>'request_id')
  or relation_n='turn_private.result_artifacts' and g->'artifactIds' ? (v->>'id')
  or relation_n='turn_private.planning_v2_execution_runs' and g->'executionIds' ? (v->>'id')
  or relation_n='turn_private.planning_v2_model_local_journal' and g->'journalIds' ? (v->>'request_id');
end$function$;

