CREATE OR REPLACE FUNCTION result_data_private.source_v1(u uuid, root_n uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a turn_private.result_artifacts%rowtype;m turn_private.assistant_messages%rowtype;t turn_private.service_tasks%rowtype;
 refs_n jsonb:=result_data_private.empty_refs_v1();g jsonb:=result_data_private.empty_graph_v1();rows_n jsonb:='[]';reverse_n jsonb:='[]';fingerprint_n jsonb;assistant_delivery_n jsonb;directions_n jsonb;
 erase_n jsonb:=result_data_private.zero_counts_v1('erase');retain_n jsonb:=result_data_private.zero_counts_v1('retain');authorities_n jsonb:='[]';witness_n jsonb;
 spec record;v jsonb;doc_n jsonb;key_n jsonb;r record;count_key text;effect_n text;conflicts_n text[]:=array[]::text[];
 turns_n uuid[];jobs_n uuid[];impact_n uuid[];id_n uuid;tuple_n jsonb;qualified_n boolean;n integer;total_n integer:=0;raw_bytes_n bigint:=0;
begin
 select * into a from turn_private.result_artifacts where id=root_n and owner_id=u;
 if not found then raise exception 'RESULT_SOURCE_UNAVAILABLE';end if;
 select * into m from turn_private.assistant_messages where id=a.input_message_id and owner_id=u;
 select * into t from turn_private.service_tasks where id=a.task_id and owner_id=u;
 if m.id is null or t.id is null or m.goal_id<>a.goal_id or m.task_id<>a.task_id or not exists(select 1 from turn_private.assistant_goals original where original.id=a.goal_id and original.owner_id=u and original.conversation_id=m.conversation_id) then raise exception 'RESULT_SOURCE_UNAVAILABLE';end if;
 authorities_n:=jsonb_build_array(jsonb_build_object('policyId',m.policy_id,'consentId',m.consent_id),jsonb_build_object('policyId',t.policy_id,'consentId',t.consent_id));
 authorities_n:=conversation_data_private.authorities_union_v1(authorities_n);
 perform conversation_data_private.authorities_current_v1(u,authorities_n);
 if not result_data_private.schema_supported_v1() then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 refs_n:=refs_n||jsonb_build_object('conversationIds',jsonb_build_array(m.conversation_id),'goalIds',jsonb_build_array(a.goal_id),'messageIds',jsonb_build_array(m.id),
  'taskIds',jsonb_build_array(t.id),'threadIds',case when t.thread_id is null then '[]'::jsonb else jsonb_build_array(t.thread_id) end,
  'tripIds',case when a.trip_id is null then '[]'::jsonb else jsonb_build_array(a.trip_id) end,
  'sourceArtifactIds',case when a.source_result_id is null then '[]'::jsonb else jsonb_build_array(a.source_result_id) end,
  'proposalIds',case when a.proposal_id is null then '[]'::jsonb else jsonb_build_array(a.proposal_id) end);
 select conversation_data_private.union_ids_v1(array_agg(task_turn_id)||array[t.goal_turn_id,t.last_turn_id,a.source_turn_id]) into turns_n from turn_private.result_revisions where artifact_id=root_n;
 refs_n:=jsonb_set(refs_n,'{turnIds}',to_jsonb(turns_n));
 select coalesce(jsonb_agg(id order by id),'[]') into doc_n from public.memory_profiles where owner_id=u and id in(
  select coalesce(b->>'memoryId',b->>'id')::uuid from turn_private.result_revisions x cross join lateral jsonb_array_elements(x.memory_basis) b
  where x.artifact_id=root_n and notification_private.uuid(coalesce(b->'memoryId',b->'id')));
 refs_n:=jsonb_set(refs_n,'{memoryIds}',doc_n);
 if exists(select 1 from turn_private.result_revisions x cross join lateral jsonb_array_elements(x.memory_basis) basis
  where x.artifact_id=root_n and (notification_private.uuid(coalesce(basis->'memoryId',basis->'id')) is not true or not exists(select 1 from public.memory_profiles mp where mp.id::text=coalesce(basis->>'memoryId',basis->>'id') and mp.owner_id=u))) then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
 select g||jsonb_build_object('artifactIds',jsonb_build_array(root_n),'revisions',coalesce(jsonb_agg(revision order by revision),'[]'),
  'publicationKeys',coalesce(jsonb_agg(idempotency_key order by idempotency_key),'[]')) into g from turn_private.result_revisions where artifact_id=root_n;
 select jsonb_set(g,'{eventIds}',coalesce(jsonb_agg(id::text order by id),'[]')) into g from turn_private.result_events where artifact_id=root_n;
 if jsonb_array_length(g->'revisions')<>a.current_revision or g->'revisions' is distinct from(select jsonb_agg(x) from generate_series(1,a.current_revision) x)
  or (select count(distinct idempotency_key) from turn_private.result_revisions where artifact_id=root_n)<>a.current_revision
  or exists(select 1 from turn_private.result_revisions where artifact_id=root_n and owner_id<>u)
  or exists(select 1 from turn_private.result_events where artifact_id=root_n and (owner_id<>u or id<=0 or revision not between 1 and a.current_revision))
  or jsonb_array_length(g->'eventIds')<a.current_revision then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if exists(select 1 from turn_private.result_revisions historical_n where historical_n.artifact_id=root_n and (historical_n.input_sequence<>m.sequence
  or not exists(select 1 from turn_private.service_task_turns st where st.turn_id=historical_n.task_turn_id and st.task_id=a.task_id and st.owner_id=u)
  or turn_private.valid_result_content_v2(historical_n.content) is not true or turn_private.valid_result_evidence_v2(historical_n.evidence_basis) is not true
  or not exists(select 1 from turn_private.result_events e where e.artifact_id=root_n and e.owner_id=u and e.revision=historical_n.revision and e.event_type=case historical_n.revision when 1 then 'ready' else 'revised' end))) then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if exists(select 1 from turn_private.result_revisions where artifact_id=root_n and (content->>'schemaVersion' not in('comparison/1','decision/1','journey-draft/1','practical/1','change-proposal-reference/1','travel-directions/1') or content->>'schemaVersion' is null)) then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if exists(select 1 from turn_private.result_revisions directions_revision where directions_revision.artifact_id=root_n and directions_revision.content->>'schemaVersion'='travel-directions/1' and not exists(select 1 from turn_private.directions_result_sources_v1 ds join turn_private.assistant_directions_intakes_v1 di on di.message_id=ds.message_id and di.owner_id=ds.owner_id where ds.artifact_id=root_n and ds.owner_id=u and ds.message_id=m.id and ds.task_turn_id=directions_revision.task_turn_id and di.task_id=a.task_id and di.goal_id=a.goal_id)) then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if a.proposal_id is not null or exists(select 1 from turn_private.result_revisions where artifact_id=root_n and content->>'schemaVersion'='change-proposal-reference/1') then conflicts_n:=conflicts_n||array['PROPOSAL_REFERENCE'];end if;
 if a.source_result_id is not null or exists(select 1 from turn_private.result_revisions where artifact_id=root_n and content->>'schemaVersion'='decision/1') then conflicts_n:=conflicts_n||array['DECISION_REFERENCE'];end if;
 select coalesce(array_agg(turn_id order by turn_id),array[]::uuid[]) into jobs_n from turn_private.planning_comparisons where artifact_id=root_n;
 if cardinality(jobs_n)>1 then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
 for id_n in select id from turn_private.planning_v2_execution_runs where turn_id=any(jobs_n) or task_id=a.task_id loop
  if cardinality(jobs_n)=1 and result_data_private.completed_copy_v1(u,root_n,id_n) then g:=jsonb_set(g,'{executionIds}',(g->'executionIds')||to_jsonb(id_n));
  else conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
 end loop;
 for id_n in select request_id from turn_private.planning_v2_model_local_journal where turn_id=any(jobs_n) loop
  if result_data_private.journal_copy_v1(u,root_n,id_n) then g:=jsonb_set(g,'{journalIds}',(g->'journalIds')||to_jsonb(id_n));else conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
 end loop;
 if jsonb_array_length(g->'executionIds')>1 or jsonb_array_length(g->'journalIds')>1 then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
 impact_n:=result_data_private.impact_sets_v1(g);
 if cardinality(impact_n)>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];end if;
 -- Every fixed relation is searched for scalar, typed JSON and original BYTEA
 -- dependencies; foreign rows enter only internal hashes and blocker names.
 for spec in select * from result_data_private.relations_v1() order by relation_name collate "C" loop
  n:=0;
  for v in execute format('select to_jsonb(actual) from %s actual where result_data_private.erase_member_v1(%L,to_jsonb(actual),$1) is not null or result_data_private.source_member_v1(%L,to_jsonb(actual),$2,$3) is not null or result_data_private.related_v1(%L,to_jsonb(actual),$1) or result_data_private.reverse_binding_v1(%L,to_jsonb(actual),$3,$6) or (%L like ''knowledge_review_private.source_impact_%%'' and (to_jsonb(actual)->>''set_id''=any($4::text[]) or %L=''knowledge_review_private.source_impact_sets'' and to_jsonb(actual)->>''id''=any($4::text[]) or %L=''knowledge_review_private.source_impact_review_requests'' and (to_jsonb(actual)->>''delivery_id'' in(select id::text from knowledge_review_private.source_impact_outbox where set_id=any($4)) or to_jsonb(actual)->>''projection_id'' in(select id::text from knowledge_review_private.source_impact_projections where set_id=any($4))))) or (%L in(''export_private.core_jobs_v1'',''export_private.core_artifacts_v1'') and to_jsonb(actual)->>''owner_id''=$5::text) order by to_jsonb(actual)::text collate "C" limit 10001',
   spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name)
   using g,refs_n,jobs_n,impact_n,u,a.task_id loop
   n:=n+1;total_n:=total_n+1;raw_bytes_n:=raw_bytes_n+octet_length(v::text);
   if n>10000 or total_n>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];exit;end if;
   key_n:=result_data_private.row_key_v1(v,spec.pk);
   if cardinality(spec.pk)=0 then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
   count_key:=result_data_private.erase_member_v1(spec.relation_name,v,g);effect_n:='erase';
   if count_key is null then count_key:=result_data_private.source_member_v1(spec.relation_name,v,refs_n,jobs_n);effect_n:='retain';end if;
   if count_key is not null then
    qualified_n:=v->>'owner_id'=u::text;
    if v->>'owner_id' is null then
     if spec.relation_name='public.model_budget_attempts' then qualified_n:=exists(select 1 from public.model_budget_scopes where id=(v->>'scope_id')::uuid and owner_id=u);
     elsif spec.relation_name='public.model_budget_provider_limits' then qualified_n:=exists(select 1 from public.model_budget_scopes where id=(v->>'scope_id')::uuid and owner_id=u);
     elsif spec.relation_name='turn_private.planning_v2_registered_tariffs' then qualified_n:=exists(select 1 from turn_private.planning_v2_execution_runs admitted join turn_private.planning_v2_execution_profiles profile on profile.id=admitted.profile_id where admitted.owner_id=u and g->'executionIds' ? admitted.id::text and profile.tariff_id::text=v->>'id');
     elsif spec.relation_name='turn_private.planning_v2_collector_principals' then qualified_n:=exists(select 1 from turn_private.planning_v2_execution_runs admitted where admitted.owner_id=u and g->'executionIds' ? admitted.id::text and admitted.collector_principal_id::text=v->>'id');
     elsif spec.relation_name='turn_private.text_dispatches' then qualified_n:=exists(select 1 from turn_private.text_content where turn_id=(v->>'turn_id')::uuid and owner_id=u);
     else qualified_n:=exists(select 1 from turn_private.planning_v2_execution_runs where id=(v->>'execution_id')::uuid and owner_id=u and g->'executionIds' ? id::text);end if;
    end if;
    if qualified_n is not true then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
    rows_n:=rows_n||jsonb_build_array(jsonb_build_object('table',spec.relation_name,'pk',key_n,'digest',result_data_private.digest_v1(v::text),'effect',effect_n,'countKey',count_key));
    if effect_n='erase' then erase_n:=jsonb_set(erase_n,array[count_key],to_jsonb((erase_n->>count_key)::integer+1));
    else retain_n:=jsonb_set(retain_n,array[count_key],to_jsonb((retain_n->>count_key)::integer+1));end if;
    if v->>'policy_id' is not null and v->>'consent_id' is not null then authorities_n:=authorities_n||jsonb_build_array(jsonb_build_object('policyId',v->'policy_id','consentId',v->'consent_id'));end if;
    if v->>'planning_policy_id' is not null and v->>'planning_consent_id' is not null then authorities_n:=authorities_n||jsonb_build_array(jsonb_build_object('policyId',v->'planning_policy_id','consentId',v->'planning_consent_id'));end if;
    if spec.relation_name='public.turns' and v->>'status' not in('completed','unavailable','failed','cancelled')
     or spec.relation_name='turn_private.work' and v->>'state' not in('completed','failed','cancelled')
     or spec.relation_name='turn_private.grounded_ai_assist_jobs' and v->>'status' in('queued','running')
     or spec.relation_name='turn_private.service_task_capacity' and v->>'state'='reserved'
     or spec.relation_name='public.model_budget_attempts' and v->>'status' not in('settled','released')
     or spec.relation_name='turn_private.planning_comparisons' and v->>'state'<>'completed'
     or spec.relation_name='turn_private.planning_v2_place_checkpoints' and v->>'state'<>'completed'
     or spec.relation_name='turn_private.planning_v2_model_attempt_bindings' and v->>'unknown_at' is not null
     or spec.relation_name='turn_private.planning_action_receipts' and v->>'state'<>'completed' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
    if effect_n='retain' and spec.relation_name<>'turn_private.planning_comparisons' and result_data_private.related_v1(spec.relation_name,v,g) then
     conflicts_n:=conflicts_n||case when spec.relation_name='turn_private.assistant_message_source_receipts' then 'CONVERSATION_SOURCE_REFERENCE' else 'SOURCE_UNSUPPORTED' end;
    end if;
   else
    reverse_n:=reverse_n||jsonb_build_array(jsonb_build_object('table',spec.relation_name,'pk',key_n,'digest',result_data_private.digest_v1(v::text)));
    conflicts_n:=conflicts_n||case
     when spec.relation_name='turn_private.result_artifacts' or spec.relation_name='turn_private.result_revisions' then case when v->'content'->>'schemaVersion'='decision/1' or v->>'source_result_id'=root_n::text then 'DECISION_REFERENCE' else 'CROSS_RESULT_REFERENCE' end
     when spec.relation_name='turn_private.assistant_message_source_receipts' then 'CONVERSATION_SOURCE_REFERENCE'
     when result_data_private.reverse_binding_v1(spec.relation_name,v,jobs_n,a.task_id) then 'SHARED_OR_FOREIGN_SCOPE'
     when spec.relation_name like 'readiness_private.%' then 'READINESS_REFERENCE' when spec.relation_name like 'guide_private.%' then 'GUIDE_REFERENCE'
     when spec.relation_name like 'scoped_edit_private.%' then 'SCOPED_EDIT_REFERENCE' when spec.relation_name like 'notification_private.%' or spec.relation_name like 'notification_exit_private.%' then 'NOTIFICATION_REFERENCE'
     when spec.relation_name like 'service_brief_private.%' then 'BRIEF_REFERENCE' when spec.relation_name like 'knowledge_review_private.source_impact_%' then 'KNOWLEDGE_MIXED_COPY'
     when spec.relation_name='public.trip_proposals' then 'PROPOSAL_REFERENCE'
     when spec.relation_name in('export_private.core_jobs_v1','export_private.core_artifacts_v1') then null
     when spec.relation_name like 'privacy_private.%' or spec.relation_name like 'conversation_data_private.%' then 'OTHER_DELETE_PENDING'
     else 'SOURCE_UNSUPPORTED' end;
   end if;
  end loop;
  if 'SCOPE_TOO_LARGE'=any(conflicts_n) then exit;end if;
 end loop;
 -- References and source identities are owner-qualified exactly, including every
 -- historical turn; absence/foreign mismatch is never reported as an eligible graph.
 if (retain_n->>'conversations')::integer<>1 or (retain_n->>'goals')::integer<>1 or (retain_n->>'messages')::integer<>1 or (retain_n->>'tasks')::integer<>1
  or (retain_n->>'turns')::integer<>cardinality(turns_n)
  or (retain_n->>'threads')::integer<>jsonb_array_length(refs_n->'threadIds')
  or (retain_n->>'trips')::integer<>jsonb_array_length(refs_n->'tripIds')
  or (retain_n->>'sourceArtifacts')::integer<>jsonb_array_length(refs_n->'sourceArtifactIds')
  or (retain_n->>'proposals')::integer<>jsonb_array_length(refs_n->'proposalIds') then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
 if exists(select 1 from export_private.core_artifacts_v1 where owner_id=u) or exists(select 1 from export_private.core_jobs_v1 where owner_id=u and (state in('queued','running') or lease_expires_at>clock_timestamp())) then conflicts_n:=conflicts_n||array['CORE_EXPORT_COPY'];end if;
 if exists(select 1 from privacy_private.trip_deletions where owner_id=u and state='queued' and refs_n->'tripIds' ? trip_id::text)
  or exists(select 1 from privacy_private.linked_delete_fences_v1 where entity_id=root_n or refs_n->'turnIds' ? entity_id::text)
  or exists(select 1 from privacy_private.memory_delete_jobs_v1 j join privacy_private.memory_delete_plans_v1 p on p.id=j.plan_id where j.owner_id=u and j.state='queued' and (p.selection->'artifactIds' ? root_n::text or privacy_private.memory_delete_ids_v1(p.selection)&&privacy_private.linked_delete_array_v1(refs_n->'memoryIds')))
  or exists(select 1 from conversation_data_private.operations_v1 o where owner_id=u and state='previewed' and not preview_erased and expires_at>floor(extract(epoch from clock_timestamp())*1000)::bigint and (o.graph->'artifactIds' ? root_n::text or o.graph->'taskIds' ? a.task_id::text or o.graph->'turnIds' ?| array(select jsonb_array_elements_text(refs_n->'turnIds'))))
  or exists(select 1 from conversation_data_private.operations_v1 o where state='erased' and (o.decision->'graph'->'artifactIds' ? root_n::text or o.decision->'graph'->'taskIds' ? a.task_id::text)) then conflicts_n:=conflicts_n||array['OTHER_DELETE_PENDING'];end if;
 for r in select * from result_data_private.deletion_witnesses_v1(u,refs_n,g) order by relation_name collate "C",document_n::text collate "C" limit 4101 loop
  total_n:=total_n+1;raw_bytes_n:=raw_bytes_n+octet_length(r.document_n::text);
  select pk into spec from result_data_private.relations_v1() where relation_name=r.relation_name;
  key_n:=case when r.relation_name='conversation_data_private.operations_v1' then jsonb_build_object('request_id',r.document_n->'request_id') else result_data_private.row_key_v1(r.document_n,spec.pk) end;
  reverse_n:=reverse_n||jsonb_build_array(jsonb_build_object('table',r.relation_name,'pk',key_n,'digest',result_data_private.digest_v1(r.document_n::text)));
  conflicts_n:=conflicts_n||array['OTHER_DELETE_PENDING'];
 end loop;
 authorities_n:=conversation_data_private.authorities_union_v1(authorities_n);
 if jsonb_array_length(authorities_n)>100 then raise exception 'RESULT_CAPACITY';end if;
 witness_n:=conversation_data_private.authorities_current_v1(u,authorities_n);
 assistant_delivery_n:=turn_private.assistant_delivery_source_v1(u,g);
 directions_n:=turn_private.directions_source_witness_v1(u,'result',g);
 fingerprint_n:=jsonb_build_object('directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'graph',g,'rows',rows_n,'reverse',reverse_n,'retainedReferences',refs_n,'authorities',authorities_n,'witness',witness_n,'conflicts',result_data_private.conflicts_v1(conflicts_n));
 if (directions_n->>'rowCount')::integer+jsonb_array_length(assistant_delivery_n->'rows')+total_n+coalesce(jsonb_array_length(witness_n),0)>4100 or raw_bytes_n+(directions_n->>'bytes')::bigint>1000000 or (select sum(jsonb_array_length(value)) from jsonb_each(g))>4100 or octet_length(fingerprint_n::text)>1000000 or jsonb_array_length(g->'eventIds')>3000 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];end if;
 if 'SCOPE_TOO_LARGE'=any(conflicts_n) then
  g:=jsonb_set(result_data_private.empty_graph_v1(),'{artifactIds}',jsonb_build_array(root_n));refs_n:=result_data_private.empty_refs_v1();
  erase_n:=result_data_private.zero_counts_v1('erase');retain_n:=result_data_private.zero_counts_v1('retain');rows_n:='[]';
 end if;
 return jsonb_build_object('graph',g,'eraseCounts',erase_n,'retainCounts',retain_n,'retainedReferences',refs_n,'conflicts',result_data_private.conflicts_v1(conflicts_n),
  'sourceAuthorities',authorities_n,'rows',rows_n,'reverse',reverse_n,'directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'sourceDigest',result_data_private.digest_v1(fingerprint_n::text));
end$function$;

CREATE OR REPLACE FUNCTION result_data_private.lock_source_v1(u uuid, source_n jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;v jsonb;pk_n text[];refs_n jsonb:=source_n->'retainedReferences';
begin
 -- Existing publication idempotency locks precede source parent locks. No
 -- owner-wide producer lock is added; only the eraser has exclusive entities.
 for r in select jsonb_array_elements_text(source_n->'graph'->'publicationKeys') id order by 1 loop
  if not pg_try_advisory_xact_lock(hashtextextended('result-idempotency:'||u||':'||r.id,0)) then raise lock_not_available using message='RESULT_CONFLICT';end if;
 end loop;
 perform 1 from turn_private.service_tasks where owner_id=u and refs_n->'taskIds' ? id::text order by id for update nowait;
 perform 1 from public.trips where owner_id=u and refs_n->'tripIds' ? id::text order by id for update nowait;
 perform 1 from turn_private.assistant_conversations where owner_id=u and refs_n->'conversationIds' ? id::text order by id for update nowait;
 perform 1 from public.chat_threads where owner_id=u and refs_n->'threadIds' ? id::text order by id for update nowait;
 perform 1 from public.turns where owner_id=u and refs_n->'turnIds' ? id::text order by id for update nowait;
 perform 1 from turn_private.assistant_goals where owner_id=u and refs_n->'goalIds' ? id::text order by id for update nowait;
 perform 1 from turn_private.assistant_messages where owner_id=u and refs_n->'messageIds' ? id::text order by id for update nowait;
 for r in select groups.key kind,ids.value::uuid id from jsonb_each(source_n->'graph') groups cross join lateral jsonb_array_elements_text(groups.value) ids(value)
  where groups.key in('artifactIds','executionIds','journalIds','publicationKeys') order by groups.key collate "C",ids.value::uuid loop
  if not pg_try_advisory_xact_lock(hashtextextended('result-data-entity:'||r.kind||':'||r.id::text,0)) then raise lock_not_available using message='RESULT_CONFLICT';end if;
  if result_data_private.fenced_v1(r.kind,r.id) then raise exception 'RESULT_CONFLICT';end if;
 end loop;
 perform conversation_data_private.authorities_current_v1(u,source_n->'sourceAuthorities');
 for v in select value from jsonb_array_elements((source_n->'rows')||(source_n->'reverse')) order by value->>'table' collate "C",(value->'pk')::text collate "C" loop
  select pk into pk_n from result_data_private.relations_v1() where relation_name=v->>'table';
  if v->>'table'='conversation_data_private.operations_v1' then pk_n:=array['request_id'];end if;
  if pk_n is null or cardinality(pk_n)=0 then raise exception 'RESULT_SOURCE_UNAVAILABLE';end if;
  execute format('select 1 from %s actual where result_data_private.row_key_v1(to_jsonb(actual),$1)=$2 for update nowait',v->>'table') using pk_n,v->'pk';
 end loop;
 perform turn_private.lock_directions_witness_v1(u,'result',source_n->'graph',source_n->'directionsSource');
 perform turn_private.lock_assistant_delivery_v1(u,source_n->'graph',source_n->'assistantDelivery');
end$function$;

CREATE OR REPLACE FUNCTION result_data_private.erase_source_v1(u uuid, source_n jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare relation_n text;v jsonb;pk_n text[];count_key text;expected_n integer;actual_n integer;counts_n jsonb:=result_data_private.zero_counts_v1('erase');
begin
 perform turn_private.erase_directions_witness_v1(u,source_n->'directionsSource');
 perform turn_private.retire_assistant_delivery_v1(u,source_n->'graph',source_n->'assistantDelivery');
 -- Children are explicit and counted. This order leaves no FK cascade effect.
 foreach relation_n in array array['turn_private.result_events','turn_private.result_revisions','turn_private.planning_v2_completed_receipts','turn_private.planning_v2_collector_outputs','turn_private.planning_v2_model_local_journal','turn_private.planning_v2_result_claims','turn_private.planning_v2_external_call_windows','turn_private.planning_v2_collector_origins','turn_private.planning_v2_completion_proofs','turn_private.planning_v2_execution_runs','turn_private.result_artifacts'] loop
  select pk into pk_n from result_data_private.relations_v1() where relation_name=relation_n;
  for v in select value from jsonb_array_elements(source_n->'rows') where value->>'table'=relation_n and value->>'effect'='erase' order by (value->'pk')::text collate "C" loop
   execute format('delete from %s actual where result_data_private.row_key_v1(to_jsonb(actual),$1)=$2 and result_data_private.digest_v1(to_jsonb(actual)::text)=$3',relation_n)
    using pk_n,v->'pk',v->>'digest';get diagnostics actual_n=row_count;
   if actual_n<>1 then raise exception 'RESULT_SOURCE_CHANGED';end if;
   count_key:=v->>'countKey';counts_n:=jsonb_set(counts_n,array[count_key],to_jsonb((counts_n->>count_key)::integer+actual_n));
  end loop;
 end loop;
 if counts_n is distinct from source_n->'eraseCounts' then raise exception 'RESULT_SOURCE_CHANGED';end if;
 -- Source preservation verified after all actual triggers/effects, by full rows.
 for v in select value from jsonb_array_elements(source_n->'rows') where value->>'effect'='retain' loop
  select pk into pk_n from result_data_private.relations_v1() where relation_name=v->>'table';
  execute format('select count(*) from %s actual where result_data_private.row_key_v1(to_jsonb(actual),$1)=$2 and result_data_private.digest_v1(to_jsonb(actual)::text)=$3',v->>'table') into actual_n using pk_n,v->'pk',v->>'digest';
  if actual_n<>1 then raise exception 'RESULT_SOURCE_CHANGED';end if;
 end loop;
 return jsonb_build_object('erasedCounts',counts_n,'retainedCounts',source_n->'retainCounts');
end$function$;

CREATE OR REPLACE FUNCTION conversation_data_private.source_v1(u uuid, root_kind_n text, root_id_n uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare closure_n jsonb;g jsonb;spec record;actual_n jsonb;key_n jsonb;ref record;qualified_n boolean;
 rows_n jsonb:='[]';reverse_n jsonb:='[]';authorities_n jsonb:='[]';witness_n jsonb;conflicts_n text[]:=array[]::text[];
 erase_n jsonb:=conversation_data_private.zero_counts_v1('erase');redact_n jsonb:=conversation_data_private.zero_counts_v1('redact');
 retain_n jsonb:=conversation_data_private.zero_counts_v1('retain');refs_n jsonb;trips_n uuid[]:=array[]::uuid[];memory_n uuid[]:=array[]::uuid[];
 executions uuid[]:=array[]::uuid[];turns uuid[];tasks uuid[];messages uuid[];goals uuid[];artifacts uuid[];threads uuid[];
 n integer;total_n integer:=0;reverse_total integer:=0;other_n jsonb;fingerprint_n jsonb;assistant_delivery_n jsonb;directions_n jsonb;directions_raw_bytes_n bigint:=0;relation_n text;extra_n uuid[];
begin
 -- Root ownership/policy precede source feedback, even on a capacity blocker.
 if root_kind_n='conversation' then
  select jsonb_build_array(jsonb_build_object('policyId',policy_id,'consentId',consent_id)) into authorities_n
   from turn_private.assistant_conversations where id=root_id_n and owner_id=u;
  if not found then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
  perform conversation_data_private.authorities_current_v1(u,authorities_n);
 elsif root_kind_n='thread' then
  perform 1 from public.chat_threads where id=root_id_n and owner_id=u;if not found then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
 else raise exception 'INVALID_INPUT';end if;
 closure_n:=conversation_data_private.closure_v1(u,root_kind_n,root_id_n);g:=closure_n->'graph';
 select coalesce(array_agg(value#>>'{}'),array[]::text[]) into conflicts_n from jsonb_array_elements(closure_n->'conflicts');
 if not conversation_data_private.schema_supported_v1() then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if conflicts_n @> array['SCOPE_TOO_LARGE'] then
  return jsonb_build_object('graph',g,'eraseCounts',erase_n,'redactCounts',redact_n,'retainCounts',retain_n,'sourceAuthorities',authorities_n,
   'retainedReferences','{"tripIds":[],"memoryIds":[]}'::jsonb,'conflicts',conversation_data_private.conflicts_v1(conflicts_n),'rows','[]'::jsonb,
   'sourceDigest',conversation_data_private.digest_v1(jsonb_build_array(g,conflicts_n,authorities_n)::text));
 end if;
 turns:=privacy_private.linked_delete_array_v1(g->'turnIds');tasks:=privacy_private.linked_delete_array_v1(g->'taskIds');
 messages:=privacy_private.linked_delete_array_v1(g->'messageIds');goals:=privacy_private.linked_delete_array_v1(g->'goalIds');
 artifacts:=privacy_private.linked_delete_array_v1(g->'artifactIds');threads:=privacy_private.linked_delete_array_v1(g->'threadIds');
 if root_kind_n='thread' and (cardinality(threads)<>1 or threads[1]<>root_id_n) then conflicts_n:=conflicts_n||array['CROSS_SCOPE_REFERENCE'];end if;
 select coalesce(array_agg(id order by id),array[]::uuid[]) into executions from turn_private.planning_v2_execution_runs
  where owner_id=u and (turn_id=any(turns) or task_id=any(tasks));
 for spec in select * from conversation_data_private.sources_v1() order by relation_name collate "C" loop
  n:=0;
  for actual_n in execute format('select to_jsonb(actual) from %s actual where conversation_data_private.related_v1(%L,to_jsonb(actual),$1,$2) order by conversation_data_private.row_key_v1(to_jsonb(actual),$3)::text collate "C" limit 10001',spec.relation_name,spec.relation_name)
   using g,executions,spec.pk loop
   n:=n+1;total_n:=total_n+1;
   if n>10000 or total_n>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];exit;end if;
   key_n:=conversation_data_private.row_key_v1(actual_n,spec.pk);
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(actual_n::text);
   rows_n:=rows_n||jsonb_build_array(jsonb_build_object('table',spec.relation_name,'pk',key_n,'digest',conversation_data_private.digest_v1(actual_n::text),'effect',spec.effect,'countKey',spec.count_key));
   if spec.has_owner then qualified_n:=actual_n->>'owner_id'=u::text;
   elsif spec.relation_name='public.model_budget_attempts' then
    qualified_n:=exists(select 1 from turn_private.service_tasks t join public.model_budget_scopes b on b.id=(actual_n->>'scope_id')::uuid where t.id=(actual_n->>'task_id')::uuid and t.owner_id=u and b.owner_id=u);
   elsif spec.relation_name='turn_private.text_dispatches' then
    qualified_n:=exists(select 1 from turn_private.text_content t where t.turn_id=(actual_n->>'turn_id')::uuid and t.owner_id=u);
   else qualified_n:=exists(select 1 from turn_private.planning_v2_execution_runs e where e.id=(actual_n->>'execution_id')::uuid and e.owner_id=u);end if;
   if not qualified_n then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];continue;end if;
   if spec.effect='erase' then erase_n:=jsonb_set(erase_n,array[spec.count_key],to_jsonb((erase_n->>spec.count_key)::integer+1));
   elsif spec.effect='redact' then redact_n:=jsonb_set(redact_n,array[spec.count_key],to_jsonb((redact_n->>spec.count_key)::integer+1));
   else retain_n:=jsonb_set(retain_n,array[spec.count_key],to_jsonb((retain_n->>spec.count_key)::integer+1));end if;
   if actual_n->>'policy_id' is not null and actual_n->>'consent_id' is not null then
    authorities_n:=authorities_n||jsonb_build_array(jsonb_build_object('policyId',actual_n->'policy_id','consentId',actual_n->'consent_id'));
   end if;
   if actual_n->>'planning_policy_id' is not null and actual_n->>'planning_consent_id' is not null then
    authorities_n:=authorities_n||jsonb_build_array(jsonb_build_object('policyId',actual_n->'planning_policy_id','consentId',actual_n->'planning_consent_id'));
   end if;
   -- Retained historical link receipts do not seed another deleted conversation.
   if spec.count_key<>'goalTripReceipts' then
    for ref in select * from conversation_data_private.json_references_v1(actual_n) loop
     if not(g->ref.kind ? ref.entity_id::text) then conflicts_n:=conflicts_n||array['CROSS_SCOPE_REFERENCE'];end if;
    end loop;
   end if;
   if spec.count_key='turns' then
    if actual_n->>'status'='proposal_ready' then conflicts_n:=conflicts_n||array['PROPOSAL_REFERENCE'];
    elsif actual_n->>'status' not in('completed','unavailable','failed','cancelled') then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
   elsif spec.count_key='work' and actual_n->>'state' not in('completed','failed','cancelled') then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='assistJobs' and actual_n->>'status' in('queued','running') then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='planning' and actual_n->>'state'<>'completed' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='capacity' and actual_n->>'state'='reserved' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='budgetAttempts' and actual_n->>'status' not in('settled','released') then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='checkpoints' and actual_n->>'state'<>'completed' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='attemptBindings' and actual_n->>'unknown_at' is not null then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='collectorOrigins' and (actual_n->>'unknown_at' is not null or actual_n->>'attempted_at' is not null and actual_n->>'response_buffered_at' is null) then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='resultClaims' and actual_n->>'state'<>'completed' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='localJournals' and (actual_n->>'unknown_at' is not null or actual_n->>'phase'<>'response_recorded'
     or not exists(select 1 from turn_private.planning_v2_completed_receipts c where c.turn_id=(actual_n->>'turn_id')::uuid and c.owner_id=u)) then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='callWindows' and (actual_n->>'calls')::integer>0
     and not exists(select 1 from turn_private.planning_v2_completion_proofs p where p.execution_id=(actual_n->>'execution_id')::uuid and p.owner_id=u) then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
   if actual_n->>'proposal_id' is not null or actual_n->'content'->>'schemaVersion' in('proposal_preview/1','change-proposal/1') then conflicts_n:=conflicts_n||array['PROPOSAL_REFERENCE'];end if;
   if actual_n->>'trip_id' is not null then trips_n:=conversation_data_private.union_ids_v1(trips_n||array[(actual_n->>'trip_id')::uuid]);end if;
   if actual_n->>'memory_id' is not null then memory_n:=conversation_data_private.union_ids_v1(memory_n||array[(actual_n->>'memory_id')::uuid]);end if;
   if jsonb_typeof(actual_n->'memory_basis')='array' then
    select array_agg(coalesce(entry->>'memoryId',entry->>'id')::uuid) into extra_n from jsonb_array_elements(actual_n->'memory_basis') entry where notification_private.uuid(coalesce(entry->'memoryId',entry->'id')) is true;
    memory_n:=conversation_data_private.union_ids_v1(memory_n||coalesce(extra_n,array[]::uuid[]));
   end if;
  end loop;
  if conflicts_n @> array['SCOPE_TOO_LARGE'] then exit;end if;
 end loop;
 redact_n:=jsonb_set(redact_n,'{taskDigests}',to_jsonb(cardinality(tasks)));
 authorities_n:=conversation_data_private.authorities_union_v1(authorities_n);
 if jsonb_array_length(authorities_n)>100 then raise exception 'CONVERSATION_CAPACITY';end if;
 witness_n:=conversation_data_private.authorities_current_v1(u,authorities_n);
 other_n:=conversation_data_private.impact_inventory_v1(g);
 if other_n->'rows'<>'[]'::jsonb then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if other_n->'overflow'='true'::jsonb then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];end if;
 reverse_n:=reverse_n||(other_n->'rows');reverse_total:=jsonb_array_length(reverse_n);
 -- Reverse JSON references in all actual application JSON tables. Known
 -- domain matches are blockers; any unregistered stored relation is unsupported.
 for relation_n in select distinct (n.nspname||'.'||c.relname) collate "C" from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid
  where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','conversation_data_private')
  and not(n.nspname='knowledge_review_private' and c.relname like 'source_impact_%')
  and a.attnum>0 and not a.attisdropped and (a.atttypid in('jsonb'::regtype,'json'::regtype) or conversation_data_private.reference_kind_v1(a.attname::text) is not null or n.nspname in('notification_private','service_brief_private','readiness_private','guide_private','scoped_edit_private'))
  and not exists(select 1 from conversation_data_private.sources_v1() s where s.relation_name=n.nspname||'.'||c.relname)
  -- Exact delivery relations covered by private witness and catalog pins.
  and n.nspname||'.'||c.relname not in ('turn_private.assistant_event_heads_v1','turn_private.assistant_events_v1','turn_private.assistant_directions_intakes_v1','turn_private.directions_result_sources_v1','turn_private.directions_operations_v1')
  order by 1 loop
  n:=0;
  for actual_n in execute format('select to_jsonb(actual) from %s actual where conversation_data_private.related_v1(%L,conversation_data_private.documents_v1(%L,to_jsonb(actual)),$1,$2) order by to_jsonb(actual)::text collate "C" limit 10001',relation_n,relation_n,relation_n) using g,executions loop
   n:=n+1;reverse_total:=reverse_total+1;
   if n>10000 or reverse_total+total_n>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];exit;end if;
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(actual_n::text);
   reverse_n:=reverse_n||jsonb_build_array(jsonb_build_object('table',relation_n,'digest',conversation_data_private.digest_v1(actual_n::text)));
   conflicts_n:=conflicts_n||case
    when relation_n like 'readiness_private.%' then 'READINESS_REFERENCE'
    when relation_n like 'guide_private.%' then 'GUIDE_REFERENCE'
    when relation_n like 'scoped_edit_private.%' then 'SCOPED_EDIT_REFERENCE'
    when relation_n like 'notification_private.%' then 'NOTIFICATION_REFERENCE'
    when relation_n like 'service_brief_private.%' then 'BRIEF_REFERENCE'
    else 'SOURCE_UNSUPPORTED' end;
  end loop;
 end loop;
 select coalesce(array_agg(id order by id),array[]::uuid[]) into trips_n from public.trips where id=any(trips_n) and owner_id=u;
 select coalesce(array_agg(id order by id),array[]::uuid[]) into memory_n from public.memory_profiles where id=any(memory_n) and owner_id=u;
 refs_n:=jsonb_build_object('tripIds',trips_n,'memoryIds',memory_n);
 for relation_n in select unnest(array['export_private.core_jobs_v1','export_private.core_artifacts_v1']) loop
  n:=0;
  for actual_n in execute format('select to_jsonb(actual) from %s actual where owner_id=$1 order by request_id limit 10001',relation_n) using u loop
   n:=n+1;reverse_total:=reverse_total+1;
   if n>10000 or reverse_total+total_n>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];exit;end if;
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(actual_n::text);
   reverse_n:=reverse_n||jsonb_build_array(jsonb_build_object('table',relation_n,'digest',conversation_data_private.digest_v1(actual_n::text)));
  end loop;
 end loop;
 if exists(select 1 from export_private.core_artifacts_v1 where owner_id=u)
  or exists(select 1 from export_private.core_jobs_v1 where owner_id=u and (state in('queued','running') or lease_expires_at>clock_timestamp())) then conflicts_n:=conflicts_n||array['CORE_EXPORT_COPY'];end if;
 if exists(select 1 from privacy_private.trip_deletions where owner_id=u and trip_id=any(trips_n) and state='queued')
  or exists(select 1 from privacy_private.linked_delete_fences_v1 f where exists(select 1 from jsonb_each(g) group_n where group_n.value ? f.entity_id::text))
  or exists(select 1 from privacy_private.memory_delete_jobs_v1 j join privacy_private.memory_delete_plans_v1 plan on plan.id=j.plan_id where j.owner_id=u and j.state='queued' and (privacy_private.memory_delete_ids_v1(plan.selection)&&memory_n or privacy_private.linked_delete_array_v1(plan.selection->'artifactIds')&&artifacts or privacy_private.linked_delete_array_v1(plan.selection->'generatedTurnIds')&&turns)) then conflicts_n:=conflicts_n||array['OTHER_DELETE_PENDING'];end if;
 if exists(select 1 from turn_private.result_revisions r where not r.artifact_id=any(artifacts)
  and exists(select 1 from conversation_data_private.json_references_v1(r.content) stored_ref where g->stored_ref.kind ? stored_ref.entity_id::text))
  or exists(select 1 from turn_private.assistant_message_source_receipts r where not r.message_id=any(messages)
   and (conversation_data_private.related_v1('reverse',r.input_sources,g,executions) or conversation_data_private.related_v1('reverse',r.captured_sources,g,executions))) then conflicts_n:=conflicts_n||array['CROSS_SCOPE_REFERENCE'];end if;
 assistant_delivery_n:=turn_private.assistant_delivery_source_v1(u,g);
 directions_n:=turn_private.directions_source_witness_v1(u,'conversation',g);
 fingerprint_n:=jsonb_build_object('directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'graph',g,'rows',rows_n,'reverse',reverse_n,'sourceAuthorities',authorities_n,'authorityWitness',witness_n,
  'trips',(select coalesce(jsonb_agg(to_jsonb(actual) order by id),'[]') from public.trips actual where id=any(trips_n) and owner_id=u),
  'memory',(select coalesce(jsonb_agg(to_jsonb(actual) order by id),'[]') from public.memory_profiles actual where id=any(memory_n) and owner_id=u),
  'conflicts',conversation_data_private.conflicts_v1(conflicts_n));
 if (directions_n->>'rowCount')::integer+jsonb_array_length(assistant_delivery_n->'rows')+total_n+reverse_total+jsonb_array_length(witness_n)+cardinality(trips_n)+cardinality(memory_n)>4100 or directions_raw_bytes_n+(directions_n->>'bytes')::bigint>1000000 or octet_length(fingerprint_n::text)>1000000 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];end if;
 if conflicts_n @> array['SCOPE_TOO_LARGE'] then
  g:=jsonb_set(conversation_data_private.empty_graph_v1(),array[case root_kind_n when 'conversation' then 'conversationIds' else 'threadIds' end],to_jsonb(array[root_id_n]));
  erase_n:=conversation_data_private.zero_counts_v1('erase');redact_n:=conversation_data_private.zero_counts_v1('redact');retain_n:=conversation_data_private.zero_counts_v1('retain');rows_n:='[]';refs_n:='{"tripIds":[],"memoryIds":[]}';
 end if;
 return jsonb_build_object('graph',g,'eraseCounts',erase_n,'redactCounts',redact_n,'retainCounts',retain_n,'sourceAuthorities',authorities_n,'retainedReferences',refs_n,
  'conflicts',conversation_data_private.conflicts_v1(conflicts_n),'rows',rows_n,'directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'sourceDigest',conversation_data_private.digest_v1(fingerprint_n::text));
end$function$;

CREATE OR REPLACE FUNCTION conversation_data_private.lock_source_v1(u uuid, source_n jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g jsonb:=source_n->'graph';identity_n uuid;ref record;row_n jsonb;table_n text;pk_n text[];
begin
 -- Original submit_service_task_turn identity pair precedes task/thread locks.
 for identity_n in select distinct value::uuid from (
  select jsonb_array_elements_text(g->'taskIds') value union select jsonb_array_elements_text(g->'turnIds') value) identities order by value::uuid loop
  if not pg_try_advisory_xact_lock(hashtextextended('service-task-identity:'||identity_n::text,0)) then raise lock_not_available using message='CONVERSATION_CONFLICT';end if;
 end loop;
 perform 1 from turn_private.service_tasks where id=any(privacy_private.linked_delete_array_v1(g->'taskIds')) and owner_id=u order by id for update nowait;
 perform 1 from public.trips where id=any(privacy_private.linked_delete_array_v1(source_n->'retainedReferences'->'tripIds')) and owner_id=u order by id for update nowait;
 for ref in select groups.key kind,ids.value::uuid entity_id from jsonb_each(g) groups cross join lateral jsonb_array_elements_text(groups.value) ids(value) order by groups.key collate "C",ids.value::uuid loop
  if not pg_try_advisory_xact_lock(hashtextextended('conversation-data-entity:'||ref.kind||':'||ref.entity_id::text,0)) then raise lock_not_available using message='CONVERSATION_CONFLICT';end if;
 end loop;
 perform 1 from turn_private.assistant_conversations where id=any(privacy_private.linked_delete_array_v1(g->'conversationIds')) and owner_id=u order by id for update nowait;
 perform 1 from public.chat_threads where id=any(privacy_private.linked_delete_array_v1(g->'threadIds')) and owner_id=u order by id for update nowait;
 perform 1 from public.turns where id=any(privacy_private.linked_delete_array_v1(g->'turnIds')) and owner_id=u order by id for update nowait;
 perform 1 from turn_private.assistant_goals where id=any(privacy_private.linked_delete_array_v1(g->'goalIds')) and owner_id=u order by id for update nowait;
 perform 1 from turn_private.assistant_messages where id=any(privacy_private.linked_delete_array_v1(g->'messageIds')) and owner_id=u order by id for update nowait;
 perform 1 from turn_private.result_artifacts where id=any(privacy_private.linked_delete_array_v1(g->'artifactIds')) and owner_id=u order by id for update nowait;
 perform 1 from public.memory_profiles where id=any(privacy_private.linked_delete_array_v1(source_n->'retainedReferences'->'memoryIds')) and owner_id=u order by id for share nowait;
 perform conversation_data_private.authorities_current_v1(u,source_n->'sourceAuthorities');
 for row_n in select value from jsonb_array_elements(source_n->'rows') order by value->>'table' collate "C",(value->'pk')::text collate "C" loop
  table_n:=row_n->>'table';select pk into pk_n from conversation_data_private.sources_v1() where relation_name=table_n;
  if pk_n is null then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
  execute format('select 1 from %s actual where conversation_data_private.row_key_v1(to_jsonb(actual),$1)=$2 for update nowait',table_n) using pk_n,row_n->'pk';
 end loop;
 perform turn_private.lock_directions_witness_v1(u,'conversation',source_n->'graph',source_n->'directionsSource');
 perform turn_private.lock_assistant_delivery_v1(u,source_n->'graph',source_n->'assistantDelivery');
end$function$;

CREATE OR REPLACE FUNCTION conversation_data_private.erase_source_v1(u uuid, source_n jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare relation_n text;spec record;key_n jsonb;selected_n jsonb;count_n integer;sum_n integer;progress_n integer;remaining_n integer;
 actual_erase jsonb:=conversation_data_private.zero_counts_v1('erase');actual_redact jsonb:=conversation_data_private.zero_counts_v1('redact');
 turns uuid[]:=privacy_private.linked_delete_array_v1(source_n->'graph'->'turnIds');tasks uuid[]:=privacy_private.linked_delete_array_v1(source_n->'graph'->'taskIds');
begin
 perform turn_private.erase_directions_witness_v1(u,source_n->'directionsSource');
 perform turn_private.retire_assistant_delivery_v1(u,source_n->'graph',source_n->'assistantDelivery');
 -- Exactly selected text keeps its original NOT NULL and retained task FK.
 update turn_private.text_content set input_text='[deleted by scoped conversation request]',output_kind=null,output_text=null,hidden_at=coalesce(hidden_at,clock_timestamp())
  where turn_id=any(turns) and owner_id=u;get diagnostics count_n=row_count;
 actual_redact:=jsonb_set(actual_redact,'{textBodies}',to_jsonb(count_n));
 update turn_private.service_tasks set goal_digest=conversation_data_private.digest_v1('[deleted by scoped conversation request]') where id=any(tasks) and owner_id=u;
 get diagnostics count_n=row_count;actual_redact:=jsonb_set(actual_redact,'{taskDigests}',to_jsonb(count_n));
 foreach relation_n in array conversation_data_private.erase_order_v1() loop
  select * into spec from conversation_data_private.sources_v1() where relation_name=relation_n;
  select coalesce(jsonb_agg(value->'pk' order by (value->'pk')::text collate "C"),'[]'::jsonb) into selected_n
   from jsonb_array_elements(source_n->'rows') where value->>'table'=relation_n;
  sum_n:=0;
  if relation_n in('turn_private.assistant_messages','turn_private.result_artifacts') then
   loop
    execute format('delete from %s actual where conversation_data_private.row_key_v1(to_jsonb(actual),$1) in(select value from jsonb_array_elements($2)) and actual.owner_id=$3 and not exists(select 1 from %s child where child.%I=actual.id)',
     relation_n,relation_n,case relation_n when 'turn_private.assistant_messages' then 'parent_message_id' else 'source_result_id' end)
     using spec.pk,selected_n,u;get diagnostics progress_n=row_count;sum_n:=sum_n+progress_n;exit when progress_n=0;
   end loop;
   execute format('select count(*) from %s actual where conversation_data_private.row_key_v1(to_jsonb(actual),$1) in(select value from jsonb_array_elements($2))',relation_n)
    into remaining_n using spec.pk,selected_n;
   if remaining_n<>0 then raise exception 'CONVERSATION_SOURCE_CHANGED';end if;
  else
   for key_n in select value from jsonb_array_elements(selected_n) order by value::text collate "C" loop
    execute format('delete from %s actual where conversation_data_private.row_key_v1(to_jsonb(actual),$1)=$2',relation_n) using spec.pk,key_n;
    get diagnostics count_n=row_count;sum_n:=sum_n+count_n;
   end loop;
  end if;
  actual_erase:=jsonb_set(actual_erase,array[spec.count_key],to_jsonb(sum_n));
 end loop;
 if actual_erase is distinct from source_n->'eraseCounts' or actual_redact is distinct from source_n->'redactCounts' then raise exception 'CONVERSATION_SOURCE_CHANGED';end if;
 return jsonb_build_object('erasedCounts',actual_erase,'redactedCounts',actual_redact,'retainedCounts',source_n->'retainCounts');
end$function$;

CREATE OR REPLACE FUNCTION turn_data_private.source_v1(u uuid, t uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b jsonb;g jsonb;refs jsonb;bad text[];spec record;v jsonb;pk_n jsonb;ref record;rel text;ex uuid[];parents uuid[];rows_n jsonb[]:=array[]::jsonb[];reverse_n jsonb[]:=array[]::jsonb[];
 impact_n jsonb;auths jsonb:='[]';witness jsonb;erase_n jsonb:=turn_data_private.zero_counts_v1('erase');redact_n jsonb:=turn_data_private.zero_counts_v1('redact');retain_n jsonb:=turn_data_private.zero_counts_v1('retain');total_n integer:=0;n integer;effect_n text;qualified boolean;fp jsonb;assistant_delivery_n jsonb;directions_n jsonb;directions_raw_bytes_n bigint:=0;trips_n uuid[]:=array[]::uuid[];mems uuid[]:=array[]::uuid[];
begin
 if turn_data_private.schema_supported_v1() is not true then
  select jsonb_build_array(jsonb_build_object('policyId',c.policy_id,'consentId',c.consent_id)) into auths from turn_private.text_content c join public.turns pt on pt.id=c.turn_id and pt.owner_id=c.owner_id where c.turn_id=t and c.owner_id=u;
  if not found then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;perform turn_data_private.authorities_current_v1(u,auths);
  return jsonb_build_object('graph',jsonb_build_object('turnIds',array[t],'messageIds',array[]::uuid[],'artifactIds',array[]::uuid[]),'retainedReferences',turn_data_private.empty_references_v1(),'rows','[]'::jsonb,'reverse','[]'::jsonb,'eraseCounts',erase_n,'redactCounts',redact_n,'retainCounts',retain_n,'sourceAuthorities',auths,'conflicts','["SOURCE_UNSUPPORTED"]'::jsonb,'sourceDigest',turn_data_private.digest_v1(jsonb_build_array(t,'SOURCE_UNSUPPORTED')::text));
 end if;
 b:=turn_data_private.graph_source_v1(u,t);g:=b->'graph';refs:=b->'retainedReferences';
 select coalesce(array_agg(value#>>'{}'),array[]::text[]) into bad from jsonb_array_elements(b->'conflicts');
 select coalesce(array_agg(id order by id),array[]::uuid[]) into ex from turn_private.planning_v2_execution_runs where turn_id=t and owner_id=u;
 for spec in select * from turn_data_private.sources_v1() order by relation_name collate "C" loop
  n:=0;
  for v in execute format('select to_jsonb(a) from %s a where turn_data_private.related_v1(%L,to_jsonb(a),$1,$2,$3,$4) order by %s limit 10001',spec.relation_name,spec.relation_name,(select string_agg(format('a.%I',k),',') from unnest(spec.pk) k)) using g,refs,ex,u loop
   n:=n+1;total_n:=total_n+1;if total_n>4100 then bad:=array_append(bad,'SCOPE_TOO_LARGE');exit;end if;
   pk_n:=turn_data_private.row_key_v1(v,spec.pk);effect_n:=spec.effect;
   qualified:=not spec.has_owner or v->>'owner_id'=u::text;
   if not qualified then bad:=array_append(bad,'SHARED_OR_FOREIGN_SCOPE');end if;
   if spec.count_key='memoryConsumers' and v->>'proposal_id' is not null then effect_n:='retain';bad:=array_append(bad,'PROPOSAL_REFERENCE');end if;
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(v::text);
   rows_n:=array_append(rows_n,jsonb_build_object('table',spec.relation_name,'pk',pk_n,'digest',turn_data_private.digest_v1(v::text),'effect',effect_n,'countKey',spec.count_key));
   if effect_n='erase' then erase_n:=jsonb_set(erase_n,array[spec.count_key],to_jsonb((erase_n->>spec.count_key)::integer+1));
   elsif effect_n='redact' then redact_n:=jsonb_set(redact_n,array[spec.count_key],to_jsonb((redact_n->>spec.count_key)::integer+1));
   elsif retain_n ? spec.count_key then retain_n:=jsonb_set(retain_n,array[spec.count_key],to_jsonb((retain_n->>spec.count_key)::integer+1));end if;
   if spec.count_key='messageBodies' then retain_n:=jsonb_set(retain_n,'{messages}',to_jsonb((retain_n->>'messages')::integer+1));end if;
   if spec.count_key='tasks' and v->>'goal_turn_id'=t::text then redact_n:=jsonb_set(redact_n,'{taskDigests}',to_jsonb((redact_n->>'taskDigests')::integer+1));end if;
   if v->>'policy_id' is not null and v->>'consent_id' is not null then auths:=auths||jsonb_build_array(jsonb_build_object('policyId',v->'policy_id','consentId',v->'consent_id'));end if;
   if v->>'planning_policy_id' is not null and v->>'planning_consent_id' is not null then auths:=auths||jsonb_build_array(jsonb_build_object('policyId',v->'planning_policy_id','consentId',v->'planning_consent_id'));end if;
   -- Dispatch has a text authority even though it has no owner column.
   if v->>'text_policy_id' is not null then
    auths:=auths||coalesce((select jsonb_agg(jsonb_build_object('policyId',tc.policy_id,'consentId',tc.consent_id)) from turn_private.text_content tc where tc.turn_id=t and tc.owner_id=u and tc.policy_id=(v->>'text_policy_id')::uuid),'[]'::jsonb);
   end if;
   for ref in select * from turn_data_private.json_references_v1(v) loop
    if ref.kind in('turnIds','messageIds','artifactIds') and not(g->ref.kind ? ref.entity_id::text)
     and not(cardinality(ref.path_n)=1 and ref.path_n[1] in('parent_turn_id','parent_message_id','source_message_id','goal_turn_id','last_turn_id')) then bad:=array_append(bad,'CROSS_TURN_REFERENCE');end if;
   end loop;
   if spec.count_key='work' and v->>'state' not in('completed','failed','cancelled')
    or spec.count_key='assistJobs' and v->>'status' in('queued','running')
    or spec.count_key='planning' and v->>'state'<>'completed'
    or spec.count_key='capacity' and v->>'state'='reserved'
    or spec.count_key='budgetAttempts' and v->>'status' not in('settled','released')
    or spec.count_key='checkpoints' and v->>'state'<>'completed'
    or spec.count_key='attemptBindings' and v->>'unknown_at' is not null
    or spec.count_key='collectorOrigins' and (v->>'unknown_at' is not null or v->>'attempted_at' is not null and v->>'response_buffered_at' is null)
    or spec.count_key='executionRuns' and (not exists(select 1 from turn_private.planning_v2_completion_proofs cp where cp.execution_id=(v->>'id')::uuid and cp.owner_id=u and cp.turn_id=t) or not exists(select 1 from turn_private.planning_v2_completed_receipts cr where cr.execution_id=(v->>'id')::uuid and cr.owner_id=u and cr.turn_id=t))
    or spec.count_key='resultClaims' and v->>'state'<>'completed'
    or spec.count_key='localJournals' and (v->>'unknown_at' is not null or v->>'phase'<>'response_recorded' or not exists(select 1 from turn_private.planning_v2_completed_receipts c where c.turn_id=t and c.owner_id=u))
    or spec.count_key='callWindows' and (v->>'calls')::integer>0 and not exists(select 1 from turn_private.planning_v2_completion_proofs p where p.execution_id=(v->>'execution_id')::uuid and p.owner_id=u) then bad:=array_append(bad,'ACTIVE_WORK');end if;
   if v->>'proposal_id' is not null or v->'content'->>'schemaVersion' in('proposal_preview/1','change-proposal/1') then bad:=array_append(bad,'PROPOSAL_REFERENCE');end if;
   if notification_private.uuid(v->'trip_id') then trips_n:=turn_data_private.union_ids_v1(trips_n||array[(v->>'trip_id')::uuid]);end if;
   if notification_private.uuid(v->'memory_id') then mems:=turn_data_private.union_ids_v1(mems||array[(v->>'memory_id')::uuid]);end if;
   if jsonb_typeof(v->'memory_basis')='array' then select turn_data_private.union_ids_v1(mems||coalesce(array_agg(coalesce(x->>'memoryId',x->>'id')::uuid),array[]::uuid[])) into mems from jsonb_array_elements(v->'memory_basis') x where notification_private.uuid(coalesce(x->'memoryId',x->'id'));end if;
  end loop;
  if total_n>4100 then exit;end if;
 end loop;
 -- Parent bytes and the current writer basis enter CAS, never the returned graph or body.
 for rel in select unnest(array['public.chat_threads','turn_private.assistant_conversations','turn_private.assistant_goals']) loop
  parents:=privacy_private.linked_delete_array_v1(refs->case rel when 'public.chat_threads' then 'threadIds' when 'turn_private.assistant_conversations' then 'conversationIds' else 'goalIds' end);
  for v in execute format('select to_jsonb(a) from %s a where id=any($1) and owner_id=$2 order by id',rel) using parents,u loop
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(v::text);
   total_n:=total_n+1;reverse_n:=array_append(reverse_n,jsonb_build_object('table',rel,'pk',jsonb_build_object('id',v->'id'),'digest',turn_data_private.digest_v1(v::text)));
  end loop;
 end loop;
 retain_n:=retain_n||jsonb_build_object('threads',jsonb_array_length(refs->'threadIds'),'conversations',jsonb_array_length(refs->'conversationIds'),'goals',jsonb_array_length(refs->'goalIds'));
 for v in select to_jsonb(w) from turn_private.assistant_messages w join turn_private.assistant_goals goal on goal.id=w.goal_id and goal.conversation_id=w.conversation_id and goal.owner_id=w.owner_id and goal.scope_version=w.scope_version where goal.id=any(privacy_private.linked_delete_array_v1(refs->'goalIds')) and w.owner_id=u and w.relationship in('goal_start','amendment') order by w.id loop
  directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(v::text);
  total_n:=total_n+1;reverse_n:=array_append(reverse_n,jsonb_build_object('table','turn_private.assistant_messages','pk',jsonb_build_object('id',v->'id'),'digest',turn_data_private.digest_v1(v::text)));
 end loop;
 -- Original connected-set helper preserves the entire six-table mixed-copy CAS.
 impact_n:=conversation_data_private.impact_inventory_v1(g);
 for v in select value from jsonb_array_elements(impact_n->'rows') loop reverse_n:=array_append(reverse_n,v);total_n:=total_n+1;end loop;
 if impact_n->'rows'<>'[]'::jsonb then bad:=array_append(bad,'SOURCE_UNSUPPORTED');end if;
 if impact_n->'overflow'='true'::jsonb then bad:=array_append(bad,'SCOPE_TOO_LARGE');end if;
 -- All actual reverse direct/nested relations are inspected, including terminal copies.
 for rel in select distinct n.nspname||'.'||c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid
  where c.relkind='r' and a.attnum>0 and not a.attisdropped and n.nspname not in('pg_catalog','information_schema','extensions','auth','storage','realtime','_realtime','vault','supabase_functions','supabase_migrations','turn_data_private')
   and not(n.nspname='knowledge_review_private' and c.relname in('source_impact_sets','source_impact_items','source_impact_pages','source_impact_outbox','source_impact_projections','source_impact_review_requests'))
   and n.nspname||'.'||c.relname not in ('turn_private.assistant_event_heads_v1','turn_private.assistant_events_v1','turn_private.assistant_directions_intakes_v1','turn_private.directions_result_sources_v1','turn_private.directions_operations_v1')
    and (a.atttypid in('json'::regtype,'jsonb'::regtype) or turn_data_private.reference_kind_v1(a.attname::text) is not null) order by 1 loop
  for v in execute format('select to_jsonb(a) from %s a where exists(select 1 from turn_data_private.json_references_v1(conversation_data_private.documents_v1(%L,to_jsonb(a))) r where $1->r.kind ? r.entity_id::text) order by to_jsonb(a)::text collate "C" limit 4101',rel,rel) using g loop
   if exists(select 1 from unnest(rows_n) r where r->>'table'=rel and r->'digest'=to_jsonb(turn_data_private.digest_v1(v::text))) then continue;end if;
   -- Retained task/identity source and own authority diagnostics do not become parent sweeps.
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(v::text);
   total_n:=total_n+1;reverse_n:=array_append(reverse_n,jsonb_build_object('table',rel,'digest',turn_data_private.digest_v1(v::text)));
   bad:=bad||case
    when rel like 'readiness_private.%' then 'READINESS_REFERENCE' when rel like 'guide_private.%' then 'GUIDE_REFERENCE'
    when rel like 'scoped_edit_private.%' then 'SCOPED_EDIT_REFERENCE' when rel like 'notification_private.%' then 'NOTIFICATION_REFERENCE'
    when rel like 'service_brief_private.%' then 'BRIEF_REFERENCE' when rel like 'knowledge_review_private.source_impact_%' then 'SOURCE_UNSUPPORTED'
    when rel like 'conversation_data_private.%' or rel like 'result_data_private.%' or rel like 'privacy_private.%' then 'OTHER_DELETE_PENDING'
    when exists(select 1 from turn_data_private.sources_v1() s where s.relation_name=rel) or rel in('turn_private.assistant_messages','turn_private.assistant_goal_trip_links','turn_private.assistant_goal_trip_receipts') then 'CROSS_TURN_REFERENCE'
    when rel like 'public.%proposal%' then 'PROPOSAL_REFERENCE' else 'SOURCE_UNSUPPORTED' end;
   if total_n>4100 then bad:=array_append(bad,'SCOPE_TOO_LARGE');exit;end if;
  end loop;
  if total_n>4100 then exit;end if;
 end loop;
 for rel in select unnest(array['export_private.core_jobs_v1','export_private.core_artifacts_v1']) loop
  for v in execute format('select to_jsonb(a) from %s a where owner_id=$1 order by request_id limit 4101',rel) using u loop
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(v::text);
   total_n:=total_n+1;reverse_n:=array_append(reverse_n,jsonb_build_object('table',rel,'digest',turn_data_private.digest_v1(v::text)));
   if rel='export_private.core_artifacts_v1' or v->>'state' in('queued','running') or (v->>'lease_expires_at')::timestamptz>clock_timestamp() then bad:=array_append(bad,'CORE_EXPORT_COPY');end if;
  end loop;
 end loop;
 if exists(select 1 from privacy_private.trip_deletions where owner_id=u and trip_id=any(trips_n) and state='queued')
  or exists(select 1 from privacy_private.linked_delete_fences_v1 f where exists(select 1 from jsonb_each(g) e where e.value ? f.entity_id::text)) then bad:=array_append(bad,'OTHER_DELETE_PENDING');end if;
 select coalesce(array_agg(id order by id),array[]::uuid[]) into trips_n from public.trips where id=any(trips_n) and owner_id=u;
 select coalesce(array_agg(id order by id),array[]::uuid[]) into mems from public.memory_profiles where id=any(mems) and owner_id=u;
 refs:=refs||jsonb_build_object('tripIds',trips_n,'memoryIds',mems);
 auths:=turn_data_private.authorities_union_v1(auths);witness:=turn_data_private.authorities_current_v1(u,auths);
 assistant_delivery_n:=turn_private.assistant_delivery_source_v1(u,g);
 directions_n:=turn_private.directions_source_witness_v1(u,'turn',g);
 fp:=jsonb_build_object('directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'graph',g,'rows',to_jsonb(rows_n),'reverse',to_jsonb(reverse_n),'retainedReferences',refs,'sourceAuthorities',auths,'authorityWitness',witness,'conflicts',turn_data_private.conflicts_v1(bad));
 if (directions_n->>'rowCount')::integer+jsonb_array_length(assistant_delivery_n->'rows')+total_n+jsonb_array_length(witness)+cardinality(trips_n)+cardinality(mems)>4100 or directions_raw_bytes_n+(directions_n->>'bytes')::bigint>1000000 or octet_length(fp::text)>1000000 then bad:=array_append(bad,'SCOPE_TOO_LARGE');end if;
 return jsonb_build_object('graph',g,'retainedReferences',refs,'rows',to_jsonb(rows_n),'reverse',to_jsonb(reverse_n),'eraseCounts',erase_n,'redactCounts',redact_n,'retainCounts',retain_n,'sourceAuthorities',auths,'conflicts',turn_data_private.conflicts_v1(bad),'directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'sourceDigest',turn_data_private.digest_v1(fp::text));
end$function$;

CREATE OR REPLACE FUNCTION turn_data_private.lock_source_v1(u uuid, src jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare id_n uuid;r record;v jsonb;s record;g jsonb:=src->'graph';refs jsonb:=src->'retainedReferences';
begin
 for id_n in select distinct value::uuid from(select jsonb_array_elements_text(refs->'taskIds') value union select jsonb_array_elements_text(g->'turnIds')) a order by 1 loop
  if not pg_try_advisory_xact_lock(hashtextextended('service-task-identity:'||id_n::text,0)) then raise lock_not_available using message='TURN_CONFLICT';end if;
 end loop;
 perform 1 from turn_private.service_tasks where id=any(privacy_private.linked_delete_array_v1(refs->'taskIds')) and owner_id=u order by id for update nowait;
 for v in select value from jsonb_array_elements(src->'rows') where value->>'effect'='erase' order by value->>'table' collate "C",(value->'pk')::text collate "C" loop
  if not pg_try_advisory_xact_lock(hashtextextended('turn-data-source-key:'||(v->>'table')||':'||turn_data_private.digest_v1((v->'pk')::text),0)) then raise lock_not_available using message='TURN_CONFLICT';end if;
 end loop;
 for r in select e.key kind,x.value::uuid id from jsonb_each(g) e cross join lateral jsonb_array_elements_text(e.value) x order by e.key collate "C",x.value::uuid loop
  if not pg_try_advisory_xact_lock(hashtextextended('turn-data-entity:'||r.kind||':'||r.id::text,0)) then raise lock_not_available using message='TURN_CONFLICT';end if;
 end loop;
 -- Original Conversation/Result entity guards share these identities too.
 for r in select e.key kind,x.value::uuid id from jsonb_each(g||refs) e cross join lateral jsonb_array_elements_text(e.value) x where e.key in('turnIds','messageIds','artifactIds','taskIds','threadIds','conversationIds','goalIds') order by e.key collate "C",x.value::uuid loop
  if not pg_try_advisory_xact_lock(hashtextextended('conversation-data-entity:'||r.kind||':'||r.id::text,0)) then raise lock_not_available using message='TURN_CONFLICT';end if;
 end loop;
 for v in select value from jsonb_array_elements((src->'rows')||(src->'reverse')) where value ? 'pk' order by value->>'table' collate "C",(value->'pk')::text collate "C" loop
  select * into s from turn_data_private.sources_v1() where relation_name=v->>'table';
  if not found then s.pk:=array['id'];end if;
  execute format('select 1 from %s a where turn_data_private.row_key_v1(to_jsonb(a),$1)=$2 for update nowait',v->>'table') using s.pk,v->'pk';
 end loop;
 perform turn_data_private.authorities_current_v1(u,src->'sourceAuthorities');
 perform turn_private.lock_directions_witness_v1(u,'turn',src->'graph',src->'directionsSource');
 perform turn_private.lock_assistant_delivery_v1(u,src->'graph',src->'assistantDelivery');
end$function$;

CREATE OR REPLACE FUNCTION turn_data_private.erase_source_v1(u uuid, src jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare spec record;v jsonb;n integer;ec jsonb:=turn_data_private.zero_counts_v1('erase');rc jsonb:=turn_data_private.zero_counts_v1('redact');t uuid:=(src->'graph'->'turnIds'->>0)::uuid;rel text;remaining integer;keys_n jsonb;
begin
 if turn_data_private.runtime_supported_v1() is not true or turn_data_private.write_hooks_valid_v1() is not true then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
 perform turn_private.erase_directions_witness_v1(u,src->'directionsSource');
 perform turn_private.retire_assistant_delivery_v1(u,src->'graph',src->'assistantDelivery');
 update turn_private.text_content set input_text='[deleted by scoped turn request]',output_kind=null,output_text=null,hidden_at=coalesce(hidden_at,clock_timestamp()) where turn_id=t and owner_id=u;get diagnostics n=row_count;rc:=jsonb_set(rc,'{textBodies}',to_jsonb(n));
 update turn_private.assistant_messages set input_text='[deleted by scoped turn request]' where id=any(privacy_private.linked_delete_array_v1(src->'graph'->'messageIds')) and owner_id=u;get diagnostics n=row_count;rc:=jsonb_set(rc,'{messageBodies}',to_jsonb(n));
 update turn_private.service_tasks set goal_digest=turn_data_private.digest_v1('[deleted by scoped turn request]') where goal_turn_id=t and id=any(privacy_private.linked_delete_array_v1(src->'retainedReferences'->'taskIds')) and owner_id=u;get diagnostics n=row_count;rc:=jsonb_set(rc,'{taskDigests}',to_jsonb(n));
 foreach rel in array conversation_data_private.erase_order_v1() loop
  select * into spec from turn_data_private.sources_v1() where relation_name=rel and effect='erase';if not found then continue;end if;
  n:=0;
  -- Child artifacts are erased before their source artifacts without parent cascades.
  select coalesce(jsonb_agg(value->'pk'),'[]'::jsonb) into keys_n from jsonb_array_elements(src->'rows') where value->>'table'=rel and value->>'effect'='erase';
  if rel='turn_private.result_artifacts' then
   loop
    execute 'delete from turn_private.result_artifacts a where turn_data_private.row_key_v1(to_jsonb(a),$1) in(select value from jsonb_array_elements($2)) and owner_id=$3 and not exists(select 1 from turn_private.result_artifacts child where child.source_result_id=a.id)' using spec.pk,keys_n,u;
    get diagnostics remaining=row_count;n:=n+remaining;exit when remaining=0;
   end loop;
  else
   for v in select value from jsonb_array_elements(keys_n) loop
    execute format('delete from %s a where turn_data_private.row_key_v1(to_jsonb(a),$1)=$2',rel) using spec.pk,v;
    get diagnostics remaining=row_count;n:=n+remaining;
   end loop;
  end if;
  ec:=jsonb_set(ec,array[spec.count_key],to_jsonb(n));
 end loop;
 if ec is distinct from src->'eraseCounts' or rc is distinct from src->'redactCounts' then raise exception 'TURN_SOURCE_CHANGED';end if;
 return jsonb_build_object('erasedCounts',ec,'redactedCounts',rc,'retainedCounts',src->'retainCounts');
end$function$;

-- Constituent: d3-handlers.after.sql
-- ARTIFACT ONLY: complete original4100/1MB selection budget; source→metadata→delivery lock order.
CREATE OR REPLACE FUNCTION privacy_private.linked_delete_graph_v1(p_owner uuid, p_trip uuid, p_seed jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare threads uuid[];turns uuid[];tasks uuid[];goals uuid[];messages uuid[];artifacts uuid[];exports uuid[];conflicts jsonb:='[]';selection jsonb;graph jsonb;counts jsonb;pass integer;derived jsonb;derived_n integer;assistant_delivery_n jsonb;directions_n jsonb;directions_raw_bytes_n bigint:=0;
begin
 select coalesce(array_agg(distinct g.id order by g.id),'{}') into goals from (select g.id from turn_private.assistant_goals g where exists(select 1 from turn_private.assistant_goal_trip_links l where l.goal_id=g.id and l.trip_id=p_trip) or g.id=any(privacy_private.linked_delete_array_v1(coalesce(p_seed->'goalIds','[]'))) order by g.id limit 1001) g;
 select coalesce(array_agg(h.id order by h.id),'{}') into threads from (select id from public.chat_threads h where h.trip_id=p_trip or exists(select 1 from public.turns t where t.thread_id=h.id and t.trip_id=p_trip) or exists(select 1 from turn_private.service_tasks st join turn_private.assistant_messages m on m.task_id=st.id where st.thread_id=h.id and m.goal_id=any(goals)) order by h.id limit 101) h;
 select coalesce(array_agg(t.id order by t.id),'{}') into turns from (select id from public.turns t where t.trip_id=p_trip or t.thread_id=any(threads) order by t.id limit 1001) t;
 select coalesce(array_agg(s.id order by s.id),'{}') into tasks from (select id from turn_private.service_tasks s where s.thread_id=any(threads) or exists(select 1 from turn_private.service_task_turns l where l.task_id=s.id and l.turn_id=any(turns)) order by s.id limit 1001) s;

 for pass in 1..2 loop
  select coalesce(array_agg(distinct g.id order by g.id),'{}') into goals from (select g.id from turn_private.assistant_goals g where g.id=any(goals) or exists(select 1 from turn_private.assistant_messages m where m.goal_id=g.id and (m.task_id=any(tasks) or m.turn_id=any(turns))) or exists(select 1 from turn_private.result_artifacts a where a.goal_id=g.id and a.trip_id=p_trip) order by g.id limit 1001) g;
  select coalesce(array_agg(m.id order by m.id),'{}') into messages from (select m.id from turn_private.assistant_messages m where m.goal_id=any(goals) or m.task_id=any(tasks) or m.turn_id=any(turns) order by m.id limit 1001) m;
  select coalesce(array_agg(s.id order by s.id),'{}') into tasks from (select s.id from turn_private.service_tasks s where s.id=any(tasks) or exists(select 1 from turn_private.assistant_messages m where m.id=any(messages) and m.task_id=s.id) order by s.id limit 1001) s;
 end loop;
 select coalesce(array_agg(a.id order by a.id),'{}') into artifacts from (select a.id from turn_private.result_artifacts a where a.trip_id=p_trip or a.task_id=any(tasks) or a.goal_id=any(goals) or a.input_message_id=any(messages) or a.source_turn_id=any(turns) order by a.id limit 1001) a;
 select coalesce(array_agg(e.request_id order by e.request_id),'{}') into exports from (select j.request_id from export_private.core_jobs_v1 j where j.owner_id=p_owner and (j.state in ('queued','running','ready_partial','ready_complete') or exists(select 1 from export_private.core_artifacts_v1 a where a.request_id=j.request_id) or j.request_id=any(privacy_private.linked_delete_array_v1(coalesce(p_seed->'exportRequestIds','[]')))) order by j.request_id limit 101) e;
 if cardinality(threads)>100 or cardinality(turns)>1000 or cardinality(tasks)>1000 or cardinality(goals)>1000 or cardinality(messages)>1000 or cardinality(artifacts)>1000 or cardinality(exports)>100 or cardinality(threads)+cardinality(turns)+cardinality(tasks)+cardinality(goals)+cardinality(messages)+cardinality(artifacts)+cardinality(exports)>4100 then
  return jsonb_build_object('selection',jsonb_build_object('threadIds','[]'::jsonb,'turnIds','[]'::jsonb,'taskIds','[]'::jsonb,'goalIds','[]'::jsonb,'messageIds','[]'::jsonb,'artifactIds','[]'::jsonb,'exportRequestIds','[]'::jsonb),'counts',jsonb_build_object('threads',0,'turns',0,'tasks',0,'goals',0,'messages',0,'artifacts',0,'exports',0),'conflicts','["SCOPE_TOO_LARGE"]'::jsonb,'graph','{}'::jsonb);
 end if;
 if exists(select 1 from public.chat_threads where id=any(threads) and (owner_id<>p_owner or trip_id is not null and trip_id<>p_trip)) or exists(select 1 from public.turns where id=any(turns) and (owner_id<>p_owner or trip_id is not null and trip_id<>p_trip or trip_id is null and not exists(select 1 from public.chat_threads h where h.id=thread_id and (h.trip_id=p_trip or exists(select 1 from turn_private.service_tasks st join turn_private.assistant_messages m on m.task_id=st.id where st.thread_id=h.id and m.goal_id=any(goals)))))) then conflicts:=conflicts||'"SHARED_OR_FOREIGN_CHAT"'::jsonb;end if;
 if exists(select 1 from turn_private.service_tasks where id=any(tasks) and owner_id<>p_owner) or exists(select 1 from turn_private.service_task_turns where task_id=any(tasks) and (owner_id<>p_owner or not(turn_id=any(turns)))) then conflicts:=conflicts||'"SHARED_TASK"'::jsonb;end if;
 if exists(select 1 from turn_private.assistant_goals where id=any(goals) and owner_id<>p_owner) or exists(select 1 from turn_private.assistant_goal_trip_links where goal_id=any(goals) and trip_id is not null and trip_id<>p_trip) or exists(select 1 from turn_private.assistant_goal_trip_receipts where goal_id=any(goals) and trip_id is not null and trip_id<>p_trip) then conflicts:=conflicts||'"SHARED_GOAL"'::jsonb;end if;
 if exists(select 1 from turn_private.assistant_messages where id=any(messages) and (owner_id<>p_owner or turn_id is not null and not(turn_id=any(turns)) or task_id is not null and not(task_id=any(tasks)))) or exists(select 1 from turn_private.assistant_messages where parent_message_id=any(messages) and not(id=any(messages))) then conflicts:=conflicts||'"SHARED_MESSAGE"'::jsonb;end if;
 if exists(select 1 from turn_private.result_artifacts where id=any(artifacts) and (owner_id<>p_owner or trip_id is not null and trip_id<>p_trip)) then conflicts:=conflicts||'"SHARED_ARTIFACT"'::jsonb;end if;
 if exists(select 1 from public.turns where id=any(turns) and status not in ('completed','proposal_ready','unavailable','failed','cancelled')) or exists(select 1 from turn_private.work where turn_id=any(turns) and state in ('queued','leased')) or exists(select 1 from public.model_budget_attempts where task_id=any(tasks) and status in ('reserved','dispatched','pending')) or exists(select 1 from turn_private.service_task_capacity where task_id=any(tasks) and state='reserved') then conflicts:=conflicts||'"ACTIVE_WORK"'::jsonb;end if;
 if exists(select 1 from public.trip_proposals child join public.trip_proposals parent on parent.id=child.parent_proposal_id where parent.trip_id=p_trip and child.trip_id<>p_trip)
 or exists(select 1 from turn_private.result_revisions r join turn_private.result_artifacts a on a.id=r.artifact_id where not(a.id=any(artifacts)) and r.content->'comparisonRef'->>'artifactId'=any(artifacts::text[]))
 or exists(select 1 from turn_private.result_revisions where task_turn_id=any(turns) and not(artifact_id=any(artifacts))) then conflicts:=conflicts||'"CROSS_SCOPE_REFERENCE"'::jsonb;end if;
 selection:=jsonb_build_object('threadIds',to_jsonb(threads),'turnIds',to_jsonb(turns),'taskIds',to_jsonb(tasks),'goalIds',to_jsonb(goals),'messageIds',to_jsonb(messages),'artifactIds',to_jsonb(artifacts),'exportRequestIds',to_jsonb(exports));
 counts:=jsonb_build_object('threads',cardinality(threads),'turns',cardinality(turns),'tasks',cardinality(tasks),'goals',cardinality(goals),'messages',cardinality(messages),'artifacts',cardinality(artifacts),'exports',cardinality(exports));
 select coalesce(jsonb_agg(x.item order by x.kind,x.id),'[]'),count(*) into derived,derived_n from (select * from (
  select 'proposal'::text kind,id::text id,jsonb_build_array('proposal',id,revision,status,parent_proposal_id,encode(sha256(convert_to(patch::text,'UTF8')),'hex')) item from public.trip_proposals where trip_id=p_trip
  union all select 'grounded',turn_id::text,jsonb_build_array('grounded',turn_id,encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')) from turn_private.grounded_turns r where turn_id=any(turns)
  union all select 'planning',turn_id::text,jsonb_build_array('planning',turn_id,state,task_id,message_id,goal_id) from turn_private.planning_comparisons where task_id=any(tasks)
  union all select 'capacity',task_id::text,jsonb_build_array('capacity',task_id,state,settled_turn_id) from turn_private.service_task_capacity where task_id=any(tasks)
  union all select 'budget',attempt_id::text,jsonb_build_array('budget',scope_id,attempt_id,task_id,status,actual_micros) from public.model_budget_attempts where task_id=any(tasks)
  union all select 'export_ticket',operation_id::text,jsonb_build_array('export_ticket',operation_id,generation,artifact_digest,expires_at,consumed_at,revoked_at) from export_private.core_tickets_v1 where request_id=any(exports)
 ) all_derived order by kind,id limit 4101) x;
 assistant_delivery_n:=turn_private.assistant_delivery_source_v1(p_owner,selection);
 directions_n:=turn_private.directions_source_witness_v1(p_owner,'d3',selection);
 if (directions_n->>'rowCount')::integer+jsonb_array_length(assistant_delivery_n->'rows')+derived_n+cardinality(threads)+cardinality(turns)+cardinality(tasks)+cardinality(goals)+cardinality(messages)+cardinality(artifacts)+cardinality(exports)>4100 then conflicts:=conflicts||'"SCOPE_TOO_LARGE"'::jsonb;selection:=jsonb_build_object('threadIds','[]'::jsonb,'turnIds','[]'::jsonb,'taskIds','[]'::jsonb,'goalIds','[]'::jsonb,'messageIds','[]'::jsonb,'artifactIds','[]'::jsonb,'exportRequestIds','[]'::jsonb);counts:=jsonb_build_object('threads',0,'turns',0,'tasks',0,'goals',0,'messages',0,'artifacts',0,'exports',0);return jsonb_build_object('selection',selection,'counts',counts,'conflicts','["SCOPE_TOO_LARGE"]'::jsonb,'graph','{}'::jsonb);end if;
 select coalesce(sum(octet_length(document_n::text)),0) into directions_raw_bytes_n from(
 select to_jsonb(t) document_n from public.trips t where t.id=p_trip
 union all select to_jsonb(p) from public.trip_proposals p where p.trip_id=p_trip
 union all select to_jsonb(t) from public.chat_threads t where t.id=any(threads)
 union all select to_jsonb(t) from public.turns t where t.id=any(turns)
 union all select to_jsonb(t) from turn_private.service_tasks t where t.id=any(tasks)
 union all select to_jsonb(t) from turn_private.assistant_goals t where t.id=any(goals)
 union all select to_jsonb(t) from turn_private.assistant_messages t where t.id=any(messages)
 union all select to_jsonb(t) from turn_private.result_artifacts t where t.id=any(artifacts)
 union all select to_jsonb(t) from turn_private.result_revisions t where t.artifact_id=any(artifacts)
 union all select to_jsonb(t) from turn_private.result_events t where t.artifact_id=any(artifacts)
 union all select to_jsonb(t) from turn_private.text_content t where t.turn_id=any(turns)
 union all select to_jsonb(t) from turn_private.grounded_turns t where t.turn_id=any(turns)
 union all select to_jsonb(t) from turn_private.planning_comparisons t where t.task_id=any(tasks)
 union all select to_jsonb(t) from turn_private.service_task_capacity t where t.task_id=any(tasks)
 union all select to_jsonb(t) from public.model_budget_attempts t where t.task_id=any(tasks)
 union all select to_jsonb(t) from export_private.core_jobs_v1 t where t.request_id=any(exports)
 union all select to_jsonb(t) from export_private.core_tickets_v1 t where t.request_id=any(exports)
 ) exact_touched_payloads;
 graph:=jsonb_build_object('directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'derived',derived,'trip',(select jsonb_build_array(id,owner_id,head_version,encode(sha256(convert_to(title,'UTF8')),'hex')) from public.trips where id=p_trip),'tripProposals',(select coalesce(jsonb_agg(jsonb_build_array(id,revision,base_trip_version,status,parent_proposal_id,encode(sha256(convert_to(patch::text,'UTF8')),'hex')) order by id),'[]') from public.trip_proposals where trip_id=p_trip),'selection',selection,'exports',(select coalesce(jsonb_agg(jsonb_build_array(request_id,generation,state,artifact_digest,artifact_expires_at,lease_id,lease_expires_at) order by request_id),'[]') from export_private.core_jobs_v1 where request_id=any(exports)),'threads',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,trip_id,status) order by id),'[]') from public.chat_threads where id=any(threads)),
 'turns',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,thread_id,trip_id,status) order by id),'[]') from public.turns where id=any(turns)),
 'tasks',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,thread_id,goal_turn_id,last_turn_id,budget_scope_id) order by id),'[]') from turn_private.service_tasks where id=any(tasks)),
 'goals',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,scope_version,encode(sha256(convert_to(current_text,'UTF8')),'hex')) order by id),'[]') from turn_private.assistant_goals where id=any(goals)),
 'messages',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,sequence,goal_id,scope_version,task_id,parent_message_id,turn_id,request_digest) order by id),'[]') from turn_private.assistant_messages where id=any(messages)),
 'artifacts',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,trip_id,current_revision,lifecycle) order by id),'[]') from turn_private.result_artifacts where id=any(artifacts)),
 'text',(select coalesce(jsonb_agg(jsonb_build_array(turn_id,owner_id,thread_id,encode(sha256(convert_to(jsonb_build_array(input_text,output_kind,output_text,hidden_at)::text,'UTF8')),'hex')) order by turn_id),'[]') from turn_private.text_content where turn_id=any(turns)));
 if directions_raw_bytes_n+(directions_n->>'bytes')::bigint>1000000 or octet_length(convert_to(graph::text,'UTF8'))>1000000 then
  selection:=jsonb_build_object('threadIds','[]'::jsonb,'turnIds','[]'::jsonb,'taskIds','[]'::jsonb,'goalIds','[]'::jsonb,'messageIds','[]'::jsonb,'artifactIds','[]'::jsonb,'exportRequestIds','[]'::jsonb);
  counts:=jsonb_build_object('threads',0,'turns',0,'tasks',0,'goals',0,'messages',0,'artifacts',0,'exports',0);
  return jsonb_build_object('selection',selection,'counts',counts,'conflicts','["SCOPE_TOO_LARGE"]'::jsonb,'graph','{}'::jsonb);
 end if;
 return jsonb_build_object('selection',selection,'counts',counts,'conflicts',conflicts,'graph',graph);
end $function$;

CREATE OR REPLACE FUNCTION public.privacy_linked_trip_delete_v1(p_action text, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare keys text[];actor jsonb;u uuid;trip uuid;version integer;plan privacy_private.linked_delete_plans_v1%rowtype;j privacy_private.linked_delete_jobs_v1%rowtype;
 request uuid;operation uuid;lease uuid;g jsonb;s jsonb;digest text;retained jsonb:='["FINANCIAL_LEDGER_MINIMUM","TASK_CAPACITY_MINIMUM","EXTERNAL_DOWNLOADED_COPIES","PROVIDER_COPIES_NOT_ERASED","BACKUP_ERASURE_NOT_VERIFIED"]';
 name text;ids uuid[];turns uuid[];messages uuid[];goals uuid[];tasks uuid[];artifacts uuid[];threads uuid[];exports uuid[];count_n integer;erased jsonb;worker privacy_private.linked_delete_worker_settings_v1%rowtype;r privacy_private.trip_deletions%rowtype;
begin
 keys:=case p_action when 'preview' then array['tripId','expectedVersion'] when 'confirm' then array['requestId','planId','scopeDigest','expectedVersion','confirmed','selection'] when 'read' then array['requestId'] when 'claim' then array['requestId','operationId'] when 'execute' then array['requestId','leaseId'] when 'purge' then array['operationId','limit'] else null end;
 if keys is null or jsonb_typeof(p_input) is distinct from 'object' or not(p_input ?& keys) or exists(select 1 from jsonb_object_keys(p_input) k where not(k=any(keys))) then raise exception 'INVALID_INPUT';end if;
 if p_action in ('claim','execute','purge') then if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN';end if;
 else actor:=privacy_private.linked_delete_actor_v1(p_action<>'read');u:=(actor->>'subject')::uuid;end if;
 if p_input ? 'requestId' then if jsonb_typeof(p_input->'requestId') is distinct from 'string' or p_input->>'requestId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then raise exception 'INVALID_INPUT';end if;request:=(p_input->>'requestId')::uuid;end if;
 if p_action='purge' then
  if jsonb_typeof(p_input->'operationId') is distinct from 'string' or p_input->>'operationId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' or jsonb_typeof(p_input->'limit') is distinct from 'number' or p_input->>'limit' !~ '^[1-9][0-9]{0,2}$' or (p_input->>'limit')::integer>100 then raise exception 'INVALID_INPUT';end if;
  delete from privacy_private.linked_delete_plans_v1 where id in(select p.id from privacy_private.linked_delete_plans_v1 p where p.expires_at<=clock_timestamp() and not exists(select 1 from privacy_private.linked_delete_jobs_v1 q where q.plan_id=p.id) order by p.id limit (p_input->>'limit')::integer for update of p skip locked);get diagnostics count_n=row_count;
  return jsonb_build_object('kind','linked_trip_delete_purge/1','removedPlans',count_n);
 end if;
 if p_action='preview' then
  if jsonb_typeof(p_input->'tripId') is distinct from 'string' or p_input->>'tripId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' or jsonb_typeof(p_input->'expectedVersion') is distinct from 'number' or p_input->>'expectedVersion' !~ '^(0|[1-9][0-9]{0,8})$' then raise exception 'INVALID_INPUT';end if;
  trip:=(p_input->>'tripId')::uuid;version:=(p_input->>'expectedVersion')::integer;
  perform 1 from public.trips where id=trip and owner_id=u and head_version=version for share nowait;if not found then raise exception 'STALE_TRIP_VERSION';end if;
  if exists(select 1 from privacy_private.trip_deletions where trip_id=trip) then raise exception 'DELETION_ALREADY_REQUESTED';end if;
  g:=privacy_private.linked_delete_graph_v1(u,trip);digest:=encode(sha256(convert_to(jsonb_build_array(u,trip,version,g->'graph',g->'selection',g->'conflicts')::text,'UTF8')),'hex');
  insert into privacy_private.linked_delete_plans_v1(owner_id,session_id,session_epoch,trip_id,head_version,scope_digest,graph,selection,counts,conflicts,retained,expires_at)
   values(u,(actor->>'sessionId')::uuid,(actor->>'mobileEpoch')::bigint,trip,version,digest,g->'graph',g->'selection',g->'counts',g->'conflicts',retained,clock_timestamp()+interval '5 minutes') returning * into plan;
  return jsonb_build_object('kind','linked_trip_delete_plan/1','planId',plan.id,'tripId',trip,'title',(select title from public.trips where id=trip),'expectedVersion',version,'scopeDigest',digest,'expiresAt',export_private.ms_v1(plan.expires_at),'selection',plan.selection,'counts',plan.counts,'conflicts',plan.conflicts,'retained',plan.retained);
 end if;
 if p_action='confirm' then
  if p_input->'confirmed' is distinct from 'true'::jsonb or jsonb_typeof(p_input->'planId') is distinct from 'string' or p_input->>'planId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then raise exception 'INVALID_INPUT';end if;
  select * into plan from privacy_private.linked_delete_plans_v1 where id=(p_input->>'planId')::uuid and owner_id=u;
  if not found then raise exception 'FORBIDDEN';end if;
  if p_input->>'scopeDigest' is distinct from plan.scope_digest or p_input->'expectedVersion' is distinct from to_jsonb(plan.head_version) then raise exception 'SCOPE_CHANGED';end if;
  if p_input->'selection' is distinct from plan.selection then raise exception 'SCOPE_NOT_COMPLETE';end if;
  select * into j from privacy_private.linked_delete_jobs_v1 where request_id=request;
  if found then if j.owner_id<>u or j.plan_id<>plan.id then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;return privacy_private.linked_delete_receipt_v1(j);end if;
  if plan.expires_at<=clock_timestamp() then raise exception 'PLAN_EXPIRED';end if;
  if plan.session_id is distinct from (actor->>'sessionId')::uuid or plan.session_epoch is distinct from (actor->>'mobileEpoch')::bigint then raise exception 'SESSION_REPLACED';end if;
  if plan.conflicts<>'[]'::jsonb then raise exception 'SCOPE_CONFLICT';end if;
  perform privacy_private.linked_delete_lock_graph_v1(u,plan.trip_id,plan.selection);
  if not exists(select 1 from public.trips where id=plan.trip_id and owner_id=u and head_version=plan.head_version) then raise exception 'STALE_TRIP_VERSION';end if;
  g:=privacy_private.linked_delete_graph_v1(u,plan.trip_id);
