 delete from turn_private.assistant_goals where id=any(goals) and owner_id=j.owner_id;get diagnostics count_n=row_count;erased:=jsonb_set(erased,'{goals}',to_jsonb(count_n));
 update turn_private.text_content set input_text='[deleted by scoped Trip request]',output_kind=null,output_text=null,hidden_at=coalesce(hidden_at,clock_timestamp()) where turn_id=any(turns) and owner_id=j.owner_id;get diagnostics count_n=row_count;erased:=jsonb_set(erased,'{textBodies}',to_jsonb(count_n));
 delete from public.memory_consumer_receipts where turn_id=any(turns) and owner_id=j.owner_id;get diagnostics count_n=row_count;erased:=jsonb_set(erased,'{consumerReferences}',to_jsonb(count_n));
 delete from public.turns where id=any(turns) and owner_id=j.owner_id;get diagnostics count_n=row_count;erased:=jsonb_set(erased,'{turns}',to_jsonb(count_n));
 delete from public.chat_threads where id=any(threads) and owner_id=j.owner_id;get diagnostics count_n=row_count;erased:=jsonb_set(erased,'{threads}',to_jsonb(count_n));
 perform public.execute_trip_deletion_v1(request);
 update privacy_private.linked_delete_jobs_v1 set erased_counts=erased,completed_at=clock_timestamp(),expected_graph='{}'::jsonb,execution_xid=null,execution_action=null,execution_digest=null where request_id=request returning * into j;
 update privacy_private.linked_delete_plans_v1 set graph='{}'::jsonb where id=j.plan_id;
 return privacy_private.linked_delete_receipt_v1(j);
end $function$;

CREATE OR REPLACE FUNCTION turn_data_private.source_key_v1(rel text, v jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select case rel when 'turn_private.assistant_directions_intakes_v1' then turn_data_private.row_key_v1(v,array['message_id']::text[]) when 'turn_private.directions_result_sources_v1' then turn_data_private.row_key_v1(v,array['artifact_id']::text[]) when 'turn_private.directions_operations_v1' then turn_data_private.row_key_v1(v,array['owner_id','operation_id']::text[]) else (select turn_data_private.row_key_v1(v,s.pk) from turn_data_private.sources_v1() s where s.relation_name=rel and s.effect='erase') end
$function$;

-- Constituent: fences.candidate.sql
-- ARTIFACT ONLY. Existing permanent Result/Convo/Turn/D3 fences on typed parents.
create function turn_private.guard_directions_linked_parent_v1() returns trigger
language plpgsql volatile security definer set search_path='' as $$
declare nv jsonb:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 ov jsonb:=case when tg_op='INSERT' then nv else to_jsonb(old) end;r record;k text;f privacy_private.linked_delete_fences_v1%rowtype;
begin
 if tg_op='DELETE' and not exists(select 1 from auth.users where id=(nv->>'owner_id')::uuid) then return old;end if;
 for r in select distinct parents.kind collate "C" kind,parents.entity_id from(
  select * from turn_private.directions_parents_v1(tg_table_schema||'.'||tg_table_name,nv)
  union select * from turn_private.directions_parents_v1(tg_table_schema||'.'||tg_table_name,ov)) parents order by parents.kind collate "C",parents.entity_id loop
  k:=case r.kind when 'turnIds' then 'turn' when 'taskIds' then 'task' when 'goalIds' then 'goal' when 'messageIds' then 'message' when 'artifactIds' then 'artifact' end;
  if k is null then continue;end if;
  select * into f from privacy_private.linked_delete_fences_v1 where entity_kind=k and entity_id=r.entity_id;
  if found and exists(select 1 from auth.users where id=f.owner_id)
   and privacy_private.linked_delete_erase_authority_v1(f.request_id,k,r.entity_id) is distinct from true then raise exception 'LINKED_TRIP_DELETION_PENDING';end if;
 end loop;
 if tg_op='DELETE' then return old;else return new;end if;
end $$;
do $hooks$ declare relation_n text;begin
 foreach relation_n in array array['assistant_directions_intakes_v1','directions_result_sources_v1','directions_operations_v1'] loop
  execute format('create trigger conversation_source_fence_v1 before insert or update or delete on turn_private.%I for each row execute function conversation_data_private.guard_source_v1()',relation_n);
  execute format('create trigger result_source_fence_v1 before insert or update or delete on turn_private.%I for each row execute function result_data_private.guard_source_v1()',relation_n);
  execute format('create trigger turn_data_parent_fence_v1 before insert or update or delete on turn_private.%I for each row execute function turn_data_private.guard_source_v1()',relation_n);
  execute format('create trigger linked_delete_fence_v1 before insert or update or delete on turn_private.%I for each row execute function turn_private.guard_directions_linked_parent_v1()',relation_n);
 end loop;
end $hooks$;
revoke all on function turn_private.guard_directions_linked_parent_v1() from public,anon,authenticated,service_role;

-- Constituent: export.candidate.sql
-- ARTIFACT ONLY. Main approved existing conversations module/three extra sections.
-- Original five-section public RPC is preserved outside one exact new-section branch.
create function turn_private.directions_export_page_v1(owner_n uuid,section_n text,after_n uuid,limit_n integer)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare r record;page_n jsonb:='[]';item_n jsonb;cursor_n uuid;more_n boolean:=false;delivered_n integer:=0;candidate_n integer:=0;envelope_n jsonb;
begin
 if auth.role() is distinct from 'service_role' or owner_n is null then raise exception 'FORBIDDEN';end if;
 if section_n is null or section_n not in('directionIntakes','directionSources','directionOperations') or limit_n is null or limit_n not between 1 and 100 then raise exception 'INVALID_INPUT';end if;
 if after_n is not null and not exists(
  select 1 from turn_private.assistant_directions_intakes_v1 where section_n='directionIntakes' and owner_id=owner_n and message_id=after_n
  union all select 1 from turn_private.directions_result_sources_v1 where section_n='directionSources' and owner_id=owner_n and artifact_id=after_n
  union all select 1 from turn_private.directions_operations_v1 where section_n='directionOperations' and owner_id=owner_n and operation_id=after_n) then raise exception 'STALE_EXPORT_CURSOR';end if;
 for r in select * from(
  select i.message_id id,jsonb_build_object('messageId',i.message_id,'intakeRevision',i.intake_revision,'goalId',i.goal_id,'conversationId',i.conversation_id,'taskId',i.task_id,'taskTurnId',i.task_turn_id,
   'messageSequence',i.message_sequence,'goalVersion',i.goal_version,'policyId',i.policy_id,'consentId',i.consent_id,'planningPolicyId',i.planning_policy_id,'planningConsentId',i.planning_consent_id,
   'idempotencyKey',i.idempotency_key,'requestBytesDigest',i.request_bytes_digest,'intake',i.intake,'memoryBasis',i.memory_basis,'createdAt',i.created_at) item
   from turn_private.assistant_directions_intakes_v1 i where section_n='directionIntakes' and i.owner_id=owner_n and (after_n is null or i.message_id>after_n)
  union all select s.artifact_id,jsonb_build_object('artifactId',s.artifact_id,'messageId',s.message_id,'taskTurnId',s.task_turn_id,'sourceDigest',s.source_digest,
   'initialContentDigest',s.initial_content_digest,'initialOutputDigest',s.initial_output_digest,'previousArtifactId',s.previous_artifact_id,'previousRevision',s.previous_revision,'publicationKey',s.publication_key,'createdAt',s.created_at)
   from turn_private.directions_result_sources_v1 s where section_n='directionSources' and s.owner_id=owner_n and (after_n is null or s.artifact_id>after_n)
  union all select o.operation_id,jsonb_build_object('operationId',o.operation_id,'sessionId',o.session_id,'action',o.action,'requestBytesDigest',o.request_bytes_digest,'erased',o.erased,
   'artifactId',o.artifact_id,'sourceMessageId',o.source_message_id,'taskTurnId',o.task_turn_id,'expectedRevision',o.expected_revision,'resultRevision',o.result_revision,'sourceDigest',o.source_digest,
   'outputContentDigest',o.output_content_digest,'tripId',o.trip_id,'proposalId',o.proposal_id,'proposalArtifactId',o.proposal_artifact_id,'receipt',o.receipt,'createdAt',o.created_at)
   from turn_private.directions_operations_v1 o where section_n='directionOperations' and o.owner_id=owner_n and (after_n is null or o.operation_id>after_n)
 ) rows order by id limit limit_n+1 loop
  candidate_n:=candidate_n+1;if delivered_n>=limit_n then more_n:=true;exit;end if;
  envelope_n:=jsonb_build_object('schemaVersion','assistant-conversation-export/1','section',section_n,'items',page_n||jsonb_build_array(r.item),'hasMore',true,'nextCursor',r.id,'sectionComplete',false);
  if octet_length(convert_to(envelope_n::text,'UTF8'))>1000000 then
   if delivered_n=0 then raise exception 'EXPORT_PAGE_TOO_LARGE';end if;
   more_n:=true;exit;
  end if;
  page_n:=page_n||jsonb_build_array(r.item);cursor_n:=r.id;delivered_n:=delivered_n+1;
 end loop;
 return jsonb_build_object('schemaVersion','assistant-conversation-export/1','section',section_n,'items',page_n,'hasMore',more_n,'nextCursor',case when more_n then cursor_n else null end,'sectionComplete',not more_n);
end $$;
revoke all on function turn_private.directions_export_page_v1(uuid,text,uuid,integer) from public,anon,authenticated,service_role;

-- Constituent: conversations-export.after.sql
-- ARTIFACT ONLY: original service-only ACL/currentowner/Main lease required.
CREATE OR REPLACE FUNCTION public.assistant_conversation_export_owner_v1(p_owner uuid, p_section text, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare page jsonb; more boolean; cursor uuid;
begin
  if p_section in('directionIntakes','directionSources','directionOperations') then return turn_private.directions_export_page_v1(p_owner,p_section,p_after_id,p_limit);end if;
  if (select auth.role()) is distinct from 'service_role' or p_owner is null then
    raise exception 'FORBIDDEN';
  end if;
  if p_section is null or p_section not in ('conversations','goals','messages','goalTripLinks','goalTripReceipts')
    or p_limit is null or p_limit not between 1 and 100 then raise exception 'INVALID_INPUT'; end if;
  -- Deleted, unknown and foreign-owner anchors uniformly require an export restart.
  if p_after_id is not null and not exists(
    select 1 from turn_private.assistant_conversations where p_section='conversations' and owner_id=p_owner and id=p_after_id
    union all
    select 1 from turn_private.assistant_goals where p_section='goals' and owner_id=p_owner and id=p_after_id
    union all
    select 1 from turn_private.assistant_messages where p_section='messages' and owner_id=p_owner and id=p_after_id
    union all
    select 1 from turn_private.assistant_goal_trip_links where p_section='goalTripLinks' and owner_id=p_owner and goal_id=p_after_id
    union all
    select 1 from turn_private.assistant_goal_trip_receipts where p_section='goalTripReceipts' and owner_id=p_owner and operation_id=p_after_id
  ) then raise exception 'INVALID_EXPORT_CURSOR'; end if;
  with candidates as (
    (select id as id,jsonb_build_object(
      'conversationId',id,'policyId',policy_id,
      'consentId',consent_id,'nextSequence',next_sequence,
      'createdAt',created_at) as item
      from turn_private.assistant_conversations
      where p_section='conversations' and owner_id=p_owner
        and id>=coalesce(p_after_id,'00000000-0000-0000-0000-000000000000'::uuid)
        and (p_after_id is null or id>p_after_id)
      order by id limit p_limit+1)
    union all
    (select id as id,jsonb_build_object(
      'goalId',id,'conversationId',conversation_id,
      'scopeVersion',scope_version,'text',current_text,
      'tripTerminal',trip_terminal,'createdAt',created_at) as item
      from turn_private.assistant_goals
      where p_section='goals' and owner_id=p_owner
        and id>=coalesce(p_after_id,'00000000-0000-0000-0000-000000000000'::uuid)
        and (p_after_id is null or id>p_after_id)
      order by id limit p_limit+1)
    union all
    (select id as id,jsonb_build_object(
      'messageId',id,'conversationId',conversation_id,
      'sequence',sequence,'policyId',policy_id,
      'consentId',consent_id,'locale',locale,
      'text',input_text,'relationship',relationship,
      'goalId',goal_id,'scopeVersion',scope_version,
      'taskId',task_id,'parentMessageId',parent_message_id,
      'turnId',turn_id,'createdAt',created_at) as item
      from turn_private.assistant_messages
      where p_section='messages' and owner_id=p_owner
        and id>=coalesce(p_after_id,'00000000-0000-0000-0000-000000000000'::uuid)
        and (p_after_id is null or id>p_after_id)
      order by id limit p_limit+1)
    union all
    (select goal_id as id,jsonb_build_object(
      'goalId',goal_id,'conversationId',conversation_id,
      'linkVersion',link_version,'goalScopeVersion',goal_scope_version,
      'lastOperationId',operation_id,'terminalUnlinked',terminal_unlinked,
      'tripId',trip_id,'tripHeadVersion',trip_head_version,
      'sourceMessageId',source_message_id,'updatedAt',updated_at) as item
      from turn_private.assistant_goal_trip_links
      where p_section='goalTripLinks' and owner_id=p_owner
        and goal_id>=coalesce(p_after_id,'00000000-0000-0000-0000-000000000000'::uuid)
        and (p_after_id is null or goal_id>p_after_id)
      order by goal_id limit p_limit+1)
    union all
    (select operation_id as id,jsonb_build_object(
      'operationId',operation_id,'goalId',goal_id,
      'action',action,'sourceKind',source_kind,
      'sourceMessageId',source_message_id,'beforeLinkVersion',before_link_version,
      'afterLinkVersion',after_link_version,'beforeGoalScopeVersion',before_goal_scope_version,
      'afterGoalScopeVersion',after_goal_scope_version,'tripId',trip_id,
      'tripHeadVersion',trip_head_version,'createdAt',created_at) as item
      from turn_private.assistant_goal_trip_receipts
      where p_section='goalTripReceipts' and owner_id=p_owner
        and operation_id>=coalesce(p_after_id,'00000000-0000-0000-0000-000000000000'::uuid)
        and (p_after_id is null or operation_id>p_after_id)
      order by operation_id limit p_limit+1)
  ), page_window as (
    select id,item from candidates order by id limit p_limit+1
  ), delivered as (
    select id,item from page_window order by id limit p_limit
  )
  select coalesce((select jsonb_agg(item order by id) from delivered),'[]'::jsonb),
    (select count(*)>p_limit from page_window),
    (select id from delivered order by id desc limit 1)
    into page,more,cursor;
  return jsonb_build_object('schemaVersion','assistant-conversation-export/1',
    'section',p_section,'items',page,'hasMore',more,
    'nextCursor',case when more then cursor else null end,'sectionComplete',not more);
end $function$;

-- Constituent: export-current.candidate.sql
-- REVIEW CANDIDATE: necessary original-job source snapshot field, not a new
-- export module/permission/planner store. Main exact table/function lease required.
alter table export_private.core_jobs_v1 add column directions_source_digest text
 check(directions_source_digest is null or directions_source_digest ~ '^[a-f0-9]{64}$');
create function turn_private.directions_export_source_digest_v1(u uuid) returns text
language plpgsql volatile security definer set search_path='' as $$
declare r record;rows_n jsonb[]:=array[]::jsonb[];n integer:=0;bytes_n bigint:=0;item_n jsonb;
begin
 if u is null or not exists(select 1 from auth.users where id=u) then raise exception 'FORBIDDEN';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('directions-export-source:'||u::text,0)) then raise lock_not_available using message='EXPORT_CONFLICT';end if;
 for r in select * from(
  select 'directionIntakes'::text section_n,message_id id,to_jsonb(i) data from turn_private.assistant_directions_intakes_v1 i where owner_id=u
  union all select 'directionSources',artifact_id,to_jsonb(s) from turn_private.directions_result_sources_v1 s where owner_id=u
  union all select 'directionOperations',operation_id,to_jsonb(o) from turn_private.directions_operations_v1 o where owner_id=u
 ) rows order by section_n collate "C",id limit 10001 loop
  item_n:=jsonb_build_object('section',r.section_n,'id',r.id,'row',r.data);n:=n+1;bytes_n:=bytes_n+octet_length(convert_to(item_n::text,'UTF8'));
  if n>10000 or bytes_n>1000000 then raise exception 'EXPORT_SOURCE_TOO_LARGE';end if;
  rows_n:=array_append(rows_n,item_n);
 end loop;
 item_n:=to_jsonb(rows_n);if octet_length(convert_to(item_n::text,'UTF8'))>1000000 then raise exception 'EXPORT_SOURCE_TOO_LARGE';end if;
 return encode(sha256(convert_to(item_n::text,'UTF8')),'hex');
end $$;
create function turn_private.guard_directions_export_source_v1() returns trigger
language plpgsql volatile security definer set search_path='' as $$
declare u uuid:=case when tg_op='DELETE' then old.owner_id else new.owner_id end;
begin
 if tg_op='DELETE' and not exists(select 1 from auth.users where id=u) then return old;end if;
 if not pg_try_advisory_xact_lock_shared(hashtextextended('directions-export-source:'||u::text,0)) then raise lock_not_available using message='EXPORT_CONFLICT';end if;
 if tg_op='DELETE' then return old;else return new;end if;
end $$;
do $hooks$ declare relation_n text;begin
 foreach relation_n in array array['assistant_directions_intakes_v1','directions_result_sources_v1','directions_operations_v1'] loop
  execute format('create trigger directions_export_source_fence_v1 before insert or update or delete on turn_private.%I for each row execute function turn_private.guard_directions_export_source_v1()',relation_n);
 end loop;
end $hooks$;
create function export_private.directions_source_current_v1(j export_private.core_jobs_v1) returns boolean
language plpgsql volatile security definer set search_path='' as $$
begin
 if j.directions_source_digest is null then
  -- Legacy jobs carry no new source snapshot and cannot export new directions.
  return not exists(select 1 from turn_private.assistant_directions_intakes_v1 where owner_id=j.owner_id)
   and not exists(select 1 from turn_private.directions_result_sources_v1 where owner_id=j.owner_id)
   and not exists(select 1 from turn_private.directions_operations_v1 where owner_id=j.owner_id);
 end if;
 return j.directions_source_digest=turn_private.directions_export_source_digest_v1(j.owner_id);
exception when lock_not_available then return false;
end $$;
revoke all on function turn_private.directions_export_source_digest_v1(uuid),turn_private.guard_directions_export_source_v1(),export_private.directions_source_current_v1(export_private.core_jobs_v1) from public,anon,authenticated,service_role;

-- Constituent: export-current-seams.review.sql
-- Exact minimal original job source field guards Convo directions even if Turn module has0pages/rows.
CREATE OR REPLACE FUNCTION export_private.lock_job_v1(p_request uuid, worker boolean)
 RETURNS export_private.core_jobs_v1
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j export_private.core_jobs_v1;p export_private.core_policies_v1%rowtype;
begin
 select * into j from export_private.core_jobs_v1 where request_id=p_request;if not found then return null;end if;
 select * into p from export_private.core_policies_v1 where id=j.policy_id for share nowait;
 if not found or not p.enabled or p.revoked_at is not null or p.valid_until<=clock_timestamp() or to_jsonb(p) is distinct from j.policy_snapshot then return null;end if;
 perform 1 from auth.users where id=j.owner_id for key share nowait;if not found then return null;end if;
 perform 1 from identity_private.mobile_accounts where owner_id=j.owner_id for update;if not found then return null;end if;
 if worker then
  if not exists(select 1 from identity_private.mobile_accounts where owner_id=j.owner_id and session_id=j.session_id and epoch=j.session_epoch) then return null;end if;
  perform 1 from auth.sessions where id=j.session_id and user_id=j.owner_id for key share;if not found then return null;end if;
 end if;
 perform 1 from public.privacy_requests where id=p_request and owner_id=j.owner_id and action='export' and scope_version='all-user-data-v1' and status='requested' and execution_state='not_started' for share nowait;if not found then return null;end if;
 select * into j from export_private.core_jobs_v1 where request_id=p_request for update nowait;
 if export_private.memory_source_current_v1(j) is distinct from true then return null;end if;
 if export_private.entitlement_source_current_v1(j) is distinct from true then return null;end if;
 if pdf_intake_private.export_current_v1(j) is distinct from true then return null;end if;
 if export_private.profile_source_current_v1(j) is distinct from true then return null;end if;
 if export_private.turn_source_current_v1(j) is distinct from true then return null;end if;
 if export_private.directions_source_current_v1(j) is distinct from true then return null;end if;
 return j;
exception when lock_not_available then return null;
end $function$;

CREATE OR REPLACE FUNCTION public.privacy_core_export_v1(p_action text, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare keys text[];role text:=auth.role();req uuid;op uuid;lease uuid;gen integer;actor jsonb;u uuid;
 policy export_private.core_policies_v1%rowtype;j export_private.core_jobs_v1%rowtype;ticket export_private.core_tickets_v1%rowtype;a export_private.core_artifacts_v1%rowtype;
 artifact jsonb;nonce bytea;tag bytea;cipher bytea;digest text;expires timestamptz;run_ms integer;ttl integer;limit_n integer;cursor uuid;page jsonb;more boolean;next_id uuid;all_complete boolean;
 profile_lease_deadline timestamptz;turn_lease_deadline timestamptz;removed integer:=0;removed_tickets integer:=0;c record;old_intent public.privacy_requests%rowtype;
begin
 if p_action='memory_page' then return export_private.core_memory_page_v1(p_input);end if;
 if p_action='entitlement_page' then return export_private.entitlement_page_v1(p_input);end if;
 if p_action='profile_page' then return export_private.core_profile_page_v1(p_input);end if;
 if p_action='turn_page' then return export_private.core_turn_page_v1(p_input);end if;
 keys:=case p_action
 when 'request' then array['requestId','confirmed'] when 'read' then array['requestId']
 when 'claim' then array['requestId','operationId','maxRunMs','expectedEnvironment','expectedKeyId']
 when 'validate' then array['requestId','leaseId','generation'] when 'trip_page' then array['requestId','leaseId','generation','afterTripId','limit']
 when 'commit' then array['requestId','leaseId','generation','artifact','modules','coverage']
 when 'execution_receipt' then array['requestId','leaseId','generation','expectedArtifactDigest']
 when 'fail' then array['requestId','leaseId','generation','reason']
 when 'ticket' then array['requestId','operationId','tokenHash','ticketTtlMs']
 when 'download_prepare' then array['requestId','operationId','tokenHash']
 when 'download_consume' then array['requestId','operationId','tokenHash','artifactDigest','generation']
 when 'purge' then array['operationId','limit'] else null end;
 if keys is null or jsonb_typeof(p_input) is distinct from 'object' or not(p_input ?& keys) or exists(select 1 from jsonb_object_keys(p_input) k where not(k=any(keys))) then raise exception 'INVALID_INPUT';end if;
 if p_action in ('request','read','ticket','download_prepare','download_consume') then
  if role is distinct from 'authenticated' then raise exception 'FORBIDDEN';end if;
 else if role is distinct from 'service_role' then raise exception 'FORBIDDEN';end if;end if;
 if p_input ? 'requestId' then
  if jsonb_typeof(p_input->'requestId') is distinct from 'string' or p_input->>'requestId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then raise exception 'INVALID_INPUT';end if;req:=(p_input->>'requestId')::uuid;
 end if;
 if p_input ? 'operationId' then
  if jsonb_typeof(p_input->'operationId') is distinct from 'string' or p_input->>'operationId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then raise exception 'INVALID_INPUT';end if;op:=(p_input->>'operationId')::uuid;
 end if;
 if p_input ? 'leaseId' then
  if jsonb_typeof(p_input->'leaseId') is distinct from 'string' or p_input->>'leaseId' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then raise exception 'INVALID_INPUT';end if;lease:=(p_input->>'leaseId')::uuid;
 end if;
 if p_input ? 'generation' then
  if jsonb_typeof(p_input->'generation') is distinct from 'number' or p_input->>'generation' !~ '^[1-3]$' then raise exception 'INVALID_INPUT';end if;gen:=(p_input->>'generation')::integer;
 end if;
 if p_input ? 'tokenHash' and (jsonb_typeof(p_input->'tokenHash') is distinct from 'string' or p_input->>'tokenHash' !~ '^[a-f0-9]{64}$') then raise exception 'INVALID_INPUT';end if;
 if p_action='request' then
  if p_input->'confirmed' is distinct from 'true'::jsonb then raise exception 'INVALID_INPUT';end if;
  select * into policy from export_private.core_policies_v1 where enabled for share nowait;
  if not found or policy.revoked_at is not null or policy.valid_until<=clock_timestamp() then raise exception 'EXPORT_POLICY_UNCONFIGURED';end if;
  actor:=export_private.current_native_v1(true);u:=(actor->>'subject')::uuid;
  select * into old_intent from public.privacy_requests where id=req for update;
  if found and (old_intent.owner_id<>u or old_intent.action<>'export' or old_intent.scope_version<>'all-user-data-v1' or old_intent.status<>'requested' or old_intent.execution_state<>'not_started') then raise exception 'EXPORT_CONFLICT';end if;
  perform public.request_privacy_action(req,'export');
  select * into j from export_private.core_jobs_v1 where request_id=req for update;
  if found then if j.owner_id<>u or j.scope<>'core-export-d2/1' then raise exception 'EXPORT_CONFLICT';end if;return export_private.job_receipt_v1(j);end if;
  insert into export_private.core_jobs_v1(request_id,owner_id,session_id,session_epoch,policy_id,policy_snapshot,state,expires_at,directions_source_digest)
  values(req,u,(actor->>'sessionId')::uuid,(actor->>'mobileEpoch')::bigint,policy.id,to_jsonb(policy),'queued',least(policy.valid_until,clock_timestamp()+2*policy.artifact_ttl_ms*interval '1 millisecond'),turn_private.directions_export_source_digest_v1(u)) returning * into j;
  return export_private.job_receipt_v1(j);
 end if;
 if p_action='purge' then
  if jsonb_typeof(p_input->'limit') is distinct from 'number' or p_input->>'limit' !~ '^[1-9][0-9]{0,2}$' or (p_input->>'limit')::integer>100 then raise exception 'INVALID_INPUT';end if;limit_n:=(p_input->>'limit')::integer;
  for c in select request_id,owner_id from export_private.core_jobs_v1 where expires_at<=clock_timestamp() or artifact_expires_at<=clock_timestamp() order by request_id limit limit_n loop
   begin
    perform 1 from auth.users where id=c.owner_id for key share nowait;
    perform 1 from identity_private.mobile_accounts where owner_id=c.owner_id for update nowait;
    select * into j from export_private.core_jobs_v1 where request_id=c.request_id for update nowait;
    delete from export_private.core_tickets_v1 where request_id=j.request_id;get diagnostics ttl=row_count;removed_tickets:=removed_tickets+ttl;
    delete from export_private.core_artifacts_v1 where request_id=j.request_id;get diagnostics ttl=row_count;removed:=removed+ttl;
    update export_private.core_jobs_v1 set state='expired',lease_id=null,lease_expires_at=null,artifact_digest=null,artifact_bytes=null,artifact_expires_at=null,modules='[]' where request_id=j.request_id;
   exception when lock_not_available then null;end;
  end loop;
  delete from export_private.core_tickets_v1 where operation_id in (select operation_id from export_private.core_tickets_v1 where expires_at<=clock_timestamp() order by operation_id limit limit_n);get diagnostics ttl=row_count;
  return jsonb_build_object('kind','privacy_export_purge/1','removedArtifacts',removed,'removedTickets',removed_tickets+ttl);
 end if;
 -- Pin job policy before native/current actor locks. Metadata lookup is not authority.
 select p.* into policy from export_private.core_policies_v1 p join export_private.core_jobs_v1 q on q.policy_id=p.id where q.request_id=req for share of p nowait;
 if not found then if p_action='execution_receipt' then return jsonb_build_object('kind','privacy_export_execution_receipt/1','outcome','unknown','receipt',null);else raise exception 'FORBIDDEN';end if;end if;
 if p_action in ('read','ticket','download_prepare','download_consume') then
  actor:=export_private.current_native_v1(p_action='ticket');u:=(actor->>'subject')::uuid;
 end if;
 if u is not null and not exists(select 1 from export_private.core_jobs_v1 where request_id=req and owner_id=u) then raise exception 'FORBIDDEN';end if;
 j:=export_private.lock_job_v1(req,p_action not in ('read','ticket','download_prepare','download_consume'));
 if j.request_id is null then
  if p_action='execution_receipt' then return jsonb_build_object('kind','privacy_export_execution_receipt/1','outcome','unknown','receipt',null);end if;
  if p_action='validate' then return jsonb_build_object('kind','privacy_export_lease_state/1','current',false);end if;
  return jsonb_build_object('kind','unavailable');
 end if;
 if u is not null and j.owner_id<>u then raise exception 'FORBIDDEN';end if;
 if p_action='read' then return export_private.job_receipt_v1(j);end if;
 if p_action='execution_receipt' then
  if jsonb_typeof(p_input->'expectedArtifactDigest') is distinct from 'string' or p_input->>'expectedArtifactDigest' !~ '^[a-f0-9]{64}$' then raise exception 'INVALID_INPUT';end if;
  if j.committed_lease=lease and j.generation=gen and j.state in ('ready_partial','ready_complete') and j.artifact_digest=p_input->>'expectedArtifactDigest' and j.artifact_expires_at>clock_timestamp() then return jsonb_build_object('kind','privacy_export_execution_receipt/1','outcome','terminal','receipt',export_private.job_receipt_v1(j));end if;
  if j.committed_lease=lease and j.generation=gen and j.state='failed' then return jsonb_build_object('kind','privacy_export_execution_receipt/1','outcome','terminal','receipt',export_private.job_receipt_v1(j));end if;
  return jsonb_build_object('kind','privacy_export_execution_receipt/1','outcome','unknown','receipt',null);
 end if;
 if p_action='claim' then
  if jsonb_typeof(p_input->'maxRunMs') is distinct from 'number' or p_input->>'maxRunMs' !~ '^[1-9][0-9]{0,4}$' or (p_input->>'maxRunMs')::integer>policy.max_run_ms or (p_input->>'maxRunMs')::integer>90000
  or jsonb_typeof(p_input->'expectedEnvironment') is distinct from 'string' or jsonb_typeof(p_input->'expectedKeyId') is distinct from 'string' or p_input->>'expectedEnvironment' is distinct from policy.environment or p_input->>'expectedKeyId' is distinct from policy.key_id then raise exception 'INVALID_INPUT';end if;run_ms:=(p_input->>'maxRunMs')::integer;
  digest:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
  if j.claim_operation=op then
   if j.claim_digest<>digest then raise exception 'EXPORT_CONFLICT';end if;
   if j.state='running' and j.lease_expires_at>clock_timestamp() then return jsonb_build_object('kind','privacy_export_lease/1','requestId',req,'ownerId',j.owner_id,'leaseId',j.lease_id,'generation',j.generation,'expiresAt',export_private.ms_v1(j.lease_expires_at),'reused',true);end if;
   return jsonb_build_object('kind','unavailable');
  end if;
  if j.expires_at<=clock_timestamp() or j.state not in ('queued','running') or j.state='running' and (j.lease_expires_at>clock_timestamp() or j.generation>=3) then return jsonb_build_object('kind','unavailable');end if;
  update export_private.core_jobs_v1 set generation=case when state='running' then generation+1 else generation end,state='running',claim_operation=op,claim_digest=digest,lease_id=gen_random_uuid(),lease_expires_at=least(clock_timestamp()+run_ms*interval '1 millisecond',expires_at,policy.valid_until) where request_id=req returning * into j;
  return jsonb_build_object('kind','privacy_export_lease/1','requestId',req,'ownerId',j.owner_id,'leaseId',j.lease_id,'generation',j.generation,'expiresAt',export_private.ms_v1(j.lease_expires_at),'reused',false);
 end if;
 if p_action='validate' then return jsonb_build_object('kind','privacy_export_lease_state/1','current',export_private.live_lease_v1(j,lease,gen));end if;
 if p_action='trip_page' then
  if not export_private.live_lease_v1(j,lease,gen) then return jsonb_build_object('kind','unavailable');end if;
  if jsonb_typeof(p_input->'limit') is distinct from 'number' or p_input->>'limit' !~ '^[1-9][0-9]{0,2}$' or (p_input->>'limit')::integer>policy.page_size then raise exception 'INVALID_INPUT';end if;limit_n:=(p_input->>'limit')::integer;
  if p_input->'afterTripId'='null'::jsonb then cursor:=null;
  elsif jsonb_typeof(p_input->'afterTripId')='string' and p_input->>'afterTripId' ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then cursor:=(p_input->>'afterTripId')::uuid;
  else raise exception 'INVALID_INPUT';end if;
  if cursor is not null and not exists(select 1 from public.trips where id=cursor and owner_id=j.owner_id and not exists(select 1 from privacy_private.trip_deletions where trip_id=cursor)) then raise exception 'INVALID_EXPORT_CURSOR';end if;
  if exists(select 1 from public.trips t left join public.trip_version_snapshots s on s.trip_id=t.id and s.version=t.head_version and s.owner_id=t.owner_id where t.owner_id=j.owner_id and (cursor is null or t.id>cursor) and not exists(select 1 from privacy_private.trip_deletions where trip_id=t.id) and (s.trip_id is null or s.title<>t.title) order by t.id limit limit_n+1) then raise exception 'SOURCE_UNAVAILABLE';end if;
  with candidates as (
   select t.id,jsonb_build_object('tripId',t.id,'title',t.title,'headVersion',t.head_version,'confirmationState',case when t.head_version=0 then 'initial' when exists(select 1 from public.trip_events e join public.trip_proposals p on p.id=e.proposal_id and p.owner_id=e.owner_id join public.trip_idempotency r on r.proposal_id=p.id and r.owner_id=p.owner_id and r.resulting_version=e.resulting_version where e.trip_id=t.id and e.owner_id=t.owner_id and e.resulting_version=t.head_version and p.status='applied' and p.base_trip_version+1=t.head_version) then 'confirmed' else 'unknown' end,'content',export_private.trip_content_v1(s.content)) as item
   from public.trips t join public.trip_version_snapshots s on s.trip_id=t.id and s.version=t.head_version and s.owner_id=t.owner_id where t.owner_id=j.owner_id and (cursor is null or t.id>cursor) and not exists(select 1 from privacy_private.trip_deletions where trip_id=t.id) order by t.id limit limit_n+1
  ),delivered as(select * from candidates order by id limit limit_n)
  select coalesce((select jsonb_agg(item order by id) from delivered),'[]'),(select count(*)>limit_n from candidates),(select id from delivered order by id desc limit 1) into page,more,next_id;
  return jsonb_build_object('schemaVersion','trip-core-export/1','section','trips','items',page,'hasMore',more,'nextCursor',case when more then next_id else null end,'sectionComplete',not more);
 end if;
 if p_action='commit' then
  if export_private.memory_commit_progress_v1(j,p_input->'modules',lease,gen) is distinct from true then raise exception 'INVALID_OUTPUT';end if;
  if export_private.entitlement_commit_progress_v1(j,p_input->'modules',lease,gen) is distinct from true then raise exception 'INVALID_OUTPUT';end if;
  if pdf_intake_private.export_commit_v1(j,p_input->'modules',lease,gen) is distinct from true then raise exception 'INVALID_OUTPUT';end if;
  if j.state='running' and export_private.profile_commit_qualifies_v1(j,p_input->'modules',lease,gen) is distinct from true then raise exception 'INVALID_OUTPUT';end if;
  if j.state='running' and export_private.turn_commit_qualifies_v1(j,p_input->'modules',lease,gen) is distinct from true then raise exception 'INVALID_OUTPUT';end if;
  artifact:=p_input->'artifact';
  if jsonb_typeof(artifact) is distinct from 'object' or artifact-array['schemaVersion','keyId','nonce','tag','ciphertext','plaintextDigest','plaintextBytes','expiresAt']<>'{}' or (select count(*) from jsonb_object_keys(artifact))<>8
  or jsonb_typeof(artifact->'keyId') is distinct from 'string' or artifact->>'schemaVersion' is distinct from 'privacy-export-artifact/1' or artifact->>'keyId' is distinct from policy.key_id or jsonb_typeof(artifact->'plaintextDigest') is distinct from 'string' or artifact->>'plaintextDigest' !~ '^[a-f0-9]{64}$'
  or jsonb_typeof(artifact->'plaintextBytes') is distinct from 'number' or artifact->>'plaintextBytes' !~ '^[1-9][0-9]{0,6}$' or (artifact->>'plaintextBytes')::integer>policy.max_bytes
  or turn_private.planning_v2_valid_ms_v1(artifact->'expiresAt') is distinct from true then raise exception 'INVALID_OUTPUT';end if;
  nonce:=export_private.unb64_v1(artifact->>'nonce',12);tag:=export_private.unb64_v1(artifact->>'tag',16);cipher:=export_private.unb64_v1(artifact->>'ciphertext',policy.max_bytes);
  if nonce is null or tag is null or cipher is null or octet_length(nonce)<>12 or octet_length(tag)<>16 or octet_length(cipher)<>(artifact->>'plaintextBytes')::integer then raise exception 'INVALID_OUTPUT';end if;
  if export_private.valid_modules_v1(p_input->'modules',policy.max_pages) is distinct from true then raise exception 'INVALID_OUTPUT';end if;
  select bool_and(m->>'status'='complete') into all_complete from jsonb_array_elements(p_input->'modules') m;
  if p_input->>'coverage' is distinct from (case when all_complete then 'complete' else 'partial' end) then raise exception 'INVALID_OUTPUT';end if;
  digest:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
  if j.state in ('ready_partial','ready_complete') then
   if j.committed_lease=lease and j.generation=gen and j.commit_digest=digest and j.artifact_expires_at>clock_timestamp() then
    if export_private.profile_source_current_v1(j) is distinct from true then raise exception 'INVALID_OUTPUT';end if;
    if export_private.turn_source_current_v1(j) is distinct from true then raise exception 'INVALID_OUTPUT';end if;
    if export_private.directions_source_current_v1(j) is distinct from true then raise exception 'INVALID_OUTPUT';end if;
    return export_private.job_receipt_v1(j);end if;raise exception 'EXPORT_CONFLICT';
  end if;
  if not export_private.live_lease_v1(j,lease,gen) then return jsonb_build_object('kind','unavailable');end if;
  expires:=(artifact->>'expiresAt')::timestamptz;
  if expires<=clock_timestamp() or expires>clock_timestamp()+interval '24 hours' then raise exception 'INVALID_OUTPUT';end if;
  expires:=least(expires,clock_timestamp()+policy.artifact_ttl_ms*interval '1 millisecond',j.expires_at);
  if expires<=clock_timestamp() then return jsonb_build_object('kind','unavailable');end if;
  profile_lease_deadline:=j.lease_expires_at;turn_lease_deadline:=j.lease_expires_at;
  insert into export_private.core_artifacts_v1(request_id,owner_id,generation,lease_id,key_id,nonce,tag,ciphertext,plaintext_digest,plaintext_bytes,ciphertext_digest,aad,expires_at)
   values(req,j.owner_id,gen,lease,policy.key_id,nonce,tag,cipher,artifact->>'plaintextDigest',(artifact->>'plaintextBytes')::integer,encode(sha256(cipher),'hex'),'["privacy-core-export/1",'||turn_private.planning_v2_json_string_v1(req::text)||','||turn_private.planning_v2_json_string_v1(j.owner_id::text)||','||gen::text||']',expires);
  update export_private.core_jobs_v1 set state=case when all_complete then 'ready_complete' else 'ready_partial' end,modules=p_input->'modules',completed_at=clock_timestamp(),artifact_digest=artifact->>'plaintextDigest',artifact_bytes=(artifact->>'plaintextBytes')::integer,artifact_expires_at=expires,committed_lease=lease,commit_digest=digest,lease_id=null,lease_expires_at=null where request_id=req returning * into j;
  perform export_private.record_profile_provenance_v1(j,profile_lease_deadline);
  perform export_private.record_turn_provenance_v1(j,turn_lease_deadline);
  return export_private.job_receipt_v1(j);
 end if;
 if p_action='fail' then
  if p_input->>'reason' not in ('SOURCE_UNAVAILABLE','INVALID_OUTPUT') or p_input->>'reason' is null then raise exception 'INVALID_INPUT';end if;
  if not export_private.live_lease_v1(j,lease,gen) then return jsonb_build_object('kind','unavailable');end if;
