'; end if;\n  if (item#>>''{}'') !~ ''[^[:space:]]'' or length(item#>>''{}'')>240\n   or strpos(source_text,item#>>''{}'')=0 then raise exception ''INVALID_INPUT''; end if;\n end loop;\n if (select count(distinct value) from jsonb_array_elements(needs))<>jsonb_array_length(needs) then raise exception ''INVALID_INPUT''; end if;\n -- The existing completion owns dispatch, current evidence, deadline recheck,\n -- immutable result and terminal event. Both writes commit or roll back together.\n result:=public.complete_grounded_work(p_turn_id,p_lease_token,p_intent,p_request_scope);\n if result->>''kind''=''finished'' then\n  update turn_private.grounded_turns set unanswered_needs=case when request_scope=''additional_needs'' then needs else ''[]''::jsonb end\n   where turn_id=p_turn_id;\n end if;\n return result;\nend ","result":"jsonb","strict":false,"identity":"p_turn_id uuid, p_lease_token uuid, p_intent text, p_request_scope text, p_unanswered_needs text","language":"plpgsql","parallel":"u","arguments":"p_turn_id uuid, p_lease_token uuid, p_intent text, p_request_scope text, p_unanswered_needs text","definition":"CREATE OR REPLACE FUNCTION public.complete_grounded_work_with_needs(p_turn_id uuid, p_lease_token uuid, p_intent text, p_request_scope text, p_unanswered_needs text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare needs jsonb; source_text text; item jsonb; result jsonb;\nbegin\n if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object(''kind'',''blocked'');end if;\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''stale''); end if;\n if p_unanswered_needs is null or octet_length(p_unanswered_needs)>12000 then raise exception ''INVALID_INPUT''; end if;\n needs:=p_unanswered_needs::jsonb;\n if jsonb_typeof(needs)<>''array'' then raise exception ''INVALID_INPUT''; end if;\n if jsonb_array_length(needs)>6 or p_request_scope is null\n  or ((p_request_scope=''additional_needs'') <> (jsonb_array_length(needs)>0)) then raise exception ''INVALID_INPUT''; end if;\n if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object(''kind'',''blocked''); end if;\n select input_text into source_text from turn_private.text_content where turn_id=p_turn_id;\n if source_text is null then return jsonb_build_object(''kind'',''blocked''); end if;\n for item in select value from jsonb_array_elements(needs) loop\n  if jsonb_typeof(item)<>''string'' then raise exception ''INVALID_INPUT''; end if;\n  if (item#>>''{}'') !~ ''[^[:space:]]'' or length(item#>>''{}'')>240\n   or strpos(source_text,item#>>''{}'')=0 then raise exception ''INVALID_INPUT''; end if;\n end loop;\n if (select count(distinct value) from jsonb_array_elements(needs))<>jsonb_array_length(needs) then raise exception ''INVALID_INPUT''; end if;\n -- The existing completion owns dispatch, current evidence, deadline recheck,\n -- immutable result and terminal event. Both writes commit or roll back together.\n result:=public.complete_grounded_work(p_turn_id,p_lease_token,p_intent,p_request_scope);\n if result->>''kind''=''finished'' then\n  update turn_private.grounded_turns set unanswered_needs=case when request_scope=''additional_needs'' then needs else ''[]''::jsonb end\n   where turn_id=p_turn_id;\n end if;\n return result;\nend $function$\n","volatility":"v","securityDefiner":true},"public.complete_planning_observation_v1(uuid,uuid,uuid,text,jsonb)":{"acl":"{postgres=X/postgres,service_role=X/postgres}","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare w turn_private.work%rowtype; a turn_private.planning_action_receipts%rowtype; existing turn_private.planning_observations%rowtype;\n  policy_environment text; digest text;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''stale''); end if;\n  if (select auth.role())<>''service_role'' or p_turn_id is null or p_owner_id is null or p_lease_token is null\n    or p_action_key !~ ''^[a-f0-9]{64}$'' or p_observation is null or octet_length(p_observation::text)>8192\n    then raise exception ''INVALID_INPUT''; end if;\n  select * into w from turn_private.work where turn_id=p_turn_id and owner_id=p_owner_id;\n  if not found or not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object(''kind'',''stale''); end if;\n  select * into w from turn_private.work where turn_id=p_turn_id for update;\n  if w.execution_mode<>''planning_comparison_v1'' or w.state<>''leased'' or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp()\n    then return jsonb_build_object(''kind'',''stale''); end if;\n  select * into a from turn_private.planning_action_receipts where turn_id=p_turn_id and action_key=p_action_key for update;\n  if not found or a.owner_id<>p_owner_id or a.lease_token<>p_lease_token or not turn_private.valid_planning_observation_v1(a.tool_id,p_observation)\n    then return jsonb_build_object(''kind'',''blocked''); end if;\n  if a.tool_id=''place.read'' then\n    select p.environment into policy_environment from turn_private.planning_comparisons j\n      join turn_private.planning_policies p on p.id=j.planning_policy_id where j.turn_id=p_turn_id;\n    if policy_environment is null or (p_observation->>''source''=''synthetic_fixture'') is distinct from (policy_environment=''local_synthetic'')\n      then return jsonb_build_object(''kind'',''blocked''); end if;\n  end if;\n  if turn_private.planning_action_basis(p_turn_id,p_owner_id,a.message_id,a.memory_basis) is distinct from a.basis_digest\n    then return jsonb_build_object(''kind'',''stale_basis''); end if;\n  digest:=encode(pg_catalog.sha256(convert_to(p_observation::text,''UTF8'')),''hex'');\n  if a.state=''completed'' then\n    select * into existing from turn_private.planning_observations where turn_id=p_turn_id and action_key=p_action_key;\n    return jsonb_build_object(''kind'',case when a.receipt_digest=digest and existing.observation=p_observation then ''duplicate'' else ''conflict'' end);\n  end if;\n  if a.state<>''started'' then return jsonb_build_object(''kind'',''unknown''); end if;\n  insert into turn_private.planning_observations(turn_id,action_key,owner_id,observation)\n    values(p_turn_id,p_action_key,p_owner_id,p_observation);\n  update turn_private.planning_action_receipts set state=''completed'',receipt_digest=digest,updated_at=clock_timestamp()\n    where turn_id=p_turn_id and action_key=p_action_key;\n  return jsonb_build_object(''kind'',''completed'',''receiptDigest'',digest);\nend ","result":"jsonb","strict":false,"identity":"p_turn_id uuid, p_owner_id uuid, p_lease_token uuid, p_action_key text, p_observation jsonb","language":"plpgsql","parallel":"u","arguments":"p_turn_id uuid, p_owner_id uuid, p_lease_token uuid, p_action_key text, p_observation jsonb","definition":"CREATE OR REPLACE FUNCTION public.complete_planning_observation_v1(p_turn_id uuid, p_owner_id uuid, p_lease_token uuid, p_action_key text, p_observation jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare w turn_private.work%rowtype; a turn_private.planning_action_receipts%rowtype; existing turn_private.planning_observations%rowtype;\n  policy_environment text; digest text;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''stale''); end if;\n  if (select auth.role())<>''service_role'