   return jsonb_build_object(''kind'',case when a.receipt_digest=digest and existing.observation=p_observation then ''duplicate'' else ''conflict'' end);\n  end if;\n  if a.state<>''started'' then return jsonb_build_object(''kind'',''unknown''); end if;\n  insert into turn_private.planning_observations(turn_id,action_key,owner_id,observation)\n    values(p_turn_id,p_action_key,p_owner_id,p_observation);\n  update turn_private.planning_action_receipts set state=''completed'',receipt_digest=digest,updated_at=clock_timestamp()\n    where turn_id=p_turn_id and action_key=p_action_key;\n  return jsonb_build_object(''kind'',''completed'',''receiptDigest'',digest);\nend $function$\n","volatility":"v","securityDefiner":true},"public.assistant_conversation_export_owner_v1(uuid,text,uuid,integer)":{"acl":"{postgres=X/postgres,service_role=X/postgres}","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare page jsonb; more boolean; cursor uuid;\nbegin\n  if p_section in(''directionIntakes'',''directionSources'',''directionOperations'') then return turn_private.directions_export_page_v1(p_owner,p_section,p_after_id,p_limit);end if;\n  if (select auth.role()) is distinct from ''service_role'' or p_owner is null then\n    raise exception ''FORBIDDEN'';\n  end if;\n  if p_section is null or p_section not in (''conversations'',''goals'',''messages'',''goalTripLinks'',''goalTripReceipts'')\n    or p_limit is null or p_limit not between 1 and 100 then raise exception ''INVALID_INPUT''; end if;\n  -- Deleted, unknown and foreign-owner anchors uniformly require an export restart.\n  if p_after_id is not null and not exists(\n    select 1 from turn_private.assistant_conversations where p_section=''conversations'' and owner_id=p_owner and id=p_after_id\n    union all\n    select 1 from turn_private.assistant_goals where p_section=''goals'' and owner_id=p_owner and id=p_after_id\n    union all\n    select 1 from turn_private.assistant_messages where p_section=''messages'' and owner_id=p_owner and id=p_after_id\n    union all\n    select 1 from turn_private.assistant_goal_trip_links where p_section=''goalTripLinks'' and owner_id=p_owner and goal_id=p_after_id\n    union all\n    select 1 from turn_private.assistant_goal_trip_receipts where p_section=''goalTripReceipts'' and owner_id=p_owner and operation_id=p_after_id\n  ) then raise exception ''INVALID_EXPORT_CURSOR''; end if;\n  with candidates as (\n    (select id as id,jsonb_build_object(\n      ''conversationId'',id,''policyId'',policy_id,\n      ''consentId'',consent_id,''nextSequence'',next_sequence,\n      ''createdAt'',created_at) as item\n      from turn_private.assistant_conversations\n      where p_section=''conversations'' and owner_id=p_owner\n        and id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or id>p_after_id)\n      order by id limit p_limit+1)\n    union all\n    (select id as id,jsonb_build_object(\n      ''goalId'',id,''conversationId'',conversation_id,\n      ''scopeVersion'',scope_version,''text'',current_text,\n      ''tripTerminal'',trip_terminal,''createdAt'',created_at) as item\n      from turn_private.assistant_goals\n      where p_section=''goals'' and owner_id=p_owner\n        and id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or id>p_after_id)\n      order by id limit p_limit+1)\n    union all\n    (select id as id,jsonb_build_object(\n      ''messageId'',id,''conversationId'',conversation_id,\n      ''sequence'',sequence,''policyId'',policy_id,\n      ''consentId'',consent_id,''locale'',locale,\n      ''text'',input_text,''relationship'',relationship,\n      ''goalId'',goal_id,''scopeVersion'',scope_version,\n      ''taskId'',task_id,''parentMessageId'',parent_message_id,\n      ''turnId'',turn_id,''createdAt'',created_at) as item\n      from turn_private.assistant_messages\n      where p_section=''messages'' and owner_id=p_owner\n        and id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or id>p_after_id)\n      order by id limit p_limit+1)\n    union all\n    (select goal_id as id,jsonb_build_object(\n      ''goalId'',goal_id,''conversationId'',conversation_id,\n      ''linkVersion'',link_version,''goalScopeVersion'',goal_scope_version,\n      ''lastOperationId'',operation_id,''terminalUnlinked'',terminal_unlinked,\n      ''tripId'',trip_id,''tripHeadVersion'',trip_head_version,\n      ''sourceMessageId'',source_message_id,''updatedAt'',updated_at) as item\n      from turn_private.assistant_goal_trip_links\n      where p_section=''goalTripLinks'' and owner_id=p_owner\n        and goal_id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or goal_id>p_after_id)\n      order by goal_id limit p_limit+1)\n    union all\n    (select operation_id as id,jsonb_build_object(\n      ''operationId'',operation_id,''goalId'',goal_id,\n      ''action'',action,''sourceKind'',source_kind,\n      ''sourceMessageId'',source_message_id,''beforeLinkVersion'',before_link_version,\n      ''afterLinkVersion'',after_link_version,''beforeGoalScopeVersion'',before_goal_scope_version,\n      ''afterGoalScopeVersion'',after_goal_scope_version,''tripId'',trip_id,\n      ''tripHeadVersion'',trip_head_version,''createdAt'',created_at) as item\n      from turn_private.assistant_goal_trip_receipts\n      where p_section=''goalTripReceipts'' and owner_id=p_owner\n        and operation_id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or operation_id>p_after_id)\n      order by operation_id limit p_limit+1)\n  ), page_window as (\n    select id,item from candidates order by id limit p_limit+1\n  ), delivered as (\n    select id,item from page_window order by id limit p_limit\n  )\n  select coalesce((select jsonb_agg(item order by id) from delivered),''[]''::jsonb),\n    (select count(*)>p_limit from page_window),\n    (select id from delivered order by id desc limit 1)\n    into page,more,cursor;\n  return jsonb_build_object(''schemaVersion'',''assistant-conversation-export/1'',\n    ''section'',p_section,''items'',page,''hasMore'',more,\n    ''nextCursor'',case when more then cursor else null end,''sectionComplete'',not more);\nend ","result":"jsonb","strict":false,"identity":"p_owner uuid, p_section text, p_after_id uuid, p_limit integer","language":"plpgsql","parallel":"u","arguments":"p_owner uuid, p_section text, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100","definition":"CREATE OR REPLACE FUNCTION public.assistant_conversation_export_owner_v1(p_owner uuid, p_section text, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare page jsonb; more boolean; cursor uuid;\nbegin\n  if p_section in(''directionIntakes'',''directionSources'',''directionOperations'') then return turn_private.directions_export_page_v1(p_owner,p_section,p_after_id,p_limit);end if;\n  if (select auth.role()) is distinct from ''service_role'' or p_owner is null then\n    raise exception ''FORBIDDEN'';\n  end if;\n  if p_section is null or p_section not in (''conversations'',''goals'',''messages'',''goalTripLinks'',''goalTripReceipts'')\n    or p_limit is null or p_limit not between 1 and 100 then raise exception ''INVALID_INPUT''; end if;\n  -- Deleted, unknown and foreign-owner anchors uniformly require an export restart.\n  if p_after_id is not null and not exists(\n    select 1 from turn_private.assistant_conversations where p_section=''conversations'' and owner_id=p_owner and id=p_after_id\n    union all\n    select 1 from turn_private.assistant_goals where p_section=''goals'' and owner_id=p_owner and id=p_after_id\n    union all\n    select 1 from turn_private.assistant_messages where p_section=''messages'' and owner_id=p_owner and id=p_after_id\n    union all\n    select 1 from turn_private.assistant_goal_trip_links where p_section=''goalTripLinks'' and owner_id=p_owner and goal_id=p_after_id\n    union all\n    select 1 from turn_private.assistant_goal_trip_receipts where p_section=''goalTripReceipts'' and owner_id=p_owner and operation_id=p_after_id\n  ) then raise exception ''INVALID_EXPORT_CURSOR''; end if;\n  with candidates as (\n    (select id as id,jsonb_build_object(\n      ''conversationId'',id,''policyId'',policy_id,\n      ''consentId'',consent_id,''nextSequence'',next_sequence,\n      ''createdAt'',created_at) as item\n      from turn_private.assistant_conversations\n      where p_section=''conversations'' and owner_id=p_owner\n        and id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or id>p_after_id)\n      order by id limit p_limit+1)\n    union all\n    (select id as id,jsonb_build_object(\n      ''goalId'',id,''conversationId'',conversation_id,\n      ''scopeVersion'',scope_version,''text'',current_text,\n      ''tripTerminal'',trip_terminal,''createdAt'',created_at) as item\n      from turn_private.assistant_goals\n      where p_section=''goals'' and owner_id=p_owner\n        and id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or id>p_after_id)\n      order by id limit p_limit+1)\n    union all\n    (select id as id,jsonb_build_object(\n      ''messageId'',id,''conversationId'',conversation_id,\n      ''sequence'',sequence,''policyId'',policy_id,\n      ''consentId'',consent_id,''locale'',locale,\n      ''text'',input_text,''relationship'',relationship,\n      ''goalId'',goal_id,''scopeVersion'',scope_version,\n      ''taskId'',task_id,''parentMessageId'',parent_message_id,\n      ''turnId'',turn_id,''createdAt'',created_at) as item\n      from turn_private.assistant_messages\n      where p_section=''messages'' and owner_id=p_owner\n        and id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or id>p_after_id)\n      order by id limit p_limit+1)\n    union all\n    (select goal_id as id,jsonb_build_object(\n      ''goalId'',goal_id,''conversationId'',conversation_id,\n      ''linkVersion'',link_version,''goalScopeVersion'',goal_scope_version,\n      ''lastOperationId'',operation_id,''terminalUnlinked'',terminal_unlinked,\n      ''tripId'',trip_id,''tripHeadVersion'',trip_head_version,\n      ''sourceMessageId'',source_message_id,''updatedAt'',updated_at) as item\n      from turn_private.assistant_goal_trip_links\n      where p_section=''goalTripLinks'' and owner_id=p_owner\n        and goal_id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or goal_id>p_after_id)\n      order by goal_id limit p_limit+1)\n    union all\n    (select operation_id as id,jsonb_build_object(\n      ''operationId'',operation_id,''goalId'',goal_id,\n      ''action'',action,''sourceKind'',source_kind,\n      ''sourceMessageId'',source_message_id,''beforeLinkVersion'',before_link_version,\n      ''afterLinkVersion'',after_link_version,''beforeGoalScopeVersion'',before_goal_scope_version,\n      ''afterGoalScopeVersion'',after_goal_scope_version,''tripId'',trip_id,\n      ''tripHeadVersion'',trip_head_version,''createdAt'',created_at) as item\n      from turn_private.assistant_goal_trip_receipts\n      where p_section=''goalTripReceipts'' and owner_id=p_owner\n        and operation_id>=coalesce(p_after_id,''00000000-0000-0000-0000-000000000000''::uuid)\n        and (p_after_id is null or operation_id>p_after_id)\n      order by operation_id limit p_limit+1)\n  ), page_window as (\n    select id,item from candidates order by id limit p_limit+1\n  ), delivered as (\n    select id,item from page_window order by id limit p_limit\n  )\n  select coalesce((select jsonb_agg(item order by id) from delivered),''[]''::jsonb),\n    (select count(*)>p_limit from page_window),\n    (select id from delivered order by id desc limit 1)\n    into page,more,cursor;\n  return jsonb_build_object(''schemaVersion'',''assistant-conversation-export/1'',\n    ''section'',p_section,''items'',page,''hasMore'',more,\n    ''nextCursor'',case when more then cursor else null end,''sectionComplete'',not more);\nend $function$\n","volatility":"s","securityDefiner":true},"public.claim_planning_action_v1(uuid,uuid,uuid,uuid,text,text,text,jsonb)":{"acl":"{postgres=X/postgres,service_role=X/postgres}","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare w turn_private.work%rowtype; prior turn_private.planning_action_receipts%rowtype;\n  basis text; v_task_id uuid;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''stale''); end if;\n  if (select auth.role())<>''service_role'' or p_action_key !~ ''^[a-f0-9]{64}$''\n    or p_input_digest !~ ''^[a-f0-9]{64}$''\n    or p_tool_id not in (''evidence.lookup'',''place.read'',''constraints.evaluate'',''result.prepare'')\n    or p_turn_id is null or p_owner_id is null or p_lease_token is null or p_message_id is null\n    then raise exception ''INVALID_INPUT''; end if;\n  select * into w from turn_private.work where turn_id=p_turn_id and owner_id=p_owner_id;\n  if not found or not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object(''kind'',''stale''); end if;\n  select * into w from turn_private.work where turn_id=p_turn_id for update;\n  if w.state<>''leased'' or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp()\n    or not exists(select 1 from public.turns t where t.id=p_turn_id and t.owner_id=p_owner_id and t.status=''accepted'')\n    then return jsonb_build_object(''kind'',''stale''); end if;\n  basis:=turn_private.planning_action_basis(p_turn_id,p_owner_id,p_message_id,p_memory_basis);\n  if basis is null then return jsonb_build_object(''kind'',''stale_basis''); end if;\n  select m.task_id into v_task_id from turn_private.assistant_messages m where m.id=p_message_id;\n  select * into prior from turn_private.planning_action_receipts where turn_id=p_turn_id and action_key=p_action_key;\n  if found then\n    if prior.owner_id<>p_owner_id or prior.task_id<>v_task_id or prior.message_id<>p_message_id\n      or prior.tool_id<>p_tool_id or prior.input_digest<>p_input_digest or prior.basis_digest<>basis\n      then return jsonb_build_object(''kind'',''conflict''); end if;\n    return jsonb_build_object(''kind'',case when prior.state=''completed'' then ''duplicate'' else ''unknown'' end,\n      ''receiptDigest'',prior.receipt_digest);\n  end if;\n  -- A dispatched/pending model charge, or a prior action without a durable\n  -- completion receipt, requires reconciliation before any new effect.\n  if exists(select 1 from public.model_budget_attempts a where a.task_id in (v_task_id,p_turn_id)\n    and a.status in (''dispatched'',''pending''))\n    or exists(select 1 from turn_private.planning_action_receipts a where a.turn_id=p_turn_id and a.state in (''started'',''unknown''))\n    then return jsonb_build_object(''kind'',''unknown''); end if;\n  if (select count(*) from turn_private.planning_action_receipts where task_id=v_task_id)>=4\n    then return jsonb_build_object(''kind'',''step_limit''); end if;\n  insert into turn_private.planning_action_receipts(turn_id,action_key,owner_id,task_id,message_id,lease_token,tool_id,input_digest,basis_digest,memory_basis,state)\n    values(p_turn_id,p_action_key,p_owner_id,v_task_id,p_message_id,p_lease_token,p_tool_id,p_input_digest,basis,p_memory_basis,''started'');\n  return jsonb_build_object(''kind'',''claimed'');\nend ","result":"jsonb","strict":false,"identity":"p_turn_id uuid, p_owner_id uuid, p_lease_token uuid, p_message_id