''\nAS $function$\ndeclare i turn_private.assistant_directions_intakes_v1%rowtype;\n m turn_private.assistant_messages%rowtype;g turn_private.assistant_goals%rowtype;\n a turn_private.assistant_conversations%rowtype;t turn_private.service_tasks%rowtype;\n w turn_private.work%rowtype;memories_n jsonb;\nbegin\n select * into i from turn_private.assistant_directions_intakes_v1 where message_id=source_n and owner_id=u;\n if not found then return null;end if;\n select * into m from turn_private.assistant_messages where id=i.message_id and owner_id=u;\n select * into g from turn_private.assistant_goals where id=i.goal_id and owner_id=u;\n select * into a from turn_private.assistant_conversations where id=i.conversation_id and owner_id=u;\n select * into t from turn_private.service_tasks where id=i.task_id and owner_id=u;\n select * into w from turn_private.work where turn_id=i.task_turn_id and owner_id=u;\n if m.id is null or g.id is null or a.id is null or t.id is null or w.turn_id is null\n  or m.conversation_id<>a.id or m.goal_id<>g.id or g.conversation_id<>a.id\n  or m.task_id is distinct from t.id or t.last_turn_id<>i.task_turn_id\n  or m.sequence<>i.message_sequence or m.scope_version<>i.goal_version\n  or g.scope_version<>i.goal_version or g.trip_terminal\n  or m.policy_id<>i.policy_id or a.policy_id<>i.policy_id or t.policy_id<>i.policy_id\n  or m.consent_id<>i.consent_id or a.consent_id<>i.consent_id or t.consent_id<>i.consent_id\n  or w.execution_mode<>''travel_directions_v1'' or w.state in(''cancelled'',''quarantined'')\n  or not exists(select 1 from turn_private.text_content c where c.turn_id=i.task_turn_id and c.owner_id=u and c.hidden_at is null and c.policy_id=i.policy_id and c.consent_id=i.consent_id)\n  or not exists(select 1 from turn_private.service_task_turns l where l.turn_id=i.task_turn_id and l.task_id=i.task_id and l.owner_id=u)\n  or not turn_private.text_policy_current(i.policy_id)\n  or not exists(select 1 from turn_private.text_consents c where