  select jsonb_build_object('owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'acl',c.relacl::text,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))order by a.attnum)from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated)order by k.conname),'[]')from pg_constraint k where k.conrelid=c.oid),'triggers',(select coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text)order by t.tgname),'[]')from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal)) into actual_n from pg_class c where c.oid=to_regclass(spec.key);
  if actual_n is distinct from spec.value then raise exception 'DIRECTIONS_AFTER_TABLE_MISMATCH %',spec.key;end if;
 end loop;
